Object.assign(window.TEM8_DICTIONARY, {"marketable":{"media":{"uk":"media/uk/marketable__gb_1.mp3","us":"media/us/marketable__us_1.mp3"},"oxford":{"phon":"ˈmɑːkɪtəbl","pos":"adjective","senses":[{"en":"easy to sell; attractive to customers or employers","cn":"容易出售的；畅销的；有销路的","ex":{"en":"marketable products/skills/qualifications","cn":"受欢迎的产品／技能／资历"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有市场的;有销路的;适销的","en":"Something that is marketable is able to be sold because people want to buy it.","ex":{"en":"...telling them how to turn their prize research projects into marketable products.","cn":"告诉他们如何把他们的获奖研究项目转化为适销产品"}}]},"examples":[{"en":"marketable products/skills/qualifications","cn":"受欢迎的产品/技能/条件"},{"en":"The program is designed to provide students with real, marketable skills.","cn":"本计划旨在让学生掌握符合市场需求的真正技能。"}]},"mad":{"media":{"uk":"media/uk/mad__gb_1.mp3","us":"media/us/mad__us_1.mp3"},"oxford":{"phon":"mæd","pos":"adjective","senses":[{"en":"very stupid; not at all sensible","cn":"极愚蠢的；很不明智的","lab":"especially British English, informal，，","ex":{"en":"You must be mad to risk it.","cn":"你去冒这种风险，简直是疯了。"}},{"en":"having a mental illness that makes somebody unable to think or behave normally","cn":"精神失常的；精神错乱的","lab":"especially British English, often offensive，，","ex":{"en":"They realized that he had gone mad.","cn":"他们意识到他疯了。"}},{"en":"very angry","cn":"很生气；气愤","g":"[not before noun]","lab":"especially North American English, informal，，","ex":{"en":"He got mad and walked out.","cn":"他大动肝火，愤然离去。"}},{"en":"liking something/somebody very much; very interested in something","cn":"（对…）痴迷，迷恋；特别喜欢","g":"[not usually before noun]","lab":"British English, informal，，","ex":{"en":"He's always been mad about kids.","cn":"他一向特别喜欢孩子。"}},{"en":"done without thought or control; wild and excited","cn":"不理智的；疯狂的；激动的","lab":"British English","ex":{"en":"The crowd made a mad rush for the exit.","cn":"人群疯狂地冲向出口处。"}},{"en":"suffering from rabies","cn":"患狂犬病的","ex":{"en":"A revolver is the only way to stop a mad dog.","cn":"左轮手枪是阻止疯狗的唯一方法。"}},{"en":"great","cn":"极好的","lab":"North American English, informal，，","ex":{"en":"Love him or hate him, the man's got mad skills.","cn":"不管你爱他还是恨他，他的技术绝了。"}},{"en":"a US humorous magazine, first published in 1952. It uses a cartoon style to make fun of films, advertisements, etc., and to make well-known people look silly. It usually has on its cover a picture of the imaginary character Alfred E Neuman, who has a wide face and a stupid smile and says ‘What, me worry?’","cn":"美国幽默杂志，最早于1952年出版。它使用卡通风格来取笑电影，广告等，并使知名人士看起来很傻。它的封面上通常是假想人物阿尔弗雷德·伊·诺伊曼（Alfred E Neuman）的照片，他的脸庞宽阔，表情愚蠢，说：“我担心什么？”","pos":""}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"疯狂的;精神错乱的","en":"Someone who is mad has a mind that does not work in a normal way, with the result that their behaviour is very strange.","ex":{"en":"She was afraid of going mad.","cn":"她担心自己会疯掉。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愚蠢无比的","en":"You use mad to describe people or things that you think are very foolish.","ex":{"en":"You'd be mad to work with him again","cn":"你要再和他一起工作那简直是疯了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"愤怒的;异常恼火的","en":"If you say that someone is mad, you mean that they are very angry.","ex":{"en":"You're just mad at me because I don't want to go","cn":"因为我不想去，你就对我火冒三丈。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"着迷的;迷恋的","en":"If you are mad about or mad on something or someone, you like them very much indeed.","ex":{"en":"She's not as mad about sport as I am","cn":"她不像我对体育那么痴迷。"}},{"pos":"ADJ 形容词","cn":"发狂的;失控的","en":"Mad behaviour is wild and uncontrolled.","ex":{"en":"You only have an hour to complete the game so it's a mad dash against the clock","cn":"你只有一个小时来完成这场比赛，所以得铆足劲头争分夺秒。"}},{"pos":"PHRASE 短语","cn":"使发狂;惹…发怒","en":"If you say that someone or something drives you mad, you mean that you find them extremely annoying.","ex":{"en":"There are certain things he does that drive me mad","cn":"他的某些举动让我很生气。"}},{"pos":"PHRASE 短语","cn":"拼命地;全力以赴地","en":"If you do something like mad, you do it very energetically or enthusiastically.","ex":{"en":"He was weight training like mad.","cn":"他在拼命地进行负重训练。"}},{"pos":"See also:","cn":"","en":"mad keen→see: ;"}]},"examples":[{"en":"‘I'm going to buy some new clothes.’ ‘Well, don't go mad (= spend more than is sensible). ’ “","cn":"我要去买几件新衣服。” “去吧，可别乱花钱。”"},{"en":"No one in their right mind would choose to work there.","cn":"任何一个精神正常的人都不会选择去那里工作。"}]},"management":{"media":{"uk":"media/uk/management__gb_1.mp3","us":"media/us/management__us_1.mp3"},"oxford":{"phon":"ˈmænɪdʒmənt","pos":"noun","senses":[{"en":"the activity of running and controlling a business or similar organization","cn":"经营；管理","g":"[uncountable]","ex":{"en":"a career in management","cn":"管理方面的职业"}},{"en":"the people who run and control a business or similar organization","cn":"经营者；管理部门；资方","g":"[countable + singular or plural verb, uncountable]","ex":{"en":"The management is/are considering closing the factory.","cn":"经营者在考虑关闭这家工厂。"}},{"en":"the act or skill of dealing with people or situations in a successful way","cn":"（成功的）处理手段；（有效的）处理能力","g":"[uncountable]","ex":{"en":"classroom management","cn":"课堂组织能力"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（商务或机构的）管理，经营","en":"Management is the control and organizing of a business or other organization.","ex":{"en":"The zoo needed better management rather than more money","cn":"这座动物园需要更好的管理，而不是更多的资金。"}},{"pos":"N-VAR-COLL 可变集合名词","cn":"资方;管理部门;经营者","en":"You can refer to the people who control and organize a business or other organization as the management .","ex":{"en":"The management is doing its best to improve the situation","cn":"管理部门正在竭尽全力改善局面。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"管理;安排;驾驭","en":"Management is the way people control different parts of their lives.","ex":{"en":"...her management of her professional life.","cn":"她对自己职业生涯的规划"}}]},"examples":[{"en":"My role is to act as a mediator between employees and management.","cn":"我的角色就是协调雇员与管理者之间的关系。"},{"en":"Most managements are keen to avoid strikes.","cn":"大多数经营者都很希望避免罢工的发生。"}]},"markers":{"oxford":{"phon":"ˈmɑːkə(r)","pos":"noun","senses":[{"en":"an object or a sign that shows the position of sth （","cn":"表示方位的）标记，记号"},{"en":"a sign that sth exists or that shows what it is like","cn":"标志；标识；表示"}]}},"matches":{"oxford":{"phon":"mætʃ","pos":"noun","senses":[{"en":"a small stick made of wood or cardboard that is used for lighting a fire, cigarette, etc.","cn":"火柴"},{"en":"( especially BrE ) a sports event where people or teams compete against each other","cn":"比赛；竞赛"}]},"media":{"uk":"media/uk/match__gb_1.mp3","us":"media/us/match__us_1.mp3"}},"magnetism":{"oxford":{"phon":"ˈmæɡnətɪzəm","pos":"noun","senses":[{"en":"a physical property (= characteristic) of some metals such as iron, produced by electric currents, that causes forces between objects, either pulling them towards each other or pushing them apart","cn":"磁性；磁力","ex":{"en":"The magnetism produced by the battery attracts the metal.","cn":"电池产生的磁力能够吸引金属。"}},{"en":"the qualities of something, especially a person’s character, that people find powerful and attractive","cn":"吸引力；魅力","ex":{"en":"She exudes sexual magnetism.","cn":"她洋溢着性感的魅力。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"魅力;吸引力","en":"Someone or something that has magnetism has unusual, powerful, and exciting qualities which attract people to them.","ex":{"en":"There was no doubting the animal magnetism of the man","cn":"毫无疑问，这个男人身上透着一种野性魅力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"磁性;磁力","en":"Magnetism is the natural power of some objects and substances, especially iron, to attract other objects towards them."}]},"media":{"uk":"media/uk/magnetism__gb_1.mp3","us":"media/us/magnetism__us_1.mp3"},"examples":[{"en":"She exudes sexual magnetism.","cn":"她洋溢着女性的魅力。"},{"en":"his personal magnetism","cn":"他的个人魅力"}]},"makeup":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"化妆品","en":"Make-up consists of things such as lipstick, eye shadow, and powder which some women put on their faces to make themselves look more attractive or which actors use to change or improve their appearance.","ex":{"en":"Normally she wore little make-up","cn":"她一般不怎么化妆。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"天性;性格","en":"Some-one's make-up is their nature and the various qualities in their character.","ex":{"en":"There was some fatal flaw in his makeup, and as time went on he lapsed into long silences or became off-hand.","cn":"他的性格有致命的缺陷，随着时间的推移，他陷入了久久的沉默，或者变得漠然。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"组成成分;构成方式","en":"The make-up of something consists of its different parts and the way these parts are arranged.","ex":{"en":"The ideological make-up of the unions is now radically different from what it had been.","cn":"协会的思想观念与过去截然不同。"}}]},"media":{"img":["media/pic/makeup_comp.jpg"]}},"mastering":{"oxford":{"phon":"ˈmɑːstə(r)","pos":"noun","senses":[{"en":"( old-fashioned ) a man who has people working for him, often as servants in his home （","cn":"男）主人，雇主"},{"en":"a person who is able to control sth","cn":"主宰；主人；有控制力的人"}]},"media":{"uk":"media/uk/master__gb_1.mp3","us":"media/us/master__us_1.mp3"}},"mar":{"media":{"uk":"media/uk/mar__gb_1.mp3","us":"media/us/mar__us_1.mp3"},"oxford":{"phon":"mɑː(r)","pos":"verb","senses":[{"en":"to damage something or make something less good or successful","cn":"破坏；毁坏；损毁；损害","ex":{"en":"The game was marred by the behaviour of drunken fans.","cn":"喝醉了的球迷行为不轨，把比赛给搅了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"破坏;损坏;毁坏","en":"To mar something means to spoil or damage it.","ex":{"en":"A number of problems marred the smooth running of this event","cn":"许多问题影响了这件事的顺利进行。"}}]},"examples":[{"en":"The game was marred by the behaviour of drunken fans.","cn":"喝醉了的球迷行为不轨，把比赛给搅了。"},{"en":"Their wedding was marred by the death of Jenny’s mother a week earlier.","cn":"一周之前珍妮母亲的过世使他们的婚礼蒙上了一层阴影。"}]},"marking":{"oxford":{"phon":"ˈmɑːkɪŋ","pos":"noun","senses":[{"en":"a pattern of colours or marks on animals, birds or wood","cn":"（兽类、鸟类或树木的）斑纹，花纹，斑点","g":"[countable, usually plural]","ex":{"en":"The female fish is bright yellow with black markings.","cn":"雌鱼呈亮黄色，有黑色斑纹。"}},{"en":"lines, colours or shapes painted on roads, vehicles, etc.","cn":"（刷在道路、车辆等上的）线条，颜色，形状","g":"[countable, usually plural]","ex":{"en":"Road markings indicate where you can stop.","cn":"道路标志告诉你哪里可以停车。"}},{"en":"the activity of checking and correcting the written work or exam papers of students","cn":"批改；打分；阅卷","g":"[uncountable]","lab":"especially British English","ex":{"en":"She does her marking in the evenings.","cn":"她晚上批改作业。"}},{"en":"the practice of staying close to a player on the other team in order to stop them getting the ball","cn":"盯人防守","g":"[uncountable]","ex":{"en":"England gave away a goal because of their slack marking at corners.","cn":"英格兰队因为角球防守不严而丢掉了一球。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"标识;标志;斑纹","en":"Markings are coloured lines, shapes, or patterns on the surface of something, which help to identify it.","ex":{"en":"A plane with Danish markings was overflying his vessel","cn":"一架带有丹麦标记的飞机从他的船上空飞过。"}}]},"media":{"uk":"media/uk/marking__gb_1.mp3","us":"media/us/marking__us_1.mp3"},"examples":[{"en":"Road markings indicate where you can stop.","cn":"道路标志告诉你哪里可以停车。"},{"en":"She does her marking in the evenings.","cn":"她晚上批改作业。"}]},"markedly":{"oxford":{"phon":"ˈmɑːkɪdli","pos":"adverb","senses":[{"en":"in a way that is easy to notice","cn":"醒目地；明显感觉得到地；浓烈地；强烈地","ex":{"en":"Her background is markedly different from her husband's.","cn":"她的出身和她丈夫迥异。"}}]},"media":{"uk":"media/uk/markedly__gb_1.mp3","us":"media/us/markedly__us_1.mp3"},"examples":[{"en":"Her background is markedly different from her husband's.","cn":"她的背景和她丈夫的截然不同。"},{"en":"This year's sales have risen markedly.","cn":"今年的销售额明显提高了。"}]},"marked":{"media":{"uk":"media/uk/marked__gb_1.mp3","us":"media/us/marked__us_1.mp3"},"oxford":{"phon":"mɑːkt","pos":"adjective","senses":[{"en":"easy to see","cn":"显而易见的；明显的；显著的","ex":{"en":"a marked difference/improvement","cn":"明显的差异／进步"}},{"en":"showing a particular feature or style, such as being formal or informal","cn":"有标记成分的（如正式或非正式用语）","lab":"linguistics"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（改变或区别）显著的，显而易见的","en":"A marked change or difference is very obvious and easily noticed.","ex":{"en":"There has been a marked increase in crimes against property","cn":"侵财案件明显增加了。"}},{"pos":"ADJ 形容词","cn":"成为攻击对象的;处境危险的","en":"If you describe someone as a marked man or woman, you mean that they are in danger from someone who wants to harm or kill them.","ex":{"en":"All he needs to do is make one phone call and I'm a marked man.","cn":"他只消打一个电话，我就大难临头了。"}}]},"examples":[{"en":"She is quiet and studious, in marked contrast to her sister.","cn":"她沉静勤奋，与她妹妹形成了鲜明的对照。"},{"en":"Her background is markedly different from her husband's.","cn":"她的背景和她丈夫的截然不同。"}]},"market":{"media":{"uk":"media/uk/market__gb_1.mp3","us":"media/us/market__us_1.mp3"},"oxford":{"phon":"ˈmɑːkɪt","pos":"noun","senses":[{"en":"an occasion when people buy and sell goods; the open area or building where they meet to do this","cn":"集市；市场；商场","g":"[countable]","ex":{"en":"a fruit/flower/fish market","cn":"水果／鲜花市场；鱼市"}},{"en":"business or trade, or the amount of trade in a particular type of goods","cn":"交易；买卖；交易量","g":"[singular]","lab":"North American English","ex":{"en":"the world market in coffee","cn":"世界咖啡交易"}},{"en":"a particular area, country or section of the population that might buy goods","cn":"商品的销售地；行销地区；消费群体","g":"[countable]","ex":{"en":"exporters who want to access the Japanese market","cn":"想要进入日本市场的出口商"}},{"en":"the number of people who want to buy something","cn":"（顾客对货物或服务的）需求","g":"[singular]","ex":{"en":"a growing/declining market for second-hand cars","cn":"不断扩大的／萎缩的二手车市场"}},{"en":"people who buy and sell goods in competition with each other","cn":"（处于竞争中的）市场经营者，市场","g":"[singular]","ex":{"en":"The market will decide if the TV station has any future.","cn":"电视台是否有前途将取决于市场。"}},{"en":"the business of buying and selling shares in companies and the place where this happens; a stock exchange","cn":"证券交易（所）；股票交易（所）；股市","g":"[countable]","ex":{"en":"the futures market","cn":"期货市场"}},{"en":"to advertise a product in a particular way in order to make people want it","cn":"推销；营销","ex":{"en":"The company utilizes every media tool available to market its products.","cn":"公司利用一切可用的媒体工具推销其产品。"},"pos":"verb"},{"en":"to offer a product for sale","cn":"推出；上市销售","ex":{"en":"Many farmers have taken steps to directly market their meat to consumers.","cn":"许多农民已经采取措施向消费者直销肉品。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指露天）集市， 市场","en":"A market is a place where goods are bought and sold, usually outdoors.","ex":{"en":"He sold boots on a market stall.","cn":"他在集市上摆摊卖靴子。"}},{"pos":"N-COUNT 可数名词","cn":"需求量;市场需求;顾客群;行销地区","en":"The market for a particular type of thing is the number of people who want to buy it, or the area of the world in which it is sold.","ex":{"en":"The foreign market was increasingly crucial.","cn":"国外市场越来越重要了。"}},{"pos":"N-SING 单数名词","cn":"（尤用于谈论同行业竞争时）年销售量，市场总额","en":"The market refers to the total amount of a product that is sold each year, especially when you are talking about the competition between the companies who sell that product.","ex":{"en":"The two big companies control 72% of the market.","cn":"两大公司控制了72%的市场份额。"}},{"pos":"ADJ 形容词","cn":"市场的;由市场决定的","en":"If you talk about a market economy, or the market price of something, you are referring to an economic system in which the prices of things depend on how many are available and how many people want to buy them, rather than prices being fixed by governments.","ex":{"en":"Their ultimate aim was a market economy for Hungary","cn":"他们最终的目标是为匈牙利建立起市场经济体制。"}},{"pos":"VERB 动词","cn":"营销;推销；进行市场推广","en":"To market a product means to organize its sale, by deciding on its price, where it should be sold, and how it should be advertised.","ex":{"en":"...if you marketed our music the way you market pop music","cn":"要是你用了推广流行音乐的方式宣传我们的音乐的方式"}},{"pos":"N-SING 单数名词","cn":"就业市场/劳动力市场","en":"The job market or the labour market refers to the people who are looking for work and the jobs available for them to do.","ex":{"en":"Every year, 250,000 people enter the job market.","cn":"每年有25万人进入就业市场。"}},{"pos":"N-SING 单数名词","cn":"股票市场;股市","en":"The stock market is sometimes referred to as the market .","ex":{"en":"The market collapsed last October.","cn":"去年10月股市崩盘。"}},{"pos":"PHRASE 短语","cn":"买方市场/ 卖方市场","en":"If you say that it is a buyer's market, you mean that it is a good time to buy a particular thing, because there is a lot of it available, so its price is low. If you say that it is a seller's market, you mean that very little of it is available, so its price is high.","ex":{"en":"Don't be afraid to haggle: for the moment, it's a buyer's market","cn":"别怕还价，现在是买方市场。"}},{"pos":"PHRASE 短语","cn":"有意购买;想买进","en":"If you are in the market for something, you are interested in buying it.","ex":{"en":"If you're in the market for a new radio, you'll see that the latest models are very different.","cn":"如果你打算买一台新收音机，你会发现最新型号的收音机变化非常大。"}},{"pos":"PHRASE 短语","cn":"在出售;待售/上市;投入市场","en":"If something is on the market, it is available for people to buy. If it comes onto the market, it becomes available for people to buy.","ex":{"en":"...putting more empty offices on the market.","cn":"出售更多的闲置办公室"}},{"pos":"PHRASE 短语","cn":"要价过高而无人购买","en":"If you price yourself out of the market, you try to sell goods or services at a higher price than other people, with the result that no one buys them from you.","ex":{"en":"At £150,000 for a season, he really is pricing himself out of the market.","cn":"他居然一个赛季要价15万英镑，真让人不敢问津。"}}]},"examples":[{"en":"School meals need to be marketed to children in the same way as other food.","cn":"校餐也要以其他食品的推销方法推销给孩子。"},{"en":"They have increased their share of the market by 10%.","cn":"他们将其所占的市场份额增加了 10%。"}]},"mandated":{"media":{"uk":"media/uk/mandated__gb_1.mp3","us":"media/us/mandated__us_1.mp3"},"oxford":{"phon":"ˈmændeɪtɪd","pos":"adjective","senses":[{"en":"placed under the rule of another country","cn":"委托别国管辖的；托管的","ex":{"en":"mandated territories","cn":"托管地区"}},{"en":"required by law","cn":"依法的；按法律要求的","ex":{"en":"a mandated curriculum","cn":"法定课程"}},{"en":"having a mandate to do something","cn":"获得授权的","ex":{"en":"a mandated government","cn":"获授权的政府"}}]},"examples":[{"en":"a mandated government","cn":"获授权的政府"},{"en":"mandated territories","cn":"托管地区"}]},"magic":{"media":{"uk":"media/uk/magic__gb_1.mp3","us":"media/us/magic__us_1.mp3"},"oxford":{"phon":"ˈmædʒɪk","pos":"noun","senses":[{"en":"the secret power of appearing to make impossible things happen by saying special words or doing special things","cn":"魔法；法术；巫术","lab":"figurative","ex":{"en":"Do you believe in magic?","cn":"你相信巫术吗？"}},{"en":"the art of doing tricks that seem impossible in order to entertain people","cn":"戏法；魔术","ex":{"en":"He earns extra money doing magic at children's parties.","cn":"他在儿童聚会上表演魔术挣外快。"}},{"en":"a special quality or ability that somebody/something has, that seems too wonderful to be real","cn":"魔力；魅力；神奇","ex":{"en":"dance and music which capture the magic of India","cn":"具有印度独特魅力的舞蹈和音乐"}},{"en":"having or using special powers to make impossible things happen or seem to happen","cn":"有魔力的；（施）巫术的；有神奇力量的","ex":{"en":"a magic spell/charm/potion","cn":"魔咒；魔力；魔药"},"pos":"adjective"},{"en":"having a special quality that makes something seem wonderful","cn":"神奇的；有魔力的；美好的","lab":"informal","ex":{"en":"It was a magic moment when the two sisters were reunited after 30 years.","cn":"30 年后姐妹俩重逢，就像做梦一样。"},"pos":"adjective"},{"en":"very good or a lot of fun","cn":"好极了；棒极了","g":"[not before noun]","lab":"British English, informal，，","ex":{"en":"‘What was the trip like?’ ‘Magic!’","cn":"“旅行感觉如何？”“棒极了！”"},"pos":"adjective"},{"en":"to make somebody/something appear somewhere, disappear or turn into something, by magic, or as if by magic","cn":"（像）用魔法变出（或使消失、使变成…等）","ex":{"en":"He played an early little sonata of Mozart's, which he magicked into a masterpiece with his deft touch.","cn":"他演奏了莫扎特早期的一首小奏鸣曲，并凭借灵巧的演奏将其变成了一部杰作。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"魔法;巫术;法术","en":"Magic is the power to use supernatural forces to make impossible things happen, such as making people disappear or controlling events in nature.","ex":{"en":"They believe in magic","cn":"他们相信巫术。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"魔术;魔法","en":"You can use magic when you are referring to an event that is so wonderful, strange, or unexpected that it seems as if supernatural powers have caused it. You can also say that something happens as if by magic or like magic .","ex":{"en":"All this was supposed to work magic","cn":"这一切被认为会创造奇迹。"}},{"pos":"ADJ 形容词","cn":"(似)用魔法变成的;(似)用魔术变出的","en":"You use magic to describe something that does things, or appears to do things, by magic.","ex":{"en":"So it's a magic potion?","cn":"那么，这是个神药？"}},{"pos":"N-UNCOUNT 不可数名词","cn":"魔术;戏法","en":"Magic is the art and skill of performing mysterious tricks to entertain people, for example by making things appear and disappear.","ex":{"en":"His secret hobby: performing magic tricks.","cn":"他私底下有变戏法的嗜好。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"魅力;魔力;神奇(性)","en":"If you refer to the magic of something, you mean that it has a special mysterious quality which makes it seem wonderful and exciting to you and which makes you feel happy.","ex":{"en":"It infected them with some of the magic of a lost age","cn":"逝去的岁月让他们平添了几分魅力。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（令人钦佩的）特殊才能，能力","en":"If you refer to a person's magic, you mean a special talent or ability that they have, which you admire or consider very impressive.","ex":{"en":"The fighter believes he can still regain some of his old magic.","cn":"这位斗士相信自己仍然可以恢复从前的一些魔力。"}},{"pos":"ADJ 形容词","cn":"（数目、词语等）重要的，关键的，举足轻重的","en":"You can use expressions such as the magic number and the magic word to indicate that a number or word is the one which is significant or desirable in a particular situation.","ex":{"en":"...their quest to gain the magic number of 270 electoral votes on Election Day.","cn":"在大选之日他们对胜败攸关的270张选票的争取"}},{"pos":"ADJ 形容词","cn":"立见奇效的;立竿见影的","en":"Magic is used in expressions such as there is no magic formula and there is no magic solution to say that someone will have to make an effort to solve a problem, because it will not solve itself.","ex":{"en":"There is no magic formula for producing winning products","cn":"获奖电影的制作没有捷径可取。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"极好的;了不起的;非常棒的","en":"If you say that something is magic, you think it is very good or enjoyable.","ex":{"en":"It was magic—one of the best days of my life.","cn":"真是太棒了——这是我生命中最美好的一天。"}}]},"examples":[{"en":"Like all truly charismatic people, he can work his magic on both men and women.","cn":"像所有真正富有魅力的人一样，他让男人和女人都很着迷。"},{"en":"There is no magic formula for passing exams — only hard work.","cn":"根本没有通过考试的魔法，唯一的方法就是勤奋学习。"}]},"married":{"media":{"uk":"media/uk/married__gb_1.mp3","us":"media/us/married__us_1.mp3"},"oxford":{"phon":"ˈmærid","pos":"adjective","senses":[{"en":"having a husband or wife","cn":"已婚的","lab":"especially North American English","ex":{"en":"a married man/woman","cn":"已婚男子／女子"}},{"en":"connected with marriage","cn":"婚姻的；结婚的","g":"[only before noun]","ex":{"en":"Are you enjoying married life?","cn":"你喜欢你的婚姻生活吗？"}},{"en":"very involved in something so that you have no time for other activities or interests","cn":"专心（于某事）；全神贯注（于某事）","ex":{"en":"My brother is married to his job.","cn":"我弟弟一心扑在工作上。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"结婚的;已婚的","en":"If you are married, you have a husband or wife.","ex":{"en":"We have been married for 14 years","cn":"我们已经结婚14年了。"}},{"pos":"ADJ 形容词","cn":"婚姻的;夫妇的","en":"Married means relating to marriage or to people who are married.","ex":{"en":"For the first ten years of our married life we lived in a farm-house.","cn":"我们结婚的头10年住在一座农舍里。"}},{"pos":"ADJ 形容词","cn":"献身(于…)的;致力(于…)的","en":"If you say that someone is married to their work or another activity, you mean that they are very involved with it and have little interest in anything else.","ex":{"en":"She was a very strict Christian who was married to her job","cn":"她是个虔诚的基督徒，对工作全身心投入。"}}]},"examples":[{"en":"Rachel and David are getting married on Saturday.","cn":"雷切尔和戴维将在星期六结婚。"},{"en":"Are you enjoying married life?","cn":"你喜欢你的婚姻生活吗？"}]},"make":{"media":{"uk":"media/uk/make__gb_1.mp3","us":"media/us/make__us_1.mp3"},"oxford":{"phon":"meɪk","pos":"verb","senses":[{"en":"to create or prepare something by combining materials or putting parts together","cn":"制造；做；组装","lab":"North American English","sc":"create","ex":{"en":"to make a table/dress/cake","cn":"做桌子／连衣裙／蛋糕"}},{"en":"to write, create or prepare something","cn":"写；出产；制定","sc":"create","ex":{"en":"These regulations were made to protect children.","cn":"这些规章制度是为了保护儿童而制定的。"}},{"en":"to cause something to appear as a result of breaking, tearing, hitting or removing material","cn":"造成（破坏、破损等）","sc":"cause to appear/happen/become/do","ex":{"en":"The stone made a dent in the roof of the car.","cn":"石头把车顶砸了个坑。"}},{"en":"to cause something to exist, happen or be done","cn":"使出现；引发；使产生","sc":"cause to appear/happen/become/do","ex":{"en":"to make a noise/mess/fuss","cn":"产生噪声；弄得一团糟；小题大做"}},{"en":"to cause somebody/something to feel, show or have a particular quality; to cause somebody/something to be or become something","cn":"使变得；使成为","sc":"cause to appear/happen/become/do","ex":{"en":"The news made him very happy.","cn":"这则消息使他非常高兴。"}},{"en":"to cause somebody/something to do something","cn":"促使；使得","sc":"cause to appear/happen/become/do","ex":{"en":"She always makes me laugh.","cn":"她总是让我发笑。"}},{"en":"to cause somebody/something to be or become a particular kind of thing or person","cn":"使成为","sc":"cause to appear/happen/become/do","ex":{"en":"This isn't very important—I don't want to make an issue of it.","cn":"这不太重要，我不想把它当回事儿。"}},{"en":"to arrange a bed so that it is neat and ready for use","cn":"铺床","sc":"a bed"},{"en":"to decide, guess, etc. something","cn":"做，作出（决定、估计等）","sc":"a decision/guess/comment, etc.","ex":{"en":"Come on! It's time we made a start.","cn":"快点！我们该开始了。"}},{"en":"to force somebody to do something","cn":"迫使；强迫","sc":"force","ex":{"en":"They made me repeat the whole story.","cn":"他们非让我把整个事件再说一遍。"}},{"en":"to represent somebody/something as being or doing something","cn":"表现；表示；描绘","sc":"represent","ex":{"en":"You've made my nose too big (= for example in a drawing).","cn":"你把我的鼻子画得太大了。"}},{"en":"to elect or choose somebody as something","cn":"选举；挑选；任命","sc":"appoint","ex":{"en":"She made him her assistant.","cn":"她挑选他做她的助手。"}},{"en":"to become or develop into something; to be suitable for something","cn":"成为；适合","sc":"be suitable","ex":{"en":"She would have made an excellent teacher.","cn":"她本可以成为一位出色的教师。"}},{"en":"to add up to or equal something","cn":"合计；等于","sc":"equal","ex":{"en":"5 and 7 make 12.","cn":"5 加 7 等于 12。"}},{"en":"to be a total of something","cn":"成为总数；是…的总和","sc":"equal","ex":{"en":"That makes the third time he's failed his driving test!","cn":"他这已经是第三次驾驶考试不及格了！"}},{"en":"to earn or gain money","cn":"挣钱；赚钱","sc":"money","ex":{"en":"She makes $100 000 a year.","cn":"她一年赚 10 万美元。"}},{"en":"to think or calculate something to be something","cn":"估计；计算","g":"[no passive]","sc":"calculate","ex":{"en":"What time do you make it?","cn":"你估计现在几点了？"}},{"en":"to manage to reach or go to a place or position","cn":"（尽力）赶往，到达，达到","g":"[no passive]","sc":"reach","ex":{"en":"Do you think we'll make Dover by 12?","cn":"你觉得我们 12 点前能到多佛吗？"}},{"en":"to cause something to be a success","cn":"使成功；使圆满","sc":"something successful","ex":{"en":"Good wine can make a meal.","cn":"酒美饭亦香。"}},{"en":"the name or type of a machine, piece of equipment, etc. that is made by a particular company","cn":"（机器、设备等的）品牌，型号","ex":{"en":"What make of car does he drive?","cn":"他开的是什么品牌的车？"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"(与大量名词连用，表示做动作、说某事等)做出，作出","en":"You can use make with a wide range of nouns to indicate that someone performs an action or says something. For example, if you make a suggestion, you suggest something.","ex":{"en":"I'd just like to make a comment","cn":"我只想稍加评论。"}},{"pos":"VERB 动词","cn":"(与某些名词连用)把…做(好)，把…搞(糟)","en":"You can use make with certain nouns to indicate that someone does something well or badly. For example, if you make a success of something, you do it successfully, and if you make a mess of something, you do it very badly.","ex":{"en":"Apparently he made a mess of his audition","cn":"看样子他把试镜搞砸了。"}},{"pos":"VERB 动词","cn":"摆出…的姿态;做出…的样子","en":"If you make as if to do something or make to do something, you behave in a way that makes it seem that you are just about to do it.","ex":{"en":"Mary made as if to protest, then hesitated","cn":"玛丽好像要抗议，却又犹豫了。"}},{"pos":"VERB 动词","cn":"(在板球、棒球、橄榄球比赛中)得(分)","en":"In cricket, if a player makes a particular number of runs, they score that number of runs. In baseball or American football, if a player makes a particular score, they achieve that score.","ex":{"en":"He made 1,972 runs for the county.","cn":"他为本郡赢得了1,972分。"}},{"pos":"PHRASE 短语","cn":"将就使用；凑合着用","en":"If you make do with something, you use or have it instead of something else that you do not have, although it is not as good.","ex":{"en":"Why make do with a copy if you can afford the genuine article?","cn":"要是买得起真品，为什么还要拿复制品来凑合呢？"}},{"pos":"PHRASE 短语","cn":"装作;假装;模仿","en":"If you make like you are doing something, you act as if you are doing it, and if you make like someone, you act as if you are that person.","ex":{"en":"Bob makes like he's a fish blowing bubbles.","cn":"鲍勃装成一条吐泡泡的鱼。"}},{"pos":"VERB 动词","cn":"使;致使","en":"If something makes you do something, it causes you to do it.","ex":{"en":"Grit from the highway made him cough","cn":"公路上扬起的沙子呛得他咳嗽起来。"}},{"pos":"VERB 动词","cn":"迫使;强迫","en":"If you make someone do something, you force them to do it.","ex":{"en":"Mama made him clean up the plate","cn":"妈妈要他把盘子洗干净。"}},{"pos":"VERB 动词","cn":"使成为(某种人或物);使具有(某种特性)","en":"You use make to talk about causing someone or something to be a particular thing or to have a particular quality. For example, to make someone a star means to cause them to become a star, and to make someone angry means to cause them to become angry.","ex":{"en":"...James Bond, the role that made him a star","cn":"詹姆斯·邦德——这个使他一举成名的角色"}},{"pos":"VERB 动词","cn":"使显得;使看上去","en":"If you say that one thing or person makes another seem, for example, small, stupid, or good, you mean that they cause them to seem small, stupid, or good in comparison, even though they are not.","ex":{"en":"They live in fantasy worlds which make Euro Disney seem uninventive","cn":"他们生活在幻想的世界里，相形之下连欧洲迪士尼乐园都显得毫无创意。"}},{"pos":"VERB 动词","cn":"使自己(被理解、听见、知晓等)","en":"If you make yourself understood, heard, or known, you succeed in getting people to understand you, hear you, or know that you are there.","ex":{"en":"Aron couldn't speak Polish. I made myself understood with difficulty","cn":"阿伦不会说波兰语，我为了让他明白我的话很是费了一番力气。"}},{"pos":"VERB 动词","cn":"委任;任命","en":"If you make someone something, you appoint them to a particular job, role, or position.","ex":{"en":"Mr Blair made him transport minister","cn":"布莱尔先生任命他为交通部长。"}},{"pos":"VERB 动词","cn":"把…变成;使…成为","en":"If you make something into something else, you change it in some way so that it becomes that other thing.","ex":{"en":"We made it into a beautiful home","cn":"我们把这里变成了美丽的家园。"}},{"pos":"VERB 动词","cn":"使(总数)升为;使(分数)达到","en":"To make a total or score a particular amount means to increase it to that amount.","ex":{"en":"This makes the total cost of the bulb and energy £27","cn":"这使灯泡与电费合计为27英镑。"}},{"pos":"VERB 动词","cn":"交(朋友);树(敌);结(仇)","en":"When someone makes a friend or an enemy, someone becomes their friend or their enemy, often because of a particular thing they have done.","ex":{"en":"Lorenzo was a natural leader who made friends easily","cn":"洛伦佐是天生的领袖，善于交友。"}},{"pos":"PHRASE 短语","cn":"成功;胜利","en":"If someone makes something of themselves or makes something of their life, they become successful.","ex":{"en":"My father lived long enough to see that I'd made something of myself","cn":"父亲在有生之年见证了我出人头地的那一天。"}},{"pos":"","cn":"","en":"to make friends→see: ;"},{"pos":"VERB 动词","cn":"制造;建造;创造","en":"To make something means to produce, construct, or create it.","ex":{"en":"She made her own bread","cn":"她自己做面包。"}},{"pos":"VERB 动词","cn":"拍摄(电影);制作(电视节目)","en":"If someone makes a film or television programme, they are involved in creating or producing it.","ex":{"en":"We are making a film about wildlife.","cn":"我们正在拍摄一部关于野生动物的影片。"}},{"pos":"VERB 动词","cn":"做(饭);准备(饮料)","en":"If you make a meal or a drink, you prepare it.","ex":{"en":"You wash while I make some lunch","cn":"你洗一下，我去做午饭。"}},{"pos":"VERB 动词","cn":"写(便条);记(笔记);列(名单)","en":"If you make a note or list, you write something down in that form.","ex":{"en":"Mr Perry made a note in his book","cn":"佩里先生在他的书上作了一个注解。"}},{"pos":"VERB 动词","cn":"制定，规定（规则、法律等）","en":"If you make rules or laws, you decide what these should be.","ex":{"en":"The police don't make the laws, they merely enforce them","cn":"警察并不制定法律，只是负责执行。"}},{"pos":"VERB 动词","cn":"挣(钱);赚(钱)","en":"If you make money, you get it by working for it, by selling something, or by winning it.","ex":{"en":"I think every business's goal is to make money","cn":"我认为各家公司的目的都是赚钱。"}},{"pos":"VERB 动词","cn":"(某事物)使(其他事物)变得成功","en":"If something makes something else, it is responsible for the success of that thing.","ex":{"en":"What really makes the book are the beautiful designs.","cn":"真正让这本书大获成功的是它精美的设计。"}},{"pos":"N-COUNT 可数名词","cn":"(汽车、收音机等的)品牌","en":"The make of something such as a car or radio is the name of the company that made it. →see usage note at:","ex":{"en":"The only car parked outside is a black Saab — a different make.","cn":"停在外面的只有一辆黑色的萨博——不是一个牌子的车。"}},{"pos":"PHRASE 短语","cn":"（可能以非法或不道德手段）拼命追求金钱(或权力）","en":"If you say that someone is on the make, you disapprove of them because they are trying to get a lot of money or power, possibly by illegal or immoral methods."},{"pos":"V-LINK 连系动词","cn":"有资格成为；足以成为","en":"You can use make to say that someone or something has the right qualities for a particular task or role. For example, if you say that someone will make a good politician, you mean that they have the right qualities to be a good politician.","ex":{"en":"She'll make a good actress, if she gets the right training","cn":"如果训练得当，她会成为一名出色的演员。"}},{"pos":"V-LINK 连系动词","cn":"组成;形成;排列成","en":"If people make a particular pattern such as a line or a circle, they arrange themselves in this way.","ex":{"en":"A group of people made a circle around the Pentagon.","cn":"一群人在五角大楼四周围成一圈。"}},{"pos":"V-LINK 连系动词","cn":"等于;成为","en":"You can use make to say what two numbers add up to.","ex":{"en":"Four twos make eight","cn":"4乘以2等于8。"}},{"pos":"VERB 动词","cn":"成为…的一员;加入;谋得（高级职务）","en":"If someone makes a particular team or makes a particular high position, they do so well that they are put in that team or get that position.","ex":{"en":"The athletes are just happy to make the British team","cn":"运动员们很乐意加入英国国家队。"}},{"pos":"VERB 动词","cn":"赶到;(及时)到达","en":"If you make a place in or by a particular time, you get there in or by that time, often with some difficulty.","ex":{"en":"They were trying to make New Orleans by nightfall.","cn":"他们力图在黄昏前赶到新奥尔良。"}},{"pos":"PHRASE 短语","cn":"(及时)到达（尤指来得及做某事）","en":"If you make it somewhere, you succeed in getting there, especially in time to do something.","ex":{"en":"So you did make it to America, after all.","cn":"那么，你终究还是成功地来到了美国。"}},{"pos":"PHRASE 短语","cn":"（经历艰难困苦后）成功","en":"If you make it, you are successful in achieving something difficult, or in surviving through a very difficult period.","ex":{"en":"I believe I have the talent to make it","cn":"我相信自己有成功的天分。"}},{"pos":"PHRASE 短语","cn":"及时赶上参加","en":"If you cannot make it, you are unable to attend an event that you have been invited to.","ex":{"en":"'I can't make it,' she said. 'That's Mother's Day.'","cn":"“我无法赴约了，”她说，“那天是母亲节。”"}},{"pos":"VERB 动词","cn":"算，猜(数字)","en":"You use make it when saying what you calculate or guess an amount to be.","ex":{"en":"All I want to know is how many T-shirts Jim Martin has got. I make it three","cn":"我就想知道吉姆·马丁一共有多少件T恤衫。我猜他有3件。"}},{"pos":"VERB 动词","cn":"(根据自己的表)时间为…","en":"You use make it when saying what time your watch says it is.","ex":{"en":"I make it nearly 9.30","cn":"我的手表显示快9点半了。"}},{"pos":"","cn":"","en":"相关词组：make for make of make off make off with make out make over make up make up for make up to"}]},"examples":[{"en":"The flight leaves in twenty minutes — we'll never make it.","cn":"再过二十分钟飞机就起飞了，咱们无论如何也赶不上了。"},{"en":"He never cleans his room and his mother never tries to make him.","cn":"他从不收拾自己的房间，而他妈也从不要求他收拾。"}]},"maize":{"oxford":{"phon":"meɪz","pos":"noun","senses":[{"en":"a tall plant grown for its large yellow grains that are used for making flour or eaten as a vegetable; the grains of this plant","cn":"玉蜀黍；玉米","lab":"British English"},{"en":"a type of corn (maize) with large brown and yellow grains, not usually eaten but sometimes used to make decorations, for example at Thanksgiving","cn":"印第安玉米（通常不食用，用于感恩节等装饰）","lab":"especially North American English"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"玉米;玉蜀黍","en":"Maize is a tall plant which produces long objects covered with yellow seeds called sweetcorn. It is often grown as a food crop.","ex":{"en":"...vast fields of maize.","cn":"广袤的玉米地"}}]},"media":{"img":["media/pic/cereals_comp.jpg","media/thumb/maize.jpg"],"uk":"media/uk/maize__gb_1.mp3","us":"media/us/maize__us_1.mp3"}},"maintain":{"media":{"uk":"media/uk/maintain__gb_1.mp3","us":"media/us/maintain__us_1.mp3"},"oxford":{"phon":"meɪnˈteɪn","pos":"verb","senses":[{"en":"to make something continue at the same level, standard, etc.","cn":"维持；保持","lab":"formal","ex":{"en":"to maintain law and order/standards/a balance/control","cn":"维持治安；保持水平／平衡／控制"}},{"en":"to keep a building, a machine, etc. in good condition by checking or repairing it regularly","cn":"维修；保养","ex":{"en":"The house is large and difficult to maintain.","cn":"房子很大，难以养护。"}},{"en":"to support somebody/something over a long period of time by giving money, paying for food, etc.","cn":"供养；扶养","ex":{"en":"Her income was barely enough to maintain one child, let alone three.","cn":"她的收入养活一个孩子几乎都不够，更不用说三个了。"}},{"en":"to keep stating that something is true, even though other people do not agree or do not believe it","cn":"坚持（意见）；固执己见","ex":{"en":"The men maintained (that) they were out of the country when the crime was committed.","cn":"这几个男人坚持说案发时他们在国外。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"维持;保持","en":"If you maintain something, you continue to have it, and do not let it stop or grow weaker.","ex":{"en":"The Department maintains many close contacts with the chemical industry","cn":"这个部门与化工行业保持着众多密切的联系。"}},{"pos":"VERB 动词","cn":"断言;宣称;坚称","en":"If you say that someone maintains that something is true, you mean that they have stated their opinion strongly but not everyone agrees with them or believes them.","ex":{"en":"He has maintained that the money was donated for international purposes","cn":"他坚称这笔捐款将用于国际用途。"}},{"pos":"VERB 动词","cn":"保持，维持（在某一比率或水平上）","en":"If you maintain something at a particular rate or level, you keep it at that rate or level.","ex":{"en":"The government was right to maintain interest rates at a high level.","cn":"政府维持高利率的做法是正确的。"}},{"pos":"VERB 动词","cn":"维修;保养","en":"If you maintain a road, building, vehicle, or machine, you keep it in good condition by regularly checking it and repairing it when necessary.","ex":{"en":"...a tough campaign to force authorities to maintain roads properly","cn":"迫使当局妥善维修道路的艰难斗争"}},{"pos":"VERB 动词","cn":"供养;赡养","en":"If you maintain someone, you provide them with money and other things that they need.","ex":{"en":"He should pay and maintain you as well.","cn":"他得给你钱，还得供养你。"}}]},"examples":[{"en":"Her income was barely enough to maintain one child, let alone three.","cn":"她的收入养活一个孩子几乎都不够，更不用说三个了。"},{"en":"The men maintained (that) they were out of the country when the crime was committed.","cn":"这几个男人坚持说案发时他们在国外。"}]},"mafia":{"oxford":{"phon":"ˈmæfiə","pos":"noun","senses":[{"en":"a secret organization of criminals, that is active especially in Sicily, Italy and the US","cn":"黑手党（尤活跃于意大利西西里和美国）","g":"[singular + singular or plural verb]","ex":{"en":"a Mafia boss","cn":"黑手党老大"}},{"en":"an organized group of criminals similar to the Mafia in the way it operates","cn":"（类似黑手党的）犯罪团伙，黑帮","g":"[countable + singular or plural verb]","ex":{"en":"the rise of criminal mafias in various parts of Europe","cn":"犯罪团伙在欧洲各地的兴起"}},{"en":"a group of people within an organization or a community who use their power to get advantages for themselves","cn":"小集团；小帮派；团伙；社会黑帮","g":"[countable + singular or plural verb]","ex":{"en":"a member of the local mafia","cn":"当地黑社会中的一名成员"}}]},"collins":{"senses":[{"pos":"N-COUNT-COLL 可数集合名词","cn":"黑手党","en":"The Mafia is a criminal organization that makes money illegally, especially by threatening people and dealing in drugs.","ex":{"en":"The Mafia is by no means ignored by Italian television.","cn":"意大利电视台绝对不会放过对黑手党的关注。"}},{"pos":"N-COUNT 可数名词","cn":"黑帮;势力集团;秘密犯罪团伙","en":"You can use mafia to refer to an organized group of people who you disapprove of because they use unfair or illegal means in order to get what they want.","ex":{"en":"They are well-connected with the south-based education-reform mafia.","cn":"他们同以南方为大本营的教育改革势力集团有着密切的联系。"}}]},"media":{"uk":"media/uk/mafia__gb_1.mp3","us":"media/us/mafia__us_1.mp3"},"examples":[{"en":"Politics is still dominated by the middle-class mafia.","cn":"政治仍然操纵在中产阶级帮派手中。"},{"en":"a member of the local mafia","cn":"当地黑社会中的一名成员"}]},"manage":{"media":{"uk":"media/uk/manage__gb_1.mp3","us":"media/us/manage__us_1.mp3"},"oxford":{"phon":"ˈmænɪdʒ","pos":"verb","senses":[{"en":"to control or be in charge of a business, a team, an organization, land, etc.","cn":"管理，负责（公司、队伍、组织等）","g":"[transitive, intransitive]","sc":"business/team","ex":{"en":"to manage a business/factory/bank/hotel/soccer team","cn":"管理企业／工厂／银行／酒店／足球队"}},{"en":"to succeed in doing something, especially something difficult","cn":"完成（困难的事）；勉力完成","g":"[transitive, intransitive]","lab":"humorous","sc":"do something difficult","ex":{"en":"I don't know exactly how we'll manage it, but we will, somehow.","cn":"我说不准我们如何去完成这件事，但不管怎样我们一定会完成的。"}},{"en":"to succeed in achieving or producing something","cn":"成功获得（或做出）","g":"[transitive]","sc":"do something difficult","ex":{"en":"In spite of his disappointment, he managed a weak smile.","cn":"尽管很失望，他还是勉强露出一丝微笑。"}},{"en":"to be able to solve your problems, deal with a difficult situation, etc.","cn":"能解决（问题）；应付（困难局面等）","g":"[intransitive]","sc":"deal with problems","ex":{"en":"She's 82 and can't manage on her own any more.","cn":"她 82 岁了，照顾不了自己的生活了。"}},{"en":"to be able to live or survive without having much money, support, sleep, etc.","cn":"勉强支撑；凑合着过活","g":"[intransitive]","sc":"money/time/information","ex":{"en":"young families who are just about managing","cn":"勉强维持生计的年轻家庭"}},{"en":"to use money, time, information, etc. in a sensible way","cn":"明智地使用（金钱、时间、信息等）","g":"[transitive]","sc":"money/time/information","ex":{"en":"Don't tell me how to manage my affairs.","cn":"用不着你来告诉我怎样管我自己的事。"}},{"en":"to be able to do something at a particular time","cn":"（在某一时间）能办到，能做成","g":"[transitive]","sc":"money/time/information","ex":{"en":"Let's meet up again—can you manage next week sometime?","cn":"我们再见一次面吧。下周找个时间，行吗？"}},{"en":"to keep somebody/something under control; to be able to deal with somebody/something","cn":"控制住；操纵；能对付","g":"[transitive]","sc":"control","ex":{"en":"It's like trying to manage an unruly child.","cn":"这就像试图管住一个任性的孩子。"}},{"en":"to control how land is used, so that it is used in a sensible way","cn":"合理使用（土地）","g":"[transitive]","sc":"land","ex":{"en":"The landowners manage their land to provide habitat for the desired species.","cn":"土地所有者合理使用土地，为受欢迎的物种提供栖息地。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"管理;经营;掌管","en":"If you manage an organization, business, or system, or the people who work in it, you are responsible for controlling them.","ex":{"en":"Within two years he was managing the store","cn":"不出两年他就开始管理这家店了。"}},{"pos":"VERB 动词","cn":"谨慎地使用，好好地利用(时间、金钱等)","en":"If you manage time, money, or other resources, you deal with them carefully and do not waste them.","ex":{"en":"In a busy world, managing your time is increasingly important","cn":"在忙碌的世界里，善于利用时间变得越来越重要。"}},{"pos":"VERB 动词","cn":"设法做到;成功完成","en":"If you manage to do something, especially something difficult, you succeed in doing it.","ex":{"en":"Somehow, he'd managed to persuade Kay to buy one for him","cn":"不知用了什么方法，他成功说服凯给他买了一个。"}},{"pos":"VERB 动词","cn":"成功对付;设法应对","en":"If you manage, you succeed in coping with a difficult situation.","ex":{"en":"She had managed perfectly well without medication for three years","cn":"3年来，她一直没有服药却挺了过来。"}},{"pos":"VERB 动词","cn":"抽出，腾出，安排出(时间、金钱等)","en":"If you say that you can manage an amount of time or money for something, you mean that you can afford to spend that time or money on it.","ex":{"en":"This makes it ideal for those who can only manage a few hours in the morning or evening","cn":"对于那些只能在早晚抽出几个小时的人来说，这是最理想不过的了。"}},{"pos":"VERB 动词","cn":"勉强做出（微笑、寒暄等);强作","en":"If you say that someone managed a particular response, such as a laugh or a greeting, you mean that it was difficult for them to do it because they were feeling sad or upset.","ex":{"en":"He looked dazed as he spoke to reporters, managing only a weak smile","cn":"跟记者谈话的时候，他只是勉强挤出一丝淡淡的微笑，显得非常恍惚。"}},{"pos":"CONVENTION 惯用语","cn":"（对他人给予帮助的婉拒）我能对付，我能行","en":"You say 'I can manage' or 'I'll manage' as a way of refusing someone's offer of help and insisting on doing something by yourself.","ex":{"en":"I know you mean well, but I can manage by myself","cn":"我知道您是一番好意，不过我一个人能行。"}}]},"examples":[{"en":"I don't know exactly how we'll manage it , but we will, somehow.","cn":"我说不准我们如何去完成这件事，但不管怎样我们一定会完成的。"},{"en":"‘Need any help?’ ‘No, thanks. I can manage.’ “","cn":"要帮忙吗？” “不了，谢谢。我应付得了。”"}]},"masses":{"oxford":{"phon":"mæs","pos":"noun","senses":[{"en":"a large amount of a substance that does not have a definite shape or form","cn":"团；块；堆"},{"en":"a large amount or quantity of sth","cn":"大量；许多"}]},"media":{"uk":"media/uk/mass__gb_1.mp3","us":"media/us/mass__us_1.mp3"}},"mainly":{"media":{"uk":"media/uk/mainly__gb_1.mp3","us":"media/us/mainly__us_1.mp3"},"oxford":{"phon":"ˈmeɪnli","pos":"adverb","senses":[{"en":"more than anything else; also used to talk about the most important reason for something","cn":"主要地；首要地","ex":{"en":"They eat mainly fruit and nuts.","cn":"他们主要吃水果和坚果。"}},{"en":"in most cases; used to talk about the largest part of a group of people or things","cn":"大部分；大多","ex":{"en":"Anorexia is an illness that occurs mainly in adolescents.","cn":"厌食症是一种多发于青少年的疾病。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"主要地;大部分地","en":"You use mainly when mentioning the main reason or thing involved in something.","ex":{"en":"The stock-market scandal is refusing to go away, mainly because there's still no consensus over how it should be dealt with","cn":"股票市场的丑闻迟迟没有消散，这主要是因为人们仍未就如何应对它达成共识。"}},{"pos":"ADV 副词","cn":"主要地；大多数地","en":"You use mainly when you are referring to a group and stating something that is true of most of it.","ex":{"en":"The African half of the audience was mainly from Senegal or Mali","cn":"观众中有一半是非洲人，其中大多数来自塞内加尔或马里。"}}]},"examples":[{"en":"The population almost doubles in summer, mainly because of the jazz festival.","cn":"主要是爵士音乐节的缘故，在夏季这里的人口几乎比平时多一倍。"},{"en":"‘Where do you export to?’ ‘France, mainly.’ “","cn":"你们出口到哪里？” “主要是法国。”"}]},"majestically":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"measuring a long distance from the bottom to the top – used about mountains, walls, and buildings","cn":""},{"en":"high – used about people, trees, plants, and buildings. Tall is used especially about things that are high and narrow","cn":""}]},"examples":[{"en":"This lovely village is surrounded by majestic mountain scenery.","cn":"","src":"ld"}],"media":{"uk":"media/uk/majestically__gb_1.mp3","us":"media/us/majestically__us_1.mp3"},"oxford":{"phon":"məˈdʒestɪkli","pos":"adverb","senses":[{"en":"in a way that is impressive because of its size or beauty","cn":"雄伟的；威严的；壮观的","ex":{"en":"The cliffs rise majestically from the ocean.","cn":"悬崖临海巍然耸立。"}}]}},"matter":{"media":{"uk":"media/uk/matter__gb_1.mp3","us":"media/us/matter__us_1.mp3"},"oxford":{"phon":"ˈmætə(r)","pos":"noun","senses":[{"en":"used (to ask) if somebody is upset, unhappy, etc. or if there is a problem","cn":"（用于询问某人的情况）","g":"[singular]","sc":"problem","ex":{"en":"What's the matter? Is there something wrong?","cn":"怎么了？出了什么事儿吗？"}},{"en":"a subject or situation that you must consider or deal with","cn":"课题；事情；问题","g":"[countable]","lab":"formal","sc":"subject/situation","ex":{"en":"It's a private matter.","cn":"这是件私事儿。"}},{"en":"the present situation, or the situation that you are talking about","cn":"事态；当前的状况","g":"[plural]","sc":"subject/situation","ex":{"en":"Unfortunately, there is nothing we can do to improve matters.","cn":"很遗憾，我们无力改善目前的状况。"}},{"en":"a situation that involves something or depends on something","cn":"关乎…的事情","g":"[singular]","sc":"a matter of (doing) something","ex":{"en":"Learning to drive is all a matter of coordination.","cn":"学开车主要是靠协调。"}},{"en":"physical substance that everything in the world is made of; not mind or spirit","cn":"（统称）物质","g":"[uncountable]","lab":"physics","sc":"substance","ex":{"en":"to study the properties of matter","cn":"研究物质的属性"}},{"en":"a substance or things of a particular sort","cn":"（某种）东西，物品，材料","g":"[uncountable]","lab":"formal","sc":"substance","ex":{"en":"Add plenty of organic matter to improve the soil.","cn":"施用大量的有机肥料以改良土壤。"}},{"en":"to be important or have an important effect on somebody/something","cn":"事关紧要；要紧；有重大影响","ex":{"en":"‘I'm afraid I forgot that book again.’ ‘It doesn't matter (= it is not important enough to worry about).’","cn":"“很抱歉，我又忘了把那本书带来了。”“没事儿。”"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"事情;状况;问题","en":"A matter is a task, situation, or event which you have to deal with or think about, especially one that involves problems.","ex":{"en":"It was clear that she wanted to discuss some private matter","cn":"很明显，她想谈些私事。"}},{"pos":"N-PLURAL 复数名词","cn":"事态;情况;局面","en":"You use matters to refer to the situation you are talking about, especially when something is affecting the situation in some way.","ex":{"en":"If your ordinary life is out of control, then retreating into a cosy ritual will not improve matters","cn":"如果正常生活都一团糟了，那么再讲究小情调根本无济于事。"}},{"pos":"N-SING 单数名词","cn":"(是…的)问题;取决于…的问题;关乎…的问题","en":"If you say that a situation is a matter of a particular thing, you mean that that is the most important thing to be done or considered when you are involved in the situation or explaining it.","ex":{"en":"History is always a matter of interpretation","cn":"历史总是一种阐释角度的问题。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(印刷或阅读的)材料","en":"Printed matter consists of books, newspapers, and other texts that are printed. Reading matter consists of things that are suitable for reading, such as books and newspapers.","ex":{"en":"...the Government's plans to levy VAT on printed matter.","cn":"政府对印刷品征收增值税的计划"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(有形的)物质","en":"Matter is the physical part of the universe consisting of solids, liquids, and gases.","ex":{"en":"A proton is an elementary particle of matter.","cn":"质子是物质的基本粒子。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(某一类型的)物质","en":"You use matter to refer to a particular type of substance.","ex":{"en":"They feed mostly on decaying vegetable matter.","cn":"它们大多以腐烂的蔬菜为食。"}},{"pos":"N-SING 单数名词","cn":"麻烦事;问题","en":"You use matter in expressions such as 'What's the matter?' or 'Is anything the matter?' when you think that someone has a problem and you want to know what it is.","ex":{"en":"Carole, what's the matter? You don't seem happy","cn":"卡萝尔，出什么事了？你好像不开心。"}},{"pos":"N-SING 单数名词","cn":"(强调数量少、时间短)","en":"You use matter in expressions such as 'a matter of weeks' when you are emphasizing how small an amount is or how short a period of time is.","ex":{"en":"Within a matter of days she was back at work","cn":"仅仅几天后，她又回去上班了。"}},{"pos":"VERB 动词","cn":"有关系;要紧;有影响","en":"If you say that something does not matter, you mean that it is not important to you because it does not have an effect on you or on a particular situation.","ex":{"en":"A lot of the food goes on the floor but that doesn't matter","cn":"许多食品掉在地板上，不过也没什么关系。"}},{"pos":"PHRASE 短语","cn":"另一码事；另一回事;不同情形","en":"If you say that something is another matter or a different matter, you mean that it is very different from the situation that you have just discussed.","ex":{"en":"Being responsible for one's own health is one thing, but being responsible for another person's health is quite a different matter","cn":"对自己的健康负责是一回事，对他人的健康负责就完全是另一回事了。"}},{"pos":"PHRASE 短语","cn":"出于（时间）的考虑;作为（紧急）事件（处理）","en":"If you are going to do something as a matter of urgency or priority, you are going to do it as soon as possible, because it is important.","ex":{"en":"Your doctor and health visitor can help a great deal and you need to talk about it with them as a matter of urgency.","cn":"你的医生和家访护士会帮很大的忙。你应该和他们谈一谈，这是当务之急。"}},{"pos":"PHRASE短语","cn":"难事;并非易事","en":"If something is no easy matter, it is difficult to do it.","ex":{"en":"Choosing the colour for the drawing-room walls was no easy matter.","cn":"选择客厅墙壁的颜色绝非易事。"}},{"pos":"PHRASE 短语","cn":"此事已定;(事情)到此为止，到此结束","en":"If someone says that's the end of the matter or that's an end to the matter, they mean that a decision that has been taken must not be changed or discussed any more.","ex":{"en":"'He's moving in here,' Maria said. 'So that's the end of the matter.'","cn":"“他就要搬来住了，”玛丽亚说，“那么就这么定了。”"}},{"pos":"PHRASE 短语","cn":"事实真相是;真实情况是","en":"You use the fact of the matter is or the truth of the matter is to introduce a fact which supports what you are saying or which is not widely known, for example because it is a secret.","ex":{"en":"The fact of the matter is that most people consume far more protein than they actually need","cn":"真实的情况是，大多数人摄入的蛋白质比他们实际所需的多出许多。"}},{"pos":"PHRASE 短语","cn":"同样;而且","en":"You can use for that matter to emphasize that the remark you are making is true in the same way as your previous, similar remark.","ex":{"en":"The irony was that Shawn had not seen her. Nor for that matter had anyone else","cn":"具有讽刺意味的是，肖恩并没有见过她，别人也同样如此。"}},{"pos":"CONVENTION 惯用语","cn":"不要紧;没关系","en":"You say 'it doesn't matter' to tell someone who is apologizing to you that you are not angry or upset, and that they should not worry.","ex":{"en":"'Did I wake you?' — 'Yes, but it doesn't matter.'","cn":"“我把你吵醒了？”——“是的，不过没关系。”"}},{"pos":"CONVENTION 惯用语","cn":"都行;无所谓;随便","en":"You say 'it doesn't matter' when someone offers you a choice between two or more things and you do not mind which is chosen.","ex":{"en":"'Steve, what do you want?' — 'Coke, Pepsi, it doesn't matter.'","cn":"“史蒂夫，你要喝点什么？”——“可口可乐，百事，随便啦。”"}},{"pos":"PHRASE 短语","cn":"正经事；非同儿戏","en":"If you say that something is no laughing matter, you mean that it is very serious and not something that you should laugh or joke about.","ex":{"en":"Their behaviour is an offence. It's no laughing matter.","cn":"他们这么做是犯罪，这可不是开玩笑的。"}},{"pos":"PHRASE 短语","cn":"使情况变得更糟","en":"If you say that something makes matters worse, you mean that it makes a difficult situation even more difficult.","ex":{"en":"Don't let yourself despair; this will only make matters worse","cn":"不要想不开，这样只能使情况变得更糟。"}},{"pos":"CONVENTION 惯用语","cn":"没关系;不要紧","en":"You say 'no matter' after you have just asked a question or mentioned an idea or doubt and you have decided that it is not really important, interesting, or worth discussing.","ex":{"en":"'Didn't you ever read the book?' Keating shook his head. 'Well, no matter.'","cn":"“你从没看过这本书？”基廷摇了摇头。“嗯，没关系。”"}},{"pos":"PHRASE 短语","cn":"不管…;无论…","en":"You use no matter in expressions such as 'no matter how' and 'no matter what' to say that something is true or happens in all circumstances.","ex":{"en":"No matter what your age, you can lose weight by following this program","cn":"不论年龄多大，都可以按这套方案来减肥。"}},{"pos":"PHRASE 短语","cn":"不管怎样;无论如何","en":"If you say that you are going to do something no matter what, you are emphasizing that you are definitely going to do it, even if there are obstacles or difficulties.","ex":{"en":"He had decided to publish the manuscript no matter what","cn":"他决定无论如何都要出版那部手稿。"}},{"pos":"PHRASE 短语","cn":"看法问题;看法因人而异的事情","en":"If you say that a statement is a matter of opinion, you mean that it is not a fact, and that other people, including yourself, do not agree with it.","ex":{"en":"'We're not that contrived. We're not that theatrical.' — 'That's a matter of opinion.'","cn":"“我们没那么造作，也没那么夸张。”——“见仁见智喽。”"}},{"pos":"PHRASE 短语","cn":"(只是)时间的问题（用于说明某事必定发生）","en":"If you say that something is just a matter of time, you mean that it is certain to happen at some time in the future.","ex":{"en":"It would be only a matter of time before he went through with it.","cn":"他完成这件事只是时间问题。"}},{"pos":"","cn":"","en":"a matter of life and death→see: ; as a matter of course→see: ; as a matter of fact→see: ; mind over matter→see: ;"}]},"examples":[{"en":"I know which area they live in, but whether I can find their house is a different matter.","cn":"我知道他们住在哪一地区，但能不能找到他们的房子则是另外一回事了。"},{"en":"‘I think this is the best so far.’ ‘Well, that's a matter of opinion (= other people may think differently). “","cn":"我认为这是迄今为止最好的。” “唔，仁者见仁，智者见智嘛。”"}]},"marsh":{"media":{"uk":"media/uk/marsh__gb_1.mp3","us":"media/us/marsh__us_1.mp3"},"oxford":{"phon":"mɑːʃ","pos":"noun","senses":[{"en":"an area of low land that is always soft and wet because there is nowhere for the water to flow away to","cn":"湿地；沼泽；草本沼泽","ex":{"en":"Cows were grazing on the marshes.","cn":"牛群在湿地上吃草。"}}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"沼泽;湿地","en":"A marsh is a wet, muddy area of land."}]},"examples":[{"en":"Cows were grazing on the marshes.","cn":"牛群在湿地上吃草。"},{"en":"marshy ground/land","cn":"沼泽地"}]},"masculine":{"oxford":{"phon":"ˈmæskjəlɪn","pos":"adjective","senses":[{"en":"having the qualities or appearance considered to be typical of men; connected with or like men","cn":"男子汉的；男人的；像男人的","ex":{"en":"He was handsome and strong, and very masculine.","cn":"他英俊强壮，富有男子汉气概。"}},{"en":"belonging to a class of words that refer to male people or animals and often have a special form","cn":"阳性的（用于雄性的人或动物）","lab":"grammar","ex":{"en":"‘He’ and ‘him’ are masculine pronouns.","cn":"he 和 him 都是阳性代词。"}},{"en":"belonging to a class of nouns, pronouns or adjectives that have masculine gender, not feminine or neuter","cn":"阳性的（区别于阴性和中性）","lab":"grammar","ex":{"en":"The French word for ‘sun’ is masculine.","cn":"法语单词“太阳”是阳性的。"}},{"en":"the masculine gender (= form of nouns, adjectives and pronouns)","cn":"（词语的）阳性","g":"[singular]","pos":"noun"},{"en":"a masculine word or word form","cn":"阳性词；阳性词形","g":"[countable]","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"男性的;男子的","en":"Masculine qualities and things relate to or are considered typical of men, in contrast to women.","ex":{"en":"...masculine characteristics like a husky voice and facial hair.","cn":"沙哑的嗓音和胡子拉碴的面孔之类的男性特征"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"有男子气概的;阳刚的;男子汉的","en":"If you say that someone or something is masculine, you mean that they have qualities such as strength or confidence which are considered typical of men.","ex":{"en":"...her aggressive, masculine image","cn":"她那咄咄逼人、男人般的形象"}},{"pos":"ADJ 形容词","cn":"(某些语言中的词)阳性的","en":"In some languages, a masculine noun, pronoun, or adjective has a different form from a feminine or neuter one, or behaves in a different way."}]},"media":{"uk":"media/uk/masculine__gb_1.mp3","us":"media/us/masculine__us_1.mp3"},"examples":[{"en":"He was handsome and strong, and very masculine.","cn":"他英俊强壮，富有男子汉气概。"},{"en":"That suit makes her look very masculine.","cn":"她穿那套衣服看起来很男性化。"}]},"march":{"media":{"uk":"media/uk/march__gb_1.mp3","us":"media/us/march__us_1.mp3"},"oxford":{"phon":"mɑːtʃ","pos":"verb","senses":[{"en":"to walk with stiff regular steps like a soldier","cn":"齐步走；行进","g":"[intransitive]","ex":{"en":"Quick march! (= the order to start marching)","cn":"（口令）齐步走！"}},{"en":"to walk somewhere quickly in a determined way","cn":"（坚定地向某地）前进，进发","g":"[intransitive]","ex":{"en":"She marched over to me and demanded an apology.","cn":"她毅然走过来，要我向她道歉。"}},{"en":"to walk through the streets in a large group in order to protest about something","cn":"游行示威；游行抗议","g":"[intransitive]","ex":{"en":"Millions of people marched against the war.","cn":"数百万人游行示威反对战争。"}},{"en":"to force somebody to walk somewhere with you","cn":"使同行；强迫（某人）一起走","g":"[transitive]","ex":{"en":"The guards marched the prisoner away.","cn":"卫兵押着囚犯离开了。"}},{"en":"an organized walk by many people from one place to another, in order to protest about something, or to express their opinions","cn":"示威游行；抗议游行","g":"[countable]","ex":{"en":"protest marches","cn":"抗议游行"},"pos":"noun"},{"en":"an act of marching; a journey made by marching","cn":"行进；行军","g":"[countable]","ex":{"en":"The army began their long march to the coast.","cn":"部队开始了他们开往沿海地区的长途行军。"},"pos":"noun"},{"en":"the steady development or forward movement of something","cn":"稳步发展；稳步前进","g":"[singular]","ex":{"en":"the march of progress/technology/time","cn":"平稳的进步；技术的稳步发展；时光的推移"},"pos":"noun"},{"en":"a piece of music written for marching to","cn":"进行曲","g":"[countable]","ex":{"en":"a funeral march","cn":"葬礼进行曲"},"pos":"noun"},{"en":"the 3rd month of the year, between February and April","cn":"三月","lab":"British English","ex":{"en":"She was born in March.","cn":"她出生在三月。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"三月","en":"March is the third month of the year in the Western calendar.","ex":{"en":"I flew to Milan in early March","cn":"我3月初乘飞机到了米兰。"}}]},"examples":[{"en":"She was a gifted and original artist who marched to a different drummer.","cn":"她有天赋，具独创性，是个与众不同的艺术家。"},{"en":"Time marches on and we still have not made a decision.","cn":"时间过得飞快，而我们却还没有拿定主意。"}]},"masse":{"collins":{"senses":[{"pos":"","cn":"","en":"→see: ;"}]},"media":{"uk":"media/uk/masse__gb_1.mp3","us":"media/us/masse__us_1.mp3"}},"marry":{"oxford":{"phon":"ˈmæri","pos":"verb","senses":[{"en":"to become the husband or wife of somebody; to get married to somebody","cn":"（和某人）结婚；嫁；娶","g":"[transitive, intransitive]","lab":"especially North American English","ex":{"en":"She married a German.","cn":"她嫁给了一个德国人。"}},{"en":"to perform a ceremony in which two people get married","cn":"为…主持（或举办）婚礼","g":"[transitive]","ex":{"en":"They were married by the local priest.","cn":"当地牧师为他们主持了婚礼。"}},{"en":"to find a husband or wife for somebody, especially your daughter or son","cn":"把…嫁给；为…娶亲","g":"[transitive]"},{"en":"to combine two different things, ideas, etc. successfully","cn":"（使不同的事物、观点等）相结合，结合在一起","g":"[transitive]","lab":"formal","ex":{"en":"The music business marries art and commerce.","cn":"音乐行业将艺术和商业结合在一起。"}}]},"collins":{"senses":[{"pos":"V-RECIP 相互动词","cn":"结婚;嫁;娶","en":"When two people get married or marry, they legally become husband and wife in a special ceremony. Get married is less formal and more commonly used than marry .","ex":{"en":"I thought he would change after we got married","cn":"我原以为我们结婚后他会改变的。"}},{"pos":"VERB 动词","cn":"(牧师或官员)为…主持婚礼","en":"When a priest or official marries two people, he or she conducts the ceremony in which the two people legally become husband and wife.","ex":{"en":"The local vicar has agreed to marry us in the chapel on the estate","cn":"当地的牧师已经同意在庄园的小教堂里为我们主持婚礼。"}},{"pos":"VERB 动词","cn":"把…嫁给；为…娶亲","en":"If a parent marries their child to someone, the parent chooses who their child will marry and arranges it.","ex":{"en":"He married his three daughters to princes of the ruling house.","cn":"他把三个女儿都嫁给了王室的王子。"}},{"pos":"","cn":"","en":"相关词组：marry off"}]},"media":{"uk":"media/uk/marry__gb_1.mp3","us":"media/us/marry__us_1.mp3"},"examples":[{"en":"The music business marries art and commerce.","cn":"音乐行当将艺术和商业结合在一起。"},{"en":"I guess I'm not the marrying kind (= the kind of person who wants to get married).","cn":"我觉得我不是那种想结婚的人。"}]},"marble":{"media":{"uk":"media/uk/marble__gb_1.mp3","us":"media/us/marble__us_1.mp3"},"oxford":{"phon":"ˈmɑːbl","pos":"noun","senses":[{"en":"a type of hard stone that is usually white and often has coloured lines in it. It can be polished (= made smooth and shiny by rubbing) and is used in building and for making statues, etc.","cn":"大理石","g":"[uncountable]","ex":{"en":"a slab/block of marble","cn":"一块大理石板"}},{"en":"a small ball of coloured glass that children roll along the ground in a game","cn":"（玻璃）弹子","g":"[countable]"},{"en":"a game played with marbles","cn":"弹子游戏","g":"[uncountable]","ex":{"en":"Three boys were playing marbles.","cn":"三个男孩儿在玩弹子游戏。"}},{"en":"a way of referring to somebody’s intelligence or mental ability","cn":"理智；智力","g":"[plural]","lab":"informal","ex":{"en":"He's losing his marbles (= he's not behaving in a sensible way).","cn":"他失去理智了。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"大理石","en":"Marble is a type of very hard rock which feels cold when you touch it and which shines when it is cut and polished. Statues and parts of buildings are sometimes made of marble.","ex":{"en":"The house has a superb staircase made from oak and marble","cn":"这座房子的楼梯堪称一流，是由橡木与大理石制成的。"}},{"pos":"N-COUNT 可数名词","cn":"大理石雕像","en":"Marbles are sculptures made of marble.","ex":{"en":"...marbles and bronzes from the Golden Age of Athens.","cn":"雅典黄金时代的大理石雕像与铜像"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(小孩子在地上玩的)弹子游戏，弹球游戏","en":"Marbles is a children's game played with small balls, usually made of coloured glass. You roll a ball along the ground and try to hit an opponent's ball with it.","ex":{"en":"On the far side of the street, two boys were playing marbles.","cn":"在街道的那一边，两个男孩在玩弹子游戏。"}},{"pos":"N-COUNT 可数名词","cn":"弹子;弹珠;弹球","en":"A marble is one of the small balls used in the game of marbles."},{"pos":"PHRASE 短语","cn":"失去理智;发疯;行为失常","en":"If you say that someone has lost their marbles, you mean that their ideas or behaviour are very strange, as if they have become insane.","ex":{"en":"I'll tell it to you, although you'll probably think I've lost my marbles.","cn":"就算你也许会以为我疯了，我也要把它告诉你。"}}]},"examples":[{"en":"Three boys were playing marbles.","cn":"三个男孩儿在玩弹子游戏。"},{"en":"He's losing his marbles (= he's not behaving in a sensible way).","cn":"他失去理智了。"}]},"max":{"media":{"uk":"media/uk/max__gb_1.mp3","us":"media/us/max__us_1.mp3"},"oxford":{"phon":"mæks","pos":"abbreviation","senses":[{"en":"maximum","cn":"最高的；最多的；最大极限的","lab":"especially in North American English","ex":{"en":"max temperature 18°C","cn":"最高气温 18 摄氏度"}},{"en":"at the most","cn":"至多","lab":"informal","ex":{"en":"It'll cost $50 max.","cn":"这东西至多花 50 美元。"}},{"en":"a first name for boys","cn":"马克斯（男子名）","pos":""}]},"examples":[{"en":"The car maxed out at 150 mph.","cn":"汽车达到了每小时 150 英里的最快速度。"},{"en":"She believes in living life to the max.","cn":"她认为人应当尽量活得充实。"}]},"manor":{"oxford":{"phon":"ˈmænə(r)","pos":"noun","senses":[{"en":"a large country house surrounded by land that belongs to it","cn":"庄园宅第","ex":{"en":"He bought the old manor and set about turning himself into the local squire.","cn":"他买下了那个老庄园，摇身一变成了当地的乡绅。"}},{"en":"an area of land with a manor house on it","cn":"庄园；庄园领地","ex":{"en":"the ancient manor of Tregarrick","cn":"特里盖里克古代的领地"}},{"en":"an area in which somebody works or for which they are responsible, especially officers at a police station","cn":"工作区；（尤指警察的）辖区","lab":"British English, slang，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（通常指中世纪）庄园，领地","en":"A manor is a large private house in the country, usually built in the Middle Ages, and also includes the land and smaller buildings around it.","ex":{"en":"Thieves broke into the manor at night.","cn":"小偷晚上闯进了庄园。"}},{"pos":"N-SING 单数名词","cn":"警区;警察管辖区","en":"Some people, especially police officers, refer to the area where they work as their manor .","ex":{"en":"The Chief Constable deeply resented any intrusions into his manor","cn":"警察局局长对侵入其辖区的行为深恶痛绝。"}}]},"media":{"uk":"media/uk/manor__gb_1.mp3","us":"media/us/manor__us_1.mp3"}},"man":{"media":{"uk":"media/uk/man__gb_1.mp3","us":"media/us/man__us_1.mp3"},"oxford":{"phon":"mæn","pos":"noun","senses":[{"en":"an adult male human","cn":"成年男子；男人","g":"[countable]","sc":"male person","ex":{"en":"a good-looking young man","cn":"英俊的年轻男子"}},{"en":"humans as a group, both male and female","cn":"人类；人","g":"[uncountable]","lab":"British English","sc":"humans","ex":{"en":"the damage caused by man to the environment","cn":"人类给环境带来的破坏"}},{"en":"a person, either male or female","cn":"（不论性别的）人","g":"[countable]","lab":"literary or old-fashioned","sc":"humans","ex":{"en":"All men must die.","cn":"所有的人都会死。"}},{"en":"humans from a particular period of history","cn":"（特定历史时期的）人，人类","g":"[uncountable]","lab":"British English","sc":"humans","ex":{"en":"early/modern/Prehistoric man","cn":"早期人；现代人；史前人"}},{"en":"a man who comes from the place mentioned or whose job or interest is connected with the thing mentioned","cn":"（来自某地、从事某种工作或有某种兴趣等的）人","g":"[countable]","lab":"British English","sc":"particular type of man","ex":{"en":"a Frenchman","cn":"法国人"}},{"en":"a man who likes or who does the thing mentioned","cn":"（喜欢或做某事的）人","g":"[countable]","sc":"particular type of man","ex":{"en":"a betting/fighting/drinking man","cn":"赌博／打架／喝酒的人"}},{"en":"a man who works for or supports a particular organization, comes from a particular town, etc.","cn":"（来自某处、支持某组织或为其工作的）人","g":"[countable]","sc":"particular type of man","ex":{"en":"the BBC’s man in Moscow (= the man who reports on news from Moscow)","cn":"英国广播公司驻莫斯科的新闻记者"}},{"en":"a soldier or a male worker who obeys the instructions of a person of higher rank","cn":"士兵；（男性）工人","g":"[countable, usually plural]","sc":"soldier/worker","ex":{"en":"The officer refused to let his men take part in the operation.","cn":"这军官拒绝让他的士兵参加这项军事行动。"}},{"en":"a man who comes to your house to do a job","cn":"上门服务的人","g":"[countable]","sc":"soldier/worker","ex":{"en":"the gas man","cn":"煤气工人"}},{"en":"used for addressing a male person","cn":"伙计；哥儿们","g":"[singular]","lab":"especially North American English, informal，，","sc":"form of address","ex":{"en":"Nice shirt, man!","cn":"好漂亮的衬衣啊，哥儿们！"}},{"en":"used for addressing a male person in an angry or impatient way","cn":"（不耐烦或生气时对男人的称呼）你这家伙","g":"[singular]","lab":"old-fashioned","sc":"form of address","ex":{"en":"Don't just stand there, man—get a doctor!","cn":"你这家伙，别只是站着，赶紧去找医生呀！"}},{"en":"a person's husband, boyfriend or male partner","cn":"丈夫；男友；男性伴侣","g":"[countable]","sc":"husband/boyfriend","ex":{"en":"What's her new man like?","cn":"她的新男友怎么样？"}},{"en":"a person who is strong and brave or has other qualities that some people think are typically male","cn":"勇敢强壮的人；男子汉","g":"[countable]","sc":"strong/brave person","ex":{"en":"Come on, now—be a man.","cn":"加油，像个男子汉的样子。"}},{"en":"a group or person that is thought to be in authority or control, especially the police or white people in government","cn":"头头，老板（尤指警察或白人政府要员）","g":"[singular]","lab":"North American English, informal, old-fashioned，，，，","sc":"people in authority","ex":{"en":"Activists marched to the police station to voice their displeasure with the Man.","cn":"活动人士游行到警察局，表达对上头的不满。"}},{"en":"a male servant","cn":"男仆；男佣","g":"[singular]","lab":"old-fashioned, formal，，","sc":"servant","ex":{"en":"My man will drive you home.","cn":"我的仆人会开车送你回家。"}},{"en":"one of the figures or objects that you play with in a game such as chess","cn":"棋子","g":"[countable]","sc":"in chess, etc"},{"en":"to work at a place or be in charge of a place or a machine","cn":"在…岗位上工作；操纵（机器等）","ex":{"en":"Soldiers manned barricades around the city.","cn":"士兵把守着城市周围的路障。"},"pos":"verb"},{"en":"used to express surprise, anger, etc.","cn":"（表示惊奇、气愤等）嘿，天哪","ex":{"en":"Man, that was great!","cn":"哇，太棒了！"},"pos":"exclamation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"男人;男子","en":"A man is an adult male human being.","ex":{"en":"He had not expected the young man to reappear before evening","cn":"他没想到这位年轻男子会在黄昏前再次出现。"}},{"pos":"N-VAR 可变名词","cn":"人，人类（此用法仍有争议）","en":"Man and men are sometimes used to refer to all human beings, including both males and females. Some people dislike this use.","ex":{"en":"The chick initially has no fear of man","cn":"小鸡天生并不怕人。"}},{"pos":"N-COUNT 可数名词","cn":"（有某类嗜好的）人","en":"If you say that a man is, for example, a gambling man or an outdoors man, you mean that he likes gambling or outdoor activities.","ex":{"en":"Are you a gambling man, Mr Graham?","cn":"格雷厄姆先生，你是好赌的人吗?"}},{"pos":"N-COUNT 可数名词","cn":"（来自某地的）人；（在某地上过学的）人","en":"If you say that a man is, for example, a London man or an Oxford man, you mean that he comes from London or Oxford, or went to university there.","ex":{"en":"...as the Stockport man collected his winnings","cn":"在那名来自斯托克波特的人收拢他赢的钱的时候"}},{"pos":"N-COUNT 可数名词","cn":"(某公司或组织的男性)职员，代表","en":"If you refer to a particular company's or organiza-tion's man, you mean a man who works for or represents that company or organization.","ex":{"en":"...the Daily Telegraph's man in Abu Dhabi.","cn":"《每日电讯报》驻阿布扎比的记者"}},{"pos":"N-COUNT 可数名词","cn":"(某人的)支持者，亲信","en":"If you say that a man is someone's man, you mean that he always supports that person or does what they want.","ex":{"en":"At the time he was said to be very much Rajiv Gandhi's man.","cn":"据说他当时是拉吉夫·甘地的铁杆支持者。"}},{"pos":"N-SING 单数名词","cn":"丈夫;情人;男朋友","en":"Some people refer to a woman's husband, lover, or boyfriend as her man .","ex":{"en":"...if they see your man cuddle you in the kitchen or living room.","cn":"假如他们看见你的男朋友在厨房或起居室里搂着你的话"}},{"pos":"N-PLURAL 复数名词","cn":"士兵（相对于军官而言）","en":"In the armed forces, the men are soldiers, sailors, marines, or airmen of lower rank, as opposed to the officers.","ex":{"en":"150 officers and men had to be taken straight to hospital.","cn":"不得不将150名官兵直接送往了医院。"}},{"pos":"N-PLURAL 复数名词","cn":"（尤指从事体力劳动或为上级工作的）男工，男雇员，男下属","en":"Male workers are sometimes referred to as men, especially if they do physical work or work for a more senior person.","ex":{"en":"The men voted by a four-to-one majority to accept the pay offer","cn":"男雇员以4比1的多数票接受了工资条件。"}},{"pos":"N-VOC 称呼名词","cn":"(对男子的称呼，表示生气或不耐烦)老兄，老弟，小伙子","en":"One man sometimes addresses another as 'man' when he is angry or impatient with him.","ex":{"en":"I told you, man! It'll be sometime after eight o'clock.","cn":"老兄，我告诉过你了，时间是八点以后。"}},{"pos":"N-VOC 称呼名词","cn":"（在非正式场合中用以称呼男子）老弟,老兄","en":"In very informal social situations, man is sometimes used as a greeting or form of address to a man.","ex":{"en":"Hey wow, man! Where d'you get those boots?","cn":"哎哟，老弟，哪里搞来的靴子？"}},{"pos":"VERB 动词","cn":"在…岗位上工作;操作(机器等)","en":"If you man something such as a place or machine, you operate it or are in charge of it.","ex":{"en":"French soldiers manned roadblocks in the capital city.","cn":"法国士兵把守着首都的各路关卡。"}},{"pos":"PHRASE 短语","cn":"有足够的勇气(或能力)","en":"If you say that a man is man enough to do something, you mean that he has the necessary courage or ability to do it.","ex":{"en":"I told him that he should be man enough to admit he had done wrong","cn":"我对他说，他应该勇于承认错误。"}},{"pos":"PHRASE 短语","cn":"更受男人（而非女人）欢迎的男人","en":"If you describe a man as a man's man, you mean that he has qualities which make him popular with other men rather than with women."},{"pos":"CONVENTION 惯用语","cn":"老兄;老弟","en":"People sometimes address a man as my man .","ex":{"en":"'Get the guy in the purple shirt.' — 'All right, my man.'","cn":"“把那个穿紫衬衫的家伙叫过来。”——“好的，老兄。”"}},{"pos":"CONVENTION 惯用语","cn":"我的老兄，我的老弟(对地位比自己低的人的友好称呼，但略带屈尊俯就之意)","en":"people sometimes address a man as my man ,my dear man, or my good man. This form of address is often friendly, but can also suggest that the speaker feels superior to the person being addressed.","ex":{"en":"My dear man, you are welcome to stay","cn":"我的老弟，欢迎你留下来。"}},{"pos":"PHRASE 短语","cn":"能自己做主;无须听命于他人","en":"If you say that a man is his own man, you approve of the fact that he makes his decisions and his plans himself, and does not depend on other people.","ex":{"en":"Be your own man. Make up your own mind","cn":"要有主见，你自己做主吧。"}},{"pos":"PHRASE 短语","cn":"一致;毫无例外","en":"If you say that a group of men are, do, or think something to a man, you are emphasizing that every one of them is, does, or thinks that thing.","ex":{"en":"To a man, the surveyors blamed the government","cn":"调查员们无一例外地都指责政府。"}},{"pos":"PHRASE 短语","cn":"私下的;一对一的;开诚布公的","en":"A man-to-man conversation or meeting takes place between two men, especially two men who meet to discuss a serious personal matter.","ex":{"en":"He called me to his office for a man-to-man talk","cn":"他把我叫到他的办公室私下谈了谈。"}},{"pos":"","cn":"","en":"the man in the street→see: ; man about town→see: ; man of the world→see: ;"}]},"examples":[{"en":"He's been doing the same job for 50 years — man and boy.","cn":"他从小就干着同一份工作，有 50 年了。"},{"en":"The officer refused to let his men take part in the operation.","cn":"这军官拒绝让他的士兵参加这项军事行动。"}]},"manages":{"oxford":{"phon":"ˈmænɪdʒ","pos":"verb","senses":[{"en":"to succeed in doing sth, especially sth difficult","cn":"完成（困难的事）；勉力完成"},{"en":"to be able to solve your problems, deal with a difficult situation, etc.","cn":"能解决（问题）；应付（困难局面等）"}]},"media":{"uk":"media/uk/manage__gb_1.mp3","us":"media/us/manage__us_1.mp3"}},"mayor":{"media":{"uk":"media/uk/mayor__gb_1.mp3","us":"media/us/mayor__us_1.mp3"},"oxford":{"phon":"meə(r)","pos":"noun","senses":[{"en":"the head of the government of a town or city, etc., elected by the public","cn":"（民选的）市长，镇长","ex":{"en":"the Mayor of New York","cn":"纽约市长"}},{"en":"(in England, Wales and Northern Ireland) the head of a town, borough or county council, chosen by other members of the council to represent them at official ceremonies, etc.","cn":"（英格兰、威尔士和北爱尔兰由议员选举产生的）镇长，市长，郡长"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"市长","en":"The mayor of a town or city is the person who has been elected to represent it for a fixed period of time or, in some places, to run its government."}]},"examples":[{"en":"Mayor Bob Anderson","cn":"鲍勃 · 安德森市长"},{"en":"mayoral robes/duties","cn":"市长的礼袍/职责"}]},"majority":{"media":{"uk":"media/uk/majority__gb_1.mp3","us":"media/us/majority__us_1.mp3"},"oxford":{"phon":"məˈdʒɒrəti","pos":"noun","senses":[{"en":"the largest part of a group of people or things","cn":"大部分；大多数","g":"[singular + singular or plural verb]","ex":{"en":"The majority of people interviewed prefer TV to radio.","cn":"大多数接受采访的人都喜欢看电视多于听收音机。"}},{"en":"the number of votes by which one political party wins an election; the number of votes by which one side in a discussion, etc. wins","cn":"（获胜的）票数；多数票","g":"[countable]","lab":"especially North American English","ex":{"en":"She was elected by a majority of 749.","cn":"她以 749 票的多数票当选。"}},{"en":"the difference between the number of votes given to the candidate who wins the election and the total number of votes of all the other candidates","cn":"超出其余各方票数总和的票数","g":"[countable]","lab":"North American English","ex":{"en":"Without this shift, Kerry would have had a popular majority of a million votes.","cn":"如果没有这种改变，克里会比其他候选人得票数多出 100 万张。"}},{"en":"the age at which you are legally considered to be an adult","cn":"成年的法定年龄","g":"[uncountable]","lab":"law","ex":{"en":"The age of majority in Britain was reduced from 21 to 18 in 1970.","cn":"1970年，英国的法定成年年龄从21岁降至18岁。"}}]},"collins":{"senses":[{"pos":"N-SING-COLL 单数集合名词","cn":"多数;大多数","en":"The majority of people or things in a group is more than half of them.","ex":{"en":"The majority of my patients come to me from out of town","cn":"大多数来找我看病的患者都是外省人。"}},{"pos":"N-COUNT 可数名词","cn":"多数票;超过对方的票数","en":"A majority is the difference between the number of votes or seats in parliament or legislature that the winner gets in an election, and the number of votes or seats that the next person or party gets.","ex":{"en":"Members of parliament approved the move by a majority of ninety-nine","cn":"议员以99张的多数票批准了这项动议。"}},{"pos":"ADJ 形容词","cn":"(观点、决定、体制等)多数人支持的，多数人拥护的","en":"Majority is used to describe opinions, decisions, and systems of government that are supported by more than half the people involved.","ex":{"en":"...her continuing disagreement with the majority view","cn":"她与大多数人的观点依旧不一致"}},{"pos":"N-UNCOUNT 不可数名词","cn":"法定成年年龄(英国和美国大多数州规定为18周岁)","en":"Majority is the state of legally being an adult. In Britain and most states in the United States, people reach their majority at the age of eighteen.","ex":{"en":"The age of majority in Romania is eighteen","cn":"罗马尼亚的法定成年年龄为18周岁。"}}]},"examples":[{"en":"The majority of people interviewed prefer TV to radio.","cn":"大多数接受采访的人都喜欢看电视多于听收音机。"},{"en":"They had a large majority over their nearest rivals.","cn":"他们所得的票数远远超出名次仅次于他们的对手。"}]},"manufacture":{"media":{"uk":"media/uk/manufacture__gb_1.mp3","us":"media/us/manufacture__us_1.mp3"},"oxford":{"phon":"ˌmænjuˈfæktʃə(r)","pos":"verb","senses":[{"en":"to make goods in large quantities, using machines","cn":"（用机器）大量生产，成批制造","ex":{"en":"manufactured goods","cn":"工业品"}},{"en":"to invent a story, an excuse, etc.","cn":"编造；捏造","ex":{"en":"a news story manufactured by an unscrupulous journalist","cn":"一个不道德的记者编造的一篇新闻报道"}},{"en":"to produce a substance","cn":"生成，产生（一种物质）","lab":"specialist","ex":{"en":"Vitamins cannot be manufactured by our bodies.","cn":"维生素无法由人体生成。"}},{"en":"the process of producing goods in large quantities","cn":"大量制造；批量生产","g":"[uncountable]","ex":{"en":"the manufacture of cars","cn":"汽车制造"},"pos":"noun"},{"en":"manufactured goods","cn":"工业品","g":"[plural]","lab":"specialist","ex":{"en":"a major importer of cotton manufactures","cn":"棉花制品的主要进口商"},"pos":"noun"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"（通常指大量）制造，生产","en":"To manufacture something means to make it in a factory, usually in large quantities.","ex":{"en":"They manufacture the class of plastics known as thermoplastic materials","cn":"他们生产这类被称为热塑材料的塑料制品。"}},{"pos":"N-COUNT 可数名词","cn":"产品；制造品;工业品","en":"Manufactures are goods or products which have been made in a factory.","ex":{"en":"...a long-term rise in the share of manufactures in nonoil exports.","cn":"非石油出口产品中工业品份额的长期增长"}},{"pos":"VERB 动词","cn":"虚构;捏造","en":"If you say that someone manufactures information, you are criticizing them because they invent information that is not true.","ex":{"en":"According to the prosecution, the officers manufactured an elaborate story","cn":"根据控方意见，官员们精心编造了事情经过。"}}]},"examples":[{"en":"a news story manufactured by an unscrupulous journalist","cn":"一个不道德的记者编造的一篇报道"},{"en":"Vitamins cannot be manufactured by our bodies.","cn":"维生素不能由人体来生成。"}]},"malt":{"oxford":{"phon":"mɔːlt","pos":"noun","senses":[{"en":"grain, usually barley, that has been left in water for a period of time and then dried, used for making beer, whisky, etc.","cn":"麦芽","g":"[uncountable]"},{"en":"high-quality whisky made only from malt, not from ordinary grain; a glass of this","cn":"（一杯）麦芽威士忌","g":"[uncountable, countable]"},{"en":"a hot or cold drink made from malt and dried milk mixed with water or milk and usually sugar, sometimes with ice cream and/or chocolate added","cn":"麦乳精；麦芽奶","g":"[uncountable, countable]","lab":"North American English"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（用以酿制威士忌、啤酒和其他酒类的）麦芽","en":"Malt is a substance made from grain that has been soaked in water and then dried in a hot oven. Malt is used in the production of whisky, beer, and other alcoholic drinks.","ex":{"en":"German beer has traditionally been made from just four ingredients — hops, malt, yeast and water.","cn":"德国啤酒传统上只用4种原料——啤酒花、麦芽、酵母和水。"}},{"pos":"N-MASS 物质名词","cn":"同 malt whisky","en":"Malt is the same as malt whisky ."},{"pos":"N-COUNT 可数名词","cn":"(用麦乳精与其他调味品制成的)麦乳精饮料","en":"A malt is a drink made from malted milk and sometimes other flavourings."}]},"media":{"uk":"media/uk/malt__gb_1.mp3","us":"media/us/malt__us_2.mp3"},"examples":[{"en":"a cheeseburger and a chocolate malt","cn":"奶酪汉堡包和巧克力味麦乳精饮料"}]},"marquee":{"media":{"uk":"media/uk/marquee__gb_1.mp3","us":"media/us/marquee__us_1.mp3"},"oxford":{"phon":"mɑːˈkiː","pos":"noun","senses":[{"en":"a large tent used at social events","cn":"（大型活动用的）大帐篷","lab":"especially British English","ex":{"en":"The guests sat under a large marquee.","cn":"客人们坐在大帐篷下面。"}},{"en":"a covered entrance to a theatre, hotel, etc., often with a sign on or above it","cn":"（戏院、酒店等入口处，通常带有标记的）遮檐","lab":"North American English"},{"en":"most important or most popular","cn":"最重要的；最受欢迎的；杰出的","ex":{"en":"He is one of the marquee names in men's tennis.","cn":"他是男子网球界大名鼎鼎的人物之一。"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"大帐篷(户外活动时用作餐饮场所)","en":"A marquee is a large tent which is used at a fair, garden party, or other outdoor event, usually for eating and drinking in."},{"pos":"N-COUNT 可数名词","cn":"(饭店、剧院等入口处的)遮篷,遮檐","en":"A marquee is a cover over the entrance of a building, for example a hotel or a theatre.","ex":{"en":"...the marquees of Broadway.","cn":"百老汇的遮檐"}}]},"examples":[{"en":"He is one of the marquee names in men's tennis.","cn":"他是男子网球坛大名鼎鼎的人物之一。"}]},"matrimony":{"media":{"uk":"media/uk/matrimony__gb_1.mp3","us":"media/us/matrimony__us_1.mp3"},"oxford":{"phon":"ˈmætrɪməni","pos":"noun","senses":[{"en":"marriage; the state of being married","cn":"婚配","ex":{"en":"holy matrimony","cn":"婚配圣事"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"婚姻","en":"Matrimony is marriage.","ex":{"en":"...the bonds of matrimony.","cn":"婚姻的纽带"}}]},"examples":[{"en":"holy matrimony","cn":"婚配圣事"},{"en":"They were joined together in holy matrimony .","cn":"他们通过神圣的婚姻结合在一起。"}]},"materialize":{"media":{"uk":"media/uk/materialize__gb_1.mp3","us":"media/us/materialize__us_1.mp3"},"oxford":{"phon":"məˈtɪəriəlaɪz","pos":"verb","senses":[{"en":"to take place or start to exist as expected or planned","cn":"实现；发生；成为现实","g":"[intransitive]","ex":{"en":"The promotion he had been promised failed to materialize.","cn":"答应给他晋升的许诺未能实现。"}},{"en":"to appear suddenly and/or in a way that cannot be explained","cn":"突然显现；奇怪地出现","g":"[intransitive]","lab":"informal","ex":{"en":"A tall figure suddenly materialized at her side.","cn":"一个高高的身影突然出现在她的身边。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"变为现实;实现;发生;出现","en":"If a possible or expected event does not materialize, it does not happen.","ex":{"en":"A rebellion by radicals failed to materialize","cn":"激进分子的叛乱没有得逞。"}},{"pos":"VERB 动词","cn":"突然出现;显形;现身","en":"If a person or thing materializes, they suddenly appear, after they have been invisible or in another place.","ex":{"en":"Tamsin materialized at her side, notebook at the ready","cn":"塔姆辛从她身旁冒了出来，且备好了笔记本。"}}]},"examples":[{"en":"A tall figure suddenly materialized at her side.","cn":"一个高高的身影突然出现在她的身边。"},{"en":"The promotion he had been promised failed to materialize.","cn":"答应给他晋升的许诺未能实现。"}]},"mass":{"media":{"uk":"media/uk/mass__gb_1.mp3","us":"media/us/mass__us_1.mp3"},"oxford":{"phon":"mæs","pos":"noun","senses":[{"en":"a large amount of a substance that does not have a definite shape or form","cn":"团；块；堆","g":"[countable]","ex":{"en":"She saw a large dark mass in the water.","cn":"她看到水中有一团黑色的大团。"}},{"en":"a large amount or quantity of something","cn":"大量；许多","g":"[countable, usually singular]","ex":{"en":"a mass of blonde hair","cn":"一头金发"}},{"en":"a large number of people or things grouped together, often in a confused way","cn":"（常指混乱的）一群，一堆","g":"[singular]","ex":{"en":"I struggled through the mass of people to the exit.","cn":"我在人群里挤来挤去，挤到了出口处。"}},{"en":"a large number or amount of something","cn":"大量；许多","g":"[plural]","lab":"informal","ex":{"en":"There were masses of people in the shops yesterday.","cn":"昨天商店里人如潮涌。"}},{"en":"the ordinary people in society who are not leaders or who are considered to be not very well educated","cn":"群众；平民百姓","g":"[plural]","ex":{"en":"government attempts to suppress dissatisfaction among the masses","cn":"政府试图压制群众不满情绪的做法"}},{"en":"the most; the majority","cn":"大多数；多数","g":"[singular]","ex":{"en":"The reforms are unpopular with the mass of teachers and parents.","cn":"大多数教师和家长并不赞成这些改革。"}},{"en":"the quantity of material that something contains","cn":"质量","g":"[uncountable, countable]","lab":"specialist","ex":{"en":"calculating the mass of a planet","cn":"计算一个行星的质量"}},{"en":"affecting or involving a large number of people or things","cn":"大批的；数量极多的；广泛的","ex":{"en":"The world faces the tremendous problem of mass unemployment.","cn":"世界面临着大规模失业的巨大问题。"},"pos":"adjective"},{"en":"to come together in large numbers; to gather people or things together in large numbers","cn":"集结；聚集","ex":{"en":"Demonstrators had massed outside the embassy.","cn":"示威者聚集在大使馆的外面。"},"pos":"verb"},{"en":"(especially in the Roman Catholic Church) a ceremony held in memory of the last meal that Christ had with his disciples","cn":"（尤指罗马天主教的）弥撒","g":"[uncountable, countable]","ex":{"en":"to go to Mass","cn":"参加弥撒"}},{"en":"a piece of music that is written for the prayers, etc. of this ceremony","cn":"弥撒曲","g":"[countable]","ex":{"en":"Bach’s Mass in B minor","cn":"巴赫的 B 小调弥撒曲"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"(聚成一体的)一团，一堆,一块","en":"A mass of things is a large number of them grouped together.","ex":{"en":"On his desk is a mass of books and papers.","cn":"他的书桌上有大堆的书籍和文件。"}},{"pos":"N-SING 单数名词","cn":"大堆;许多;大量","en":"A mass of something is a large amount of it.","ex":{"en":"She had a mass of auburn hair.","cn":"她有一头浓密的棕发。"}},{"pos":"QUANT 数量词","cn":"大量;许多;一大堆","en":"Masses of something means a great deal of it.","ex":{"en":"There's masses of work for her to do","cn":"她有一大堆的工作要做。"}},{"pos":"ADJ 形容词","cn":"一大群的;大批的","en":"Mass is used to describe something which involves or affects a very large number of people.","ex":{"en":"...ideas on combating mass unemployment","cn":"对付大量失业的点子"}},{"pos":"N-COUNT 可数名词","cn":"(尤指无固定形状的)块，堆，团","en":"A mass of a solid substance, a liquid, or a gas is an amount of it, especially a large amount which has no definite shape.","ex":{"en":"...before it cools and sets into a solid mass","cn":"在它冷却成为固态之前"}},{"pos":"N-PLURAL 复数名词","cn":"（与领导或受过高等教育的人相对的）普通老百姓，民众，平民大众","en":"If you talk about the masses, you mean the ordinary people in society, in contrast to the leaders or the highly educated people.","ex":{"en":"His music is commercial. It is aimed at the masses","cn":"他的音乐走商业化路线，针对的是一般大众。"}},{"pos":"N-SING 单数名词","cn":"(民众中的)大部分，大多数","en":"The mass of people are most of the people in a country, society, or group.","ex":{"en":"The 1939-45 world war involved the mass of the population","cn":"1939至1945年间的世界大战使大多数民众卷入其中。"}},{"pos":"N-COUNT 可数名词","cn":"（人）一大群，一大堆","en":"A mass of people is a large crowd of them.","ex":{"en":"...masses of excited people clogged the streets.","cn":"情绪激动的人群挤满了街道。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)聚集;(使)集中;(使)集结","en":"When people or things mass, or when you mass them, they gather together into a large crowd or group.","ex":{"en":"Shortly after the workers went on strike, police began to mass at the shipyard","cn":"工人们罢工后不久，警察就开始在船厂集结。"}},{"pos":"N-SING 单数名词","cn":"充满;布满","en":"If you say that something is a mass of things, you mean that it is covered with them or full of them.","ex":{"en":"His body was a mass of sores","cn":"他遍体鳞伤。"}},{"pos":"N-VAR 可变名词","cn":"(物理学中的)质量","en":"In physics, the mass of an object is the amount of physical matter that it has.","ex":{"en":"Astronomers know that Pluto and Triton have nearly the same size, mass, and density.","cn":"天文学家知道冥王星与海卫一拥有几乎相同的体积、质量与密度。"}},{"pos":"N-VAR 可变名词","cn":"弥撒(尤指天主教或东正教的圣餐仪式，以此纪念耶稣基督的最后的晚餐)","en":"Mass is a Christian church ceremony, especially in a Roman Catholic or Orthodox church, during which people eat bread and drink wine in order to remember the last meal of Jesus Christ.","ex":{"en":"She attended a convent school and went to Mass each day.","cn":"她上的是教会学校，每天都去做弥撒。"}},{"pos":"N-COUNT 可数名词","cn":"弥撒曲","en":"A Mass is a piece of music which uses the prayers from the Christian ceremony of Mass as the words that are sung."}]},"examples":[{"en":"Bach's Mass in B minor","cn":"巴赫的 B 小调弥撒曲"},{"en":"a priest celebrating/saying Mass","cn":"主持弥撒的神父"}]},"magnificent":{"media":{"uk":"media/uk/magnificent__gb_1.mp3","us":"media/us/magnificent__us_1.mp3"},"oxford":{"phon":"mæɡˈnɪfɪsnt","pos":"adjective","senses":[{"en":"extremely attractive and impressive; deserving praise","cn":"壮丽的；宏伟的；值得赞扬的","ex":{"en":"The Taj Mahal is a magnificent building.","cn":"泰姬陵是一座宏伟的建筑。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"宏伟的;壮丽的;令人印象深刻的","en":"If you say that something or someone is magnificent, you mean that you think they are extremely good, beautiful, or impressive.","ex":{"en":"...a magnificent country house in wooded grounds.","cn":"绿树掩映中的一幢乡间豪宅"}}]},"examples":[{"en":"The public have responded magnificently to our appeal.","cn":"对于我们的呼吁，公众的反响极为热烈。"},{"en":"She looked magnificent in her wedding dress.","cn":"她穿着婚纱，看上去漂亮极了。"}]},"manufacturer":{"media":{"uk":"media/uk/manufacturer__gb_1.mp3","us":"media/us/manufacturer__us_1.mp3"},"oxford":{"phon":"ˌmænjuˈfæktʃərə(r)","pos":"noun","senses":[{"en":"a person or company that produces goods in large quantities","cn":"生产者；制造者；生产商","ex":{"en":"a car/computer manufacturer","cn":"汽车／计算机制造商"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"生产商;制造商","en":"A manufacturer is a business or company which makes goods in large quantities to sell.","ex":{"en":"...the world's largest doll manufacturer.","cn":"全球最大的玩偶生产商"}}]},"examples":[{"en":"Faulty goods should be returned to the manufacturers.","cn":"有问题的产品应退还生产厂家。"},{"en":"Always follow the manufacturer's instructions.","cn":"务必按厂家的用法说明使用。"}]},"manipulate":{"media":{"uk":"media/uk/manipulate__gb_1.mp3","us":"media/us/manipulate__us_1.mp3"},"oxford":{"phon":"məˈnɪpjuleɪt","pos":"verb","senses":[{"en":"to control or influence somebody/something, often in a dishonest way so that they do not realize it","cn":"（暗中）控制，操纵，影响","lab":"disapproving","ex":{"en":"She uses her charm to manipulate people.","cn":"她利用自身的魅力来摆布别人。"}},{"en":"to control, use or change something with skill","cn":"（熟练地）操作，使用，改变","lab":"formal","ex":{"en":"to manipulate the gears and levers of a machine","cn":"熟练地操纵机器的排挡和变速杆"}},{"en":"to move a person’s bones or joints into the correct position","cn":"正骨；治疗脱臼","lab":"specialist"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"摆布，操纵，控制(他人)","en":"If you say that someone manipulates people, you disapprove of them because they skilfully force or persuade people to do what they want.","ex":{"en":"He is a very difficult character. He manipulates people","cn":"他是个极难对付的角色，总是把人玩弄于股掌之间。"}},{"pos":"VERB 动词","cn":"摆布，操纵，处理(事件或局势)","en":"If you say that someone manipulates an event or situation, you disapprove of them because they use or control it for their own benefit, or cause it to develop in the way they want.","ex":{"en":"She was unable, for once, to control and manipulate events","cn":"她仅有一次没能控制和处理好局势。"}},{"pos":"VERB 动词","cn":"操作; 使用","en":"If you manipulate something that requires skill, such as a complicated piece of equipment or a difficult idea, you operate it or process it.","ex":{"en":"The technology uses a pen to manipulate a computer","cn":"这项技术使用一支笔来操作电脑。"}},{"pos":"VERB 动词","cn":"使脱臼复位;用推拿术治疗","en":"If someone manipulates your bones or muscles, they skilfully move and press them with their hands in order to push the bones into their correct position or make the muscles less stiff.","ex":{"en":"The way he can manipulate my leg has helped my arthritis so much.","cn":"他为我的腿实施的推拿术治疗对我的关节炎大有好处。"}}]},"examples":[{"en":"As a politician, he knows how to manipulate public opinion.","cn":"身为一位政客，他知道如何左右公众舆论。"},{"en":"They managed to manipulate us into agreeing to help.","cn":"他们总算促使我们答应提供帮助了。"}]},"machinery":{"media":{"uk":"media/uk/machinery__gb_1.mp3","us":"media/us/machinery__us_1.mp3"},"oxford":{"phon":"məˈʃiːnəri","pos":"noun","senses":[{"en":"machines as a group, especially large ones","cn":"（统称）机器；（尤指）大型机器","g":"[uncountable]","ex":{"en":"agricultural/industrial machinery","cn":"农业／工业机械"}},{"en":"the parts of a machine that make it work","cn":"机器的运转部分；机械装置","g":"[uncountable]","ex":{"en":"a clock with all its machinery hanging out","cn":"一个时钟，所有的机械装置都挂在外面"}},{"en":"the organization or structure of something; the system for doing something","cn":"组织；机构；系统；体制","g":"[uncountable, singular]","ex":{"en":"the machinery of government","cn":"政府机构"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(总称)机器，机械","en":"You can use machinery to refer to machines in general, or machines that are used in a factory or on a farm.","ex":{"en":"...quality tools and machinery.","cn":"质量上乘的工具和机械"}},{"pos":"N-SING 单数名词","cn":"(国家)机构;机制;组织","en":"The machinery of a government or organization is the system and all the procedures that it uses to deal with things.","ex":{"en":"The machinery of democracy could be created quickly.","cn":"民主制度可以迅速建立起来。"}}]},"examples":[{"en":"There is no machinery for resolving disputes.","cn":"根本没有解决纷争的机制。"},{"en":"agricultural/industrial machinery","cn":"农业/工业机械"}]},"marketing":{"media":{"uk":"media/uk/marketing__gb_1.mp3","us":"media/us/marketing__us_1.mp3"},"oxford":{"phon":"ˈmɑːkɪtɪŋ","pos":"noun","senses":[{"en":"the activity of presenting, advertising and selling a company’s products or services in the best possible way","cn":"市场营销","lab":"North American English","ex":{"en":"a marketing campaign/strategy","cn":"市场营销活动／策略"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"市场营销;营销","en":"Marketing is the organization of the sale of a product, for example, deciding on its price, the areas it should be supplied to, and how it should be advertised.","ex":{"en":"...expert advice on production and marketing.","cn":"对生产和营销的专业建议"}}]},"examples":[{"en":"a company that is a developer and marketer of software","cn":"一家软件开发和销售公司"},{"en":"She works in sales and marketing.","cn":"她在市场营销部工作。"}]},"mathematical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"数学的;数学方面的","en":"Something that is mathematical involves numbers and calculations.","ex":{"en":"...mathematical calculations","cn":"数学计算"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(具有)数学(头脑)的;运算能力强的","en":"If you have mathematical abilities or a mathematical mind, you are clever at doing calculations or understanding problems that involve numbers.","ex":{"en":"...children who display extraordinary mathematical ability.","cn":"显示出不凡的数学能力的儿童"}}]},"media":{"uk":"media/uk/mathematical__gb_1.mp3","us":"media/us/mathematical__us_1.mp3"},"examples":[{"en":"mathematical calculations/problems/models","cn":"数学计算/问题/模型"},{"en":"to assess children's mathematical ability","cn":"评定孩子们的计算能力"}],"oxford":{"phon":"ˌmæθəˈmætɪkl","pos":"adjective","senses":[{"en":"connected with or involving mathematics","cn":"数学的","ex":{"en":"mathematical calculations/problems/models","cn":"数学计算／题／模型"}}]}},"mark":{"media":{"uk":"media/uk/mark__gb_1.mp3","us":"media/us/mark__us_1.mp3"},"oxford":{"phon":"mɑːk","pos":"verb","senses":[{"en":"to write or draw a symbol, line, etc. on something in order to give information about it","cn":"做记号；做标记","g":"[transitive]","sc":"write/draw","ex":{"en":"The flood level is marked by a white line on the wall.","cn":"洪水水位在墙上用白线作了标记。"}},{"en":"to give marks to students’ work","cn":"给（学生作业）打分，评分，评成绩","g":"[transitive, intransitive]","lab":"especially British English","sc":"give mark/grade","ex":{"en":"I hate marking exam papers.","cn":"我讨厌阅卷。"}},{"en":"to make a mark on something in a way that damages it or makes it look less good; to become damaged or be made to look less good in this way","cn":"留下痕迹；弄污；使有污点","g":"[transitive, intransitive]","sc":"damage","ex":{"en":"A large purple scar marked his cheek.","cn":"他的面颊上有一块大紫疤。"}},{"en":"to show the position of something","cn":"标明方位；标示","g":"[transitive]","sc":"show position","ex":{"en":"Yellow arrows mark the way.","cn":"黄色箭头指示方向。"}},{"en":"to celebrate or officially remember an event that you consider to be important","cn":"纪念；庆贺","g":"[transitive]","sc":"celebrate","ex":{"en":"a ceremony to mark the 50th anniversary of the end of the war","cn":"纪念战争结束 50 周年的庆典"}},{"en":"to be a sign that something new is going to happen","cn":"是…的迹象；成为…的征兆；表明","g":"[transitive]","sc":"show change","ex":{"en":"This agreement marks the start of a new phase in international relations.","cn":"这一协议标志着国际关系新时期的到来。"}},{"en":"to give somebody/something a particular quality or character","cn":"赋予特征；给…确定性质","g":"[transitive, usually passive]","lab":"formal","sc":"give particular quality","ex":{"en":"a life marked by suffering","cn":"痛苦的一生"}},{"en":"used to tell somebody to pay careful attention to something","cn":"留心；留意；注意","g":"[transitive]","lab":"old-fashioned","sc":"pay attention","ex":{"en":"There'll be trouble over this, mark my words.","cn":"记住我的话，这件事是会有麻烦的。"}},{"en":"to stay close to an opponent in order to prevent them from getting the ball","cn":"盯人防守；钉住（对手）","g":"[transitive]","lab":"British English","sc":"in sport","ex":{"en":"Hughes was marking Taylor.","cn":"休斯在盯防泰勒。"}},{"en":"a written or printed symbol that is used as a sign of something, for example the quality of something or who made or owns it","cn":"符号；记号；（显示质量、制造者或所有者等的）标记","sc":"symbol","ex":{"en":"punctuation marks","cn":"标点符号"},"pos":"noun"},{"en":"a number or letter that is given to show the standard of somebody’s work or performance or is given to somebody for answering something correctly","cn":"成绩；分数；等级","lab":"especially British English","sc":"standard/grade","ex":{"en":"to get a good/poor mark in English","cn":"英语得分高／低"},"pos":"noun"},{"en":"a point given for a correct answer in an exam or competition","cn":"（考试或竞赛的）分，分数","lab":"especially British English","sc":"standard/grade","ex":{"en":"You get two marks for each correct answer.","cn":"每个正确答案得两分。"},"pos":"noun"},{"en":"a small area of dirt, a spot or a cut on a surface that makes it look less good","cn":"污点；污渍；斑点；疤痕","sc":"spot/dirt","ex":{"en":"The children left dirty marks all over the kitchen floor.","cn":"孩子们把厨房的地板弄得污渍斑斑。"},"pos":"noun"},{"en":"a spot or area of colour on the body of a person or an animal that helps you to recognize them","cn":"（人或动物身上有助于识别的）斑点，记号，色斑","sc":"spot/dirt","ex":{"en":"a horse with a white mark on its head","cn":"头上有块白斑的马"},"pos":"noun"},{"en":"a sign that a quality or feeling exists","cn":"（品质或情感的）标志，迹象，表示","sc":"sign","ex":{"en":"On the day of the funeral businesses remained closed as a mark of respect.","cn":"葬礼那天，商户停业以示敬意。"},"pos":"noun"},{"en":"a level or point that something reaches that is thought to be important","cn":"（重要的）水平，标准点，指标","sc":"level","ex":{"en":"Unemployment has passed the four million mark.","cn":"失业人数已突破四百万大关。"},"pos":"noun"},{"en":"a particular type or model of a machine or vehicle","cn":"型号","sc":"machine/vehicle","ex":{"en":"the Mark II engine","cn":"II 型发动机"},"pos":"noun"},{"en":"a particular level of temperature in a gas oven","cn":"燃气挡；温度刻度","lab":"British English","sc":"in gas oven","ex":{"en":"Preheat the oven to gas Mark 6.","cn":"将烤箱预热到 6 挡。"},"pos":"noun"},{"en":"a cross made on a document instead of a signature by somebody who is not able to write their name","cn":"（不会写名字的人在文件上代替签名的）花押","sc":"for signing document","pos":"noun"},{"en":"a target","cn":"目标；靶子","lab":"formal","sc":"target","ex":{"en":"Of the blows delivered, barely half found their mark.","cn":"仅有不到半数的出拳击中目标。"},"pos":"noun"},{"en":"the former unit of money in Germany (replaced in 2002 by the euro)","cn":"德国马克（德国货币单位，于 2002 年为欧元所取代）","sc":"German money","pos":"noun"},{"en":"a first name for boys","cn":"马克（男子名）","pos":""}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"斑点;污点;污迹","en":"A mark is a small area of something such as dirt that has accidentally got onto a surface or piece of clothing.","ex":{"en":"The dogs are always rubbing against the wall and making dirty marks","cn":"那些狗老是往墙上蹭，留下了斑斑污迹。"}},{"pos":"V-ERG 及物/不及物动词","cn":"（使）留下印迹;（使）留下污痕","en":"If something marks a surface, or if the surface marks, the surface is damaged by marks or a mark.","ex":{"en":"Leather overshoes were put on the horses' hooves to stop them marking the turf","cn":"马蹄上套了皮套子，以免弄脏赛马场。"}},{"pos":"N-COUNT 可数名词","cn":"记号;符号","en":"A mark is a written or printed symbol, for example a letter of the alphabet.","ex":{"en":"He made marks with a pencil.","cn":"他用铅笔做了记号。"}},{"pos":"VERB 动词","cn":"标示;为…作记号;为…作标记","en":"If you mark something with a particular word or symbol, you write that word or symbol on it.","ex":{"en":"The bank marks the check 'certified'","cn":"银行在支票上标有“保付”的字样。"}},{"pos":"N-COUNT 可数名词","cn":"(考试或竞赛的)成绩，分数","en":"A mark is a point that is given for a correct answer or for doing something well in an exam or competition. A mark can also be a written symbol such as a letter that indicates how good a student's or competitor's work or performance is.","ex":{"en":"...a simple scoring device of marks out of 10, where '1' equates to 'Very poor performance'","cn":"简单的十分评分制，其中“1”即“极差”"}},{"pos":"N-PLURAL 复数名词","cn":"评价","en":"If someone gets good or high marks for doing something, they have done it well. If they get poor or low marks, they have done it badly.","ex":{"en":"You have to give her top marks for moral guts","cn":"你不得不对她维护正义的勇气竖起大拇指。"}},{"pos":"VERB 动词","cn":"给(作业)评分(或打分)","en":"When a teacher marks a student's work, the teacher decides how good it is and writes a number or letter on it to indicate this opinion.","ex":{"en":"He was marking essays in his small study.","cn":"他正在他那间小书房里批阅文章。"}},{"pos":"N-COUNT 可数名词","cn":"(重要的)标准，指标","en":"A particular mark is a particular number, point, or stage which has been reached or might be reached, especially a significant one.","ex":{"en":"Unemployment is rapidly approaching the one million mark.","cn":"失业人数正迅速逼近百万大关。"}},{"pos":"N-COUNT 可数名词","cn":"特征;特色","en":"The mark of something is the characteristic feature that enables you to recognize it.","ex":{"en":"The mark of a civilized society is that it looks after its weakest members.","cn":"文明社会的特征是照顾最弱势群体。"}},{"pos":"N-SING 单数名词","cn":"（品质、情感、情景的）标志，表现，迹象","en":"If you say that a type of behaviour or an event is a mark of a particular quality, feeling, or situation, you mean it shows that that quality, feeling, or situation exists.","ex":{"en":"It was a mark of his unfamiliarity with Hollywood that he didn't understand that an agent was paid out of his client's share","cn":"他居然不知道经纪人的报酬得从其客户的收入中出，这说明他对好莱坞太不了解了。"}},{"pos":"VERB 动词","cn":"标明(方位);标示","en":"If something marks a place or position, it shows where something else is or where it used to be.","ex":{"en":"A huge crater marks the spot where the explosion happened.","cn":"巨大的弹坑标明了爆炸发生的地点。"}},{"pos":"VERB 动词","cn":"标志;意味着;是…的征兆","en":"An event that marks a particular stage or point is a sign that something different is about to happen.","ex":{"en":"The announcement marks the end of an extraordinary period in European history","cn":"声明标志着欧洲历史上一个伟大时代的终结。"}},{"pos":"VERB 动词","cn":"纪念;庆祝","en":"If you do something to mark an event or occasion, you do it to show that you are aware of the importance of the event or occasion.","ex":{"en":"The four new stamps mark the 100th anniversary of the British Astronomical Association","cn":"这四枚新邮票是为了纪念英国天文协会成立100周年而发行的。"}},{"pos":"VERB 动词","cn":"是…的特色;是…的典型特征","en":"If a particular quality or feature marks something, it is a quality or feature which that thing typically has.","ex":{"en":"Tragedy has marked Wilmette's life","cn":"悲剧笼罩着薇尔梅特的一生。"}},{"pos":"VERB 动词","cn":"将…归为;把…列为;给…确定性质","en":"Something that marks someone as a particular type of person indicates that they are that type of person.","ex":{"en":"Her opposition to abortion and feminism mark her as a convinced traditionalist.","cn":"她对堕胎和女权主义的反对态度表明她是个不折不扣的传统主义者。"}},{"pos":"VERB 动词","cn":"(团队比赛中)盯住(对方球员)","en":"In a team game, when a defender is marking an attacker, they are trying to stay close to the attacker and prevent them from getting the ball.","ex":{"en":"...Manchester United defender Rio Ferdinand, who so effectively marked Michael Owen.","cn":"成功盯住了迈克尔·欧文的曼联后卫里奥·费迪南德"}},{"pos":"N-COUNT 可数名词","cn":"马克(德国使用欧元之前的货币单位)","en":"The mark was the unit of money used in Germany before it was replaced by the euro.","ex":{"en":"The government gave 30 million marks for new school books.","cn":"政府拨款3000万马克用于购置学校的新教材。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(煤气炉上表示温度的)刻度，挡","en":"Mark is used before a number to indicate a particular temperature level in a gas oven.","ex":{"en":"Set the oven at gas mark 4.","cn":"将煤气炉开至4挡。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(汽车、机器、设备等的)型，式","en":"Mark is used before a number to indicate a particular version or model of a vehicle, machine, or device.","ex":{"en":"...his Mark II Ford Cortina.","cn":"他的福特葛天娜二代车"}},{"pos":"PHRASE 短语","cn":"留下深刻的印记;留下深远的影响","en":"If someone or something leaves their mark or leaves a mark, they have a lasting effect on another person or thing.","ex":{"en":"Years of conditioning had left their mark on her, and she never felt inclined to talk to strange men.","cn":"多年的熏陶对她影响很深，她从不愿意跟陌生人说话。"}},{"pos":"PHRASE 短语","cn":"成就不凡;获得名望;成名","en":"If you make your mark or make a mark, you become noticed or famous by doing something impressive or unusual.","ex":{"en":"She made her mark in the film industry in the 1960s.","cn":"她在20世纪60年代的电影界占有一席之地。"}},{"pos":"PHRASE 短语","cn":"（理解力或反应）敏捷的/迟钝的，灵敏的/缓慢的","en":"If you are quick off the mark, you are quick to understand or respond to something. If you are slow off the mark, you are slow to understand or respond to something."},{"pos":"CONVENTION 惯用语","cn":"各就各位","en":"On your marks in British English, or on your mark in American English, is a command given to runners at the beginning of a race in order to get them into the correct position to start.","ex":{"en":"On your marks—get set—go!","cn":"各就各位！预备！跑！"}},{"pos":"PHRASE 短语","cn":"不正确;不得要领;不够贴切/完全正确;切中要害;十分贴切","en":"If something is off the mark, it is inaccurate or incorrect. If it is on the mark, it is accurate or correct.","ex":{"en":"Robinson didn't think the story was so far off the mark","cn":"鲁宾逊认为这个报道根本算不上离谱。"}},{"pos":"PHRASE 短语","cn":"达到标准;符合要求","en":"If something is up to the mark, it is good enough.","ex":{"en":"The workers get rid of those whose work is not up to the mark.","cn":"工人们赶走了工作不符合要求的人。"}},{"pos":"PHRASE 短语","cn":"离谱;大错特错","en":"If something such as a claim or estimate is wide of the mark, it is incorrect or inaccurate.","ex":{"en":"That comparison isn't as wide of the mark as it seems.","cn":"那种比较并非像看起来那么离谱。"}},{"pos":"PHRASE 短语","cn":"你听着(表示强调)","en":"You can say mark you to emphasize and draw attention to something you have just said.","ex":{"en":"We're not extremists, mark you.","cn":"你听好了，我们不是极端分子。"}},{"pos":"","cn":"","en":"to overstep the mark→see: ; mark my words→see: ;"},{"pos":"","cn":"","en":"相关词组：mark down mark off mark out mark up"}]},"examples":[{"en":"I'm just marking time in this job — I'm hoping to get into journalism.","cn":"我干这件工作只是在等待时机，我希望能从事新闻工作。"},{"en":"I put a mark in the margin to remind me to check the figure.","cn":"我在页边做了个记号来提醒自己核对一下这个数字。"}]},"majestic":{"media":{"uk":"media/uk/majestic__gb_1.mp3","us":"media/us/majestic__us_1.mp3"},"oxford":{"phon":"məˈdʒestɪk","pos":"adjective","senses":[{"en":"impressive because of size or beauty","cn":"雄伟的；威严的；壮观的","ex":{"en":"a majestic castle/river/view","cn":"雄伟的城堡；壮丽的河流／景色"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"壮丽的;庄严的;雄伟的","en":"If you describe something or someone as majestic, you think they are very beautiful, dignified, and impressive.","ex":{"en":"...a majestic country home that once belonged to the Astor family","cn":"一座曾经属于阿斯特家族的气派不凡的乡间住宅"}}]},"examples":[{"en":"a majestic castle/river/view","cn":"雄伟的城堡；壮丽的河流/景色"},{"en":"This lovely village is surrounded by majestic mountain scenery.","cn":"这座美丽的村庄四周山色壮丽。"}]},"manpower":{"media":{"uk":"media/uk/manpower__gb_1.mp3","us":"media/us/manpower__us_1.mp3"},"oxford":{"phon":"ˈmænpaʊə(r)","pos":"noun","senses":[{"en":"the number of workers needed or available to do a particular job","cn":"劳动力；人手；人力","ex":{"en":"a need for trained/skilled manpower","cn":"对受过培训的／熟练的劳动力的需求"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"人力;劳动力","en":"Workers are sometimes referred to as manpower when they are being considered as a part of the process of producing goods or providing services.","ex":{"en":"...the shortage of skilled manpower in the industry","cn":"该行业熟练劳动力的短缺"}}]},"examples":[{"en":"a need for trained/skilled manpower","cn":"对受过培训的/熟练的劳动力的需求"},{"en":"a manpower shortage","cn":"劳动力短缺"}]},"magazine":{"media":{"uk":"media/uk/magazine__gb_1.mp3","us":"media/us/magazine__us_1.mp3"},"oxford":{"phon":"ˌmæɡəˈziːn","pos":"noun","senses":[{"en":"a type of large thin book with a paper cover that you can buy every week or month, containing articles, photographs, etc., often on a particular topic; a similar collection of articles, etc. that appears regularly online","cn":"杂志；期刊；网络期刊","lab":"informal","ex":{"en":"a weekly/monthly magazine","cn":"周刊；月刊"}},{"en":"a radio or television programme that is about a particular topic","cn":"（电视、广播）专题节目","ex":{"en":"a regional news magazine on TV","cn":"以地区新闻为主题的电视节目"}},{"en":"the part of a gun that holds the bullets before they are fired","cn":"弹仓；弹盒；弹盘","ex":{"en":"He took the machine gun and a spare magazine.","cn":"他拿走了机枪和备用弹匣。"}},{"en":"a room or building where weapons, explosives and bullets are stored","cn":"弹药库；军火库；军械库","ex":{"en":"Those buildings are ammunition magazines.","cn":"那些建筑物是弹药库。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"杂志","en":"A magazine is a publication with a paper cover which is issued regularly, usually every week or every month, and which contains articles, stories, photographs, and advertisements.","ex":{"en":"Her face is on the cover of a dozen or more magazines.","cn":"她的面孔出现在十几种杂志的封面上。"}},{"pos":"N-COUNT 可数名词","cn":"(广播、电视上融合多种话题的)杂志型节目，板块节目","en":"On radio or television, a magazine or a magazine programme is a programme consisting of several items about different topics, people, and events.","ex":{"en":"...a live arts magazine.","cn":"直播的艺术板块节目"}},{"pos":"N-COUNT 可数名词","cn":"(枪的)子弹夹，弹匣，弹仓","en":"In an automatic gun, the magazine is the part that contains the bullets."},{"pos":"N-COUNT 可数名词","cn":"军火库；弹药库","en":"A magazine is a building in which things such as guns, bullets, and explosives are kept."}]},"examples":[{"en":"Her designer clothes were from the pages of a glossy fashion magazine.","cn":"她的名师设计的服装取材于一份精美的时装杂志。"},{"en":"a regional news magazine on TV","cn":"以地区新闻为主题的电视节目"}]},"material":{"media":{"uk":"media/uk/material__gb_1.mp3","us":"media/us/material__us_1.mp3"},"oxford":{"phon":"məˈtɪəriəl","pos":"noun","senses":[{"en":"a substance that things can be made from","cn":"材料；原料","g":"[countable, uncountable]","ex":{"en":"building materials (= bricks, sand, glass, etc.)","cn":"建筑材料"}},{"en":"things that are needed in order to do a particular activity","cn":"（某一活动所需的）材料","g":"[countable, usually plural, uncountable]","ex":{"en":"teaching materials","cn":"教材"}},{"en":"information or ideas used in books, etc.","cn":"素材；用以创作的材料（或构想）","g":"[uncountable]","ex":{"en":"She's collecting material for her latest novel.","cn":"她在为其最新的小说收集素材。"}},{"en":"cloth used for making clothes, curtains, etc.","cn":"布料","g":"[uncountable, countable]","ex":{"en":"You'll need a piece of material about 20 cm square.","cn":"你将需要一块20厘米见方的布料。"}},{"en":"items used in a performance","cn":"节目；曲目；剧目","g":"[uncountable]","ex":{"en":"The band played all new material at the gig.","cn":"在现场音乐会上，乐队演奏的都是新曲目。"}},{"en":"a person with particular qualities or suitable for a particular opportunity","cn":"合适的人；材料","ex":{"en":"The teacher saw her as good university material (= good enough to go to university).","cn":"老师认为她是块上大学的料。"}},{"en":"connected with money, possessions, etc. rather than with the needs of the mind or spirit","cn":"物质的，实际的（非精神需求的）","g":"[only before noun]","ex":{"en":"material possessions/wealth","cn":"物质财产／财富"},"pos":"adjective"},{"en":"connected with the physical world rather than with the mind or spirit","cn":"物质的；客观存在的","g":"[only before noun]","ex":{"en":"the material world","cn":"物质世界"},"pos":"adjective"},{"en":"important and needing to be considered","cn":"重要的；必要的","lab":"formal or law","ex":{"en":"material evidence/facts","cn":"实质性的证据；重要事实"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"物质;材料","en":"A material is a solid substance.","ex":{"en":"...electrons in a conducting material such as a metal.","cn":"金属等导电材料中的电子"}},{"pos":"N-MASS 物质名词","cn":"布料;衣料;织物","en":"Material is cloth.","ex":{"en":"...the thick material of her skirt","cn":"她的裙子的厚布料"}},{"pos":"N-PLURAL 复数名词","cn":"原料;材料","en":"Materials are the things that you need for a particular activity.","ex":{"en":"The builders ran out of materials.","cn":"建筑商耗尽了材料。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(书、戏剧或电影的)素材，资料","en":"Ideas or information that are used as a basis for a book, play, or film can be referred to as material .","ex":{"en":"In my version of the story, I added some new material.","cn":"我在讲述这个故事时加入了新的素材。"}},{"pos":"ADJ 形容词","cn":"（指与抽象相对）物质的，有形的，实体的","en":"Material things are related to possessions or money, rather than to more abstract things such as ideas or values.","ex":{"en":"Every room must have been stuffed with material things.","cn":"每个房间肯定都塞满了东西。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"人才;(做…的)料","en":"If you say that someone is a particular kind of material, you mean that they have the qualities or abilities to do a particular job or task.","ex":{"en":"She was not university material","cn":"她不是上大学的料。"}},{"pos":"ADJ 形容词","cn":"(证据或信息)直接相关的，实质性的，重要的","en":"Material evidence or information is directly relevant and important in a legal or academic argument.","ex":{"en":"The nature and availability of material evidence was not to be discussed","cn":"实质性证据的性质和可用性毋庸讨论。"}}]},"examples":[{"en":"Their comments have not materially affected our plans (= in a noticeable or important way).","cn":"他们的评价并没有对我们的计划产生多么重要的影响。"},{"en":"‘What material is this dress made of?’ ‘Cotton.’ “","cn":"这件连衣裙是用什么料子做的？” “棉布。”"}]},"manual":{"media":{"uk":"media/uk/manual__gb_1.mp3","us":"media/us/manual__us_1.mp3"},"oxford":{"phon":"ˈmænjuəl","pos":"adjective","senses":[{"en":"involving using the hands or physical strength","cn":"用手的；手工的；体力的","ex":{"en":"manual labour/jobs/skills","cn":"体力劳动／活儿；手工技巧"}},{"en":"operated or controlled by hand rather than by machine or using electricity, etc.","cn":"手动的；手控的；用手操作的","ex":{"en":"a manual gearbox","cn":"手动变速箱"}},{"en":"connected with using the hands","cn":"手工的；用手的","ex":{"en":"manual dexterity","cn":"手的灵巧"}},{"en":"a book that tells you how to do or operate something, especially one that comes with a machine, etc. when you buy it","cn":"使用手册；说明书；指南","ex":{"en":"a(n) computer/car/instruction manual","cn":"电脑／汽车说明书；用法指南"},"pos":"noun"},{"en":"a vehicle with a system of gears operated by the driver using a gear lever","cn":"手动挡汽车","lab":"British English","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"人力的;体力的；手工的","en":"Manual work is work in which you use your hands or your physical strength rather than your mind.","ex":{"en":"...skilled manual workers","cn":"熟练的体力劳动者"}},{"pos":"ADJ 形容词","cn":"用手的;手工的","en":"Manual is used to talk about movements which are made by someone's hands.","ex":{"en":"...toys designed to help develop manual dexterity.","cn":"用来培养手的灵活性的玩具"}},{"pos":"ADJ 形容词","cn":"手动的;用手操作的","en":"Manual means operated by hand, rather than by electricity or a motor.","ex":{"en":"There is a manual pump to get rid of the water.","cn":"有一只手摇水泵用来排水。"}},{"pos":"N-COUNT 可数名词","cn":"使用手册;说明书","en":"A manual is a book which tells you how to do something or how a piece of machinery works.","ex":{"en":"...the instruction manual.","cn":"使用说明书"}}]},"examples":[{"en":"My camera has manual and automatic functions.","cn":"我的照相机有手调和自动两种功能。"},{"en":"Leave the controls on manual.","cn":"让操纵杆处于手动状态。"}]},"marker":{"oxford":{"phon":"ˈmɑːkə(r)","pos":"noun","senses":[{"en":"an object or a sign that shows the position of something","cn":"（表示方位的）标记，记号","g":"[countable]","ex":{"en":"a boundary marker","cn":"界标"}},{"en":"a sign that something exists or that shows what it is like","cn":"标志；标识；表示","g":"[singular]","ex":{"en":"Price is not always an accurate marker of quality.","cn":"价格并不总是质量的准确标志。"}},{"en":"a pen with a thick felt tip","cn":"记号笔；毡头笔","lab":"British English also"},{"en":"a person who marks students’ work or exam papers","cn":"阅卷人；判作业的人","lab":"British English"},{"en":"a player who stays close to a player on the other team in order to stop them getting the ball","cn":"紧逼防守的队员；盯人的防守队员","lab":"British English"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(表示方位的)标记，路标，记号;（起提示作用的）标示物","en":"A marker is an object which is used to show the position of something, or is used to help someone remember something.","ex":{"en":"He put a marker in his book and followed her out.","cn":"他在书里夹了一个书签后便随她出去了。"}},{"pos":"N-COUNT 可数名词","cn":"（品质或特点的）标志，代表","en":"If you refer to something as a marker for a particular quality or feature, you mean that it demonstrates the existence or presence of that quality or feature.","ex":{"en":"Vitamin C is a good marker for the presence of other vitamins and nutrients in frozen food.","cn":"维生素C的存在是冷冻食品里存在其他维生素和营养成分的很好说明。"}},{"pos":"N-COUNT 可数名词","cn":"记号笔，毡笔(笔头较粗，由毡毛制成，用于绘画和着色)","en":"A marker or a marker pen is a pen with a thick tip made of felt, which is used for drawing and for colouring things.","ex":{"en":"Draw your child's outline with a heavy black marker.","cn":"用浓黑色的毡笔画出你孩子的轮廓。"}}]},"media":{"img":["media/pic/stationery_supplies_comp.jpg","media/thumb/marker.jpg"],"uk":"media/uk/marker__gb_1.mp3","us":"media/us/marker__us_1.mp3"},"examples":[{"en":"He placed a marker where the ball had landed.","cn":"他在球落地的地方放了个标记。"},{"en":"Price is not always an accurate marker of quality.","cn":"价格并不总是质量的准确标志。"}]},"ma":{"media":{"uk":"media/uk/ma__gb_1.mp3","us":"media/us/ma__us_1.mp3"},"oxford":{"phon":"mɑː","pos":"noun","senses":[{"en":"mother","cn":"妈；妈妈","ex":{"en":"I'm going now, Ma.","cn":"妈，我走啦。"}},{"en":"a second university degree in an arts subject, or, in Scotland, a first university degree in an arts subject (the abbreviation for ‘Master of Arts’)","cn":"文学硕士（大学文科的二级学位），（苏格兰）文学学士（全写为 Master of Arts）","lab":"British English","ex":{"en":"to be/have/do an MA","cn":"是文学硕士；有／攻读文学硕士学位"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"文科硕士学位","en":"An MA is a master's degree in an arts or social science subject. MA is an abbreviation for (缩略 =) 'Master of Arts'.","ex":{"en":"She then went on to university where she got a BA and then an MA.","cn":"她后来上了大学，先后获得了文科学士与硕士学位。"}},{"pos":"","cn":"(用于人名之后)文科硕士，获得文科硕士学位的人","en":"MA is written after someone's name to indicate that they have an MA.","ex":{"en":"...Clive W Heaton, MA.","cn":"文科硕士克莱夫·W.希顿"}}]},"examples":[{"en":"( BrE ) Julie Bell MA","cn":"文科硕士朱莉 · 贝尔"},{"en":"to be/have/do an MA","cn":"成为文科硕士；有/攻读文科硕士学位"}]},"managed":{"media":{"uk":"media/uk/managed__gb_1.mp3","us":"media/us/managed__us_1.mp3"},"oxford":{"phon":"ˈmænɪdʒd","pos":"adjective","senses":[{"en":"done or arranged with care and control","cn":"妥善安排的；受监管的","ex":{"en":"The money will be invested in managed funds.","cn":"这笔钱将投资于管理基金。"}}]},"examples":[{"en":"Only wood from managed forests is used in our furniture.","cn":"我们的家具完全是用监管林中的木材做的。"},{"en":"The money will be invested in managed funds.","cn":"这笔钱将投资于管理基金。"}]},"margin":{"oxford":{"phon":"ˈmɑːdʒɪn","pos":"noun","senses":[{"en":"the empty space at the side of a written or printed page","cn":"页边空白；白边","ex":{"en":"the left-hand/right-hand margin","cn":"左／右页边"}},{"en":"the amount of time, or number of votes, etc. by which somebody wins something","cn":"（获胜者在时间或票数上领先的）幅度，差额，差数","g":"[usually singular]","ex":{"en":"He won by a narrow margin.","cn":"他以微小的差额获胜。"}},{"en":"the difference between the cost of buying or producing something and the price that it is sold for","cn":"利润率","lab":"business","ex":{"en":"What are your average operating margins?","cn":"你的平均营业利润率是多少？"}},{"en":"an extra amount of something such as time, space, money, etc. that you include in order to make sure that something is successful","cn":"余地；备用的时间（或空间、金钱等）","g":"[usually singular]","ex":{"en":"a safety margin","cn":"安全距离"}},{"en":"the extreme edge or limit of a place","cn":"边缘；极限；界限","lab":"formal","ex":{"en":"the eastern margin of the Indian Ocean","cn":"印度洋的东岸"}},{"en":"the part that is not included in the main part of a group or situation","cn":"边缘部分；非主体部分","g":"[usually plural]","ex":{"en":"people living on the margins of society","cn":"生活在社会边缘的人"}},{"en":"an amount that is added to a basic wage, paid for special skill or responsibility","cn":"（基本工资以外的）技术津贴，职务补贴","lab":"Australian English, New Zealand English，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指选票或比分的)差额，差数","en":"A margin is the difference between two amounts, especially the difference in the number of votes or points between the winner and the loser in an election or other contest.","ex":{"en":"They could end up with a 50-point winning margin","cn":"他们最终可能会以50分的优势获胜。"}},{"pos":"N-COUNT 可数名词","cn":"页边空白;页边;白边","en":"The margin of a written or printed page is the empty space at the side of the page.","ex":{"en":"She added her comments in the margin.","cn":"她在页边的空白处写下了评语。"}},{"pos":"N-VAR 可变名词","cn":"余地;富余","en":"If there is a margin for something in a situation, there is some freedom to choose what to do or decide how to do it.","ex":{"en":"The money is collected in a straightforward way with little margin for error","cn":"钱是直接筹集上来的，不太容易出错。"}},{"pos":"N-COUNT 可数名词","cn":"边缘;边沿","en":"The margin of a place or area is the extreme edge of it.","ex":{"en":"...the low coastal plain along the western margin","cn":"沿着西部边缘的地势低平的沿海平原"}},{"pos":"N-PLURAL 复数名词","cn":"（社会、群体或活动中的）边缘地位，非主体地位","en":"To be on the margins of a society, group, or activity means to be among the least typical or least important parts of it.","ex":{"en":"Students have played an important role in the past, but for the moment, they're on the margins.","cn":"学生过去曾经发挥了重要的作用，不过现在他们变得无足轻重了。"}}]},"media":{"uk":"media/uk/margin__gb_1.mp3","us":"media/us/margin__us_1.mp3"},"examples":[{"en":"The narrow gateway left me little margin for error as I reversed the car.","cn":"门口狭窄，弄得我倒车时几乎不能出任何差错。"},{"en":"She beat the other runners by a margin of ten seconds.","cn":"她以领先十秒的优势战胜了其他赛跑者。"}]},"massive":{"media":{"uk":"media/uk/massive__gb_1.mp3","us":"media/us/massive__us_1.mp3"},"oxford":{"phon":"ˈmæsɪv","pos":"adjective","senses":[{"en":"very large, heavy and solid","cn":"巨大的；大而重的；结实的","ex":{"en":"a massive rock","cn":"一块巨大的岩石"}},{"en":"extremely large or serious","cn":"巨大的；非常严重的","lab":"British English, informal，，","ex":{"en":"The government put massive amounts of money into the health service.","cn":"政府投入大量资金用于医疗服务。"}},{"en":"very successful or important","cn":"非常成功的；强大的","lab":"informal","ex":{"en":"This band is going to be massive.","cn":"这支乐队将会大红大紫。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"巨大的;庞大的;厚重的;强大的","en":"Something that is massive is very large in size, quantity, or extent.","ex":{"en":"There was evidence of massive fraud.","cn":"有证据表明是巨额欺诈。"}},{"pos":"ADJ 形容词","cn":"(疾病)非常严重的，十分危急的","en":"If you describe a medical condition as massive, you mean that it is extremely serious.","ex":{"en":"He died six weeks later of a massive heart attack.","cn":"六周后他因严重的心脏病发作去世。"}}]},"examples":[{"en":"The explosion made a massive hole in the ground.","cn":"爆炸在地面留下了一个巨大的坑。"},{"en":"They have a massive great house.","cn":"他们有一座非常大的房子。"}]},"mattress":{"media":{"uk":"media/uk/mattress__gb_1.mp3","us":"media/us/mattress__us_1.mp3"},"oxford":{"phon":"ˈmætrəs","pos":"noun","senses":[{"en":"the soft part of a bed, that you lie on","cn":"床垫","ex":{"en":"a soft/hard mattress","cn":"软／硬床垫"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"褥垫;床垫","en":"A mattress is the large, flat object which is put on a bed to make it comfortable to sleep on."}]},"examples":[{"en":"a soft/hard mattress","cn":"软/硬床垫"}]},"mature":{"oxford":{"phon":"məˈtʃʊə(r)","pos":"adjective","senses":[{"en":"behaving in a sensible way, like an adult","cn":"明白事理的；成熟的；像成人似的","sc":"sensible","ex":{"en":"Jane is very mature for her age.","cn":"简年龄不大，却很成熟。"}},{"en":"fully grown and developed","cn":"成熟的；发育完全的","sc":"fully grown","ex":{"en":"sexually mature","cn":"性成熟的"}},{"en":"developed over a period of time to produce a strong, rich taste","cn":"发酵成熟的；酿成的","sc":"wine/cheese"},{"en":"used as a polite or humorous way of saying that somebody is no longer young","cn":"（礼貌或幽默的说法）成年的，不再年轻的","sc":"no longer young","ex":{"en":"clothes for the mature woman","cn":"成年妇女的服装"}},{"en":"created late in an artist’s life and showing great understanding and skill","cn":"成熟的；技艺精湛的；创作于晚年的","sc":"work of art"},{"en":"ready to be paid","cn":"到期（应该支付）的","lab":"business","sc":"insurance policy"},{"en":"to become fully grown or developed","cn":"成熟；长成","g":"[intransitive]","sc":"become fully grown","ex":{"en":"This particular breed of cattle matures early.","cn":"这一品种的牛发育成熟快。"},"pos":"verb"},{"en":"to develop emotionally and start to behave like a sensible adult","cn":"（情感和认识）成熟；有判断力","g":"[intransitive]","sc":"become sensible","ex":{"en":"He has matured a great deal over the past year.","cn":"经过过去这一年，他成熟了许多。"},"pos":"verb"},{"en":"to fully develop a particular skill or quality","cn":"使（技能或素质）成熟；充分发展","g":"[intransitive]","sc":"develop skill","ex":{"en":"She has matured into one of the country's finest actresses.","cn":"她已经成长为这个国家一位最优秀的演员。"},"pos":"verb"},{"en":"if wine, cheese, etc. matures or is matured, it develops over a period of time to produce a strong, rich taste","cn":"酿成；制成；发酵成熟","g":"[intransitive, transitive]","sc":"wine/cheese","ex":{"en":"The cheese is smoked and then left to mature.","cn":"奶酪先经熏制，然后放置待其酿熟。"},"pos":"verb"},{"en":"to reach the date when it must be paid","cn":"到期（应付款）","g":"[intransitive]","lab":"business","sc":"insurance policy","ex":{"en":"She has a number of investments that mature at the end of the year.","cn":"她有多项投资将于年底到期。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"长大(成人);发育成熟","en":"When a child or young animal matures, it becomes an adult.","ex":{"en":"You will learn what to expect as your child matures physically","cn":"在孩子身体发育成熟时，你就知道会发生什么事了。"}},{"pos":"VERB 动词","cn":"成熟；完善","en":"When something matures, it reaches a state of complete development.","ex":{"en":"When the trees matured they were cut in certain areas","cn":"在有些地方，树木长成后就会被砍掉。"}},{"pos":"VERB 动词","cn":"(在性格、感情等方面)趋于成熟","en":"If someone matures, they become more fully developed in their personality and emotional behaviour.","ex":{"en":"Hopefully after three years at university I will have matured","cn":"希望3年大学生活之后我能变成熟。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(性格、感情等方面)成熟的;明白事理的","en":"If you describe someone as mature, you think that they are fully developed and balanced in their personality and emotional behaviour.","ex":{"en":"They are emotionally mature and should behave responsibly","cn":"他们在情感上已经成熟，应该负责任地行事。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(画家、作家、音乐家等的技艺、能力等)成熟的，炉火纯青的","en":"If you describe the work of an artist, writer, or musician as mature, you mean that it is thoughtful and skilful and shows that their abilities have fully developed.","ex":{"en":"It is his most mature comedy yet.","cn":"这是他迄今最成熟的喜剧作品。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(葡萄酒、干酪等)发酵成熟;酿成","en":"If something such as wine or cheese matures or is matured, it is left for a time to allow its full flavour or strength to develop.","ex":{"en":"Unlike wine, brandy matures only in wood, not glass.","cn":"和葡萄酒不同的是，白兰地只能在木制容器而非玻璃容器里酿制。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(干酪、葡萄酒等)发酵成熟的，酿熟的","en":"Mature cheese or wine has been left for a time to allow its full flavour or strength to develop.","ex":{"en":"Grate some mature cheddar cheese.","cn":"将一些已经酿熟的切达干酪磨碎。"}},{"pos":"VERB 动词","cn":"(存单、养老金计划等)到期","en":"When an investment such as a savings policy or pension plan matures, it reaches the stage when you stop paying money and the company pays you back the money you have saved, and the interest your money has earned.","ex":{"en":"These bonuses will be paid when your savings plan matures in ten years' time.","cn":"这些红利会在10年后存款到期时支付。"}},{"pos":"ADJ 形容词","cn":"成熟的;不再年轻的;老成的(婉词)","en":"If you say that someone is mature or of mature years, you are saying politely that they are middle-aged or old.","ex":{"en":"...a man of mature years who had been in the job for longer than most of the members could remember.","cn":"一个已过中年的男子，大多数成员都不记得他干这行有多久了"}}]},"media":{"uk":"media/uk/mature__gb_1.mp3","us":"media/us/mature__us_1.mp3"},"examples":[{"en":"Technology in this field has matured considerably over the last decade.","cn":"这一领域的技术经过过去十年的发展已经相当完善。"},{"en":"She has matured into one of the country's finest actresses.","cn":"她已经成长为这个国家一位最优秀的演员。"}]},"maximum":{"media":{"uk":"media/uk/maximum__gb_1.mp3","us":"media/us/maximum__us_1.mp3"},"oxford":{"phon":"ˈmæksɪməm","pos":"adverb","senses":[{"en":"used after amounts to show that the amount is the highest possible","cn":"用在金额之后，表示金额可能是最高的","ex":{"en":"The table has a length of four feet maximum.","cn":"这种桌子最长可达四英尺。"}},{"en":"as large, fast, etc. as is possible, or the most that is possible or allowed","cn":"最高的；最多的；最大极限的","ex":{"en":"the maximum amount/number of something","cn":"最大数量／数目"},"pos":"adjective"},{"en":"the greatest amount, size, speed, etc. that is possible, recorded or allowed","cn":"最大量；最大限度；最高限度","ex":{"en":"a maximum of 30 children in a class","cn":"每班至多 30 名学生"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"最高的;最大的;最多的","en":"You use maximum to describe an amount which is the largest that is possible, allowed, or required.","ex":{"en":"Under planning law the maximum height for a fence or hedge is 2 metres","cn":"规划法中规定，围栏或树篱最高为2米。"}},{"pos":"ADJ 形容词","cn":"(数量)极大的,极多的","en":"You use maximum to indicate how great an amount is.","ex":{"en":"...the maximum amount of information","cn":"海量信息"}},{"pos":"ADV 副词","cn":"最多;顶多;充其量","en":"If you say that something is a particular amount maximum, you mean that this is the greatest amount it should be or could possibly be, although a smaller amount is acceptable or very possible.","ex":{"en":"We need an extra 6g a day maximum.","cn":"我们一天最多还需要6克。"}},{"pos":"PHRASE 短语","cn":"最大限度地;尽可能充分地;竭尽全力地","en":"If you say that someone does something to the maximum, you are emphasizing that they do it to the greatest degree possible.","ex":{"en":"You have to develop your capabilities to the maximum.","cn":"你必须尽你所能。"}}]},"examples":[{"en":"The job will require you to use all your skills to the maximum.","cn":"这项工作将要求你最大限度地发挥你的技能。"},{"en":"The July maximum (= the highest temperature recorded in July) was 30°C.","cn":"七月的最高气温是 30 摄氏度。"}]},"many":{"media":{"uk":"media/uk/many__gb_1.mp3","us":"media/us/many__us_1.mp3"},"oxford":{"phon":"ˈmeni","pos":"determiner, pronoun","senses":[{"en":"used with plural nouns and verbs, especially in negative sentences or in more formal English, to mean ‘a large number of’. Also used in questions to ask about the size of a number, and with ‘as’, ‘so’ and ‘too’.","cn":"许多（与复数名词及动词连用，尤用于否定句或正式用语，表示大量；也用于疑问句以询问数字大小，并可与 as、so 和 too 连用）","lab":"British English","ex":{"en":"We don't have very many copies left.","cn":"我们所剩的册数不多。"}},{"en":"used with a plural verb to mean ‘most people’","cn":"（与复数动词连用）大多数人","ex":{"en":"a government which improves conditions for the many","cn":"为大多数人改善生活条件的政府"}},{"en":"used with a singular noun and verb to mean ‘a large number of’","cn":"（与单数名词及动词连用）许多，大量","lab":"formal","ex":{"en":"Many a good man has been destroyed by drink.","cn":"许多好人都毁在了饮酒上。"}}]},"collins":{"senses":[{"pos":"DET 限定词","cn":"许多的;大量的","en":"You use many to indicate that you are talking about a large number of people or things.","ex":{"en":"I don't think many people would argue with that","cn":"我认为多数人不会对此有异议。"}},{"pos":"ADV-GRADED 副词","cn":"(回答有关数量的提问时)多","en":"You use many in expressions such as 'not many', 'not very many', and 'too many' when replying to questions about numbers of things or people.","ex":{"en":"'How many of the songs that dealt with this theme became hit songs?' — 'Not very many.'","cn":"“有多少关于这个主题的歌曲风靡一时呢？”“并不很多。”"}},{"pos":"PREDET 前置限定词","cn":"(用于 a + 单数名词之前表示强调)许多，很多","en":"You use many followed by 'a' and a noun to emphasize that there are a lot of people or things involved in something.","ex":{"en":"Many a mother tries to act out her unrealized dreams through her daughter","cn":"有许多母亲都试图在女儿身上实现自己未竟的梦想。"}},{"pos":"DET 限定词","cn":"(用于 how 之后)多少","en":"You use many after 'how' to ask questions about numbers or quantities. You use many after 'how' in reported clauses to talk about numbers or quantities.","ex":{"en":"How many years have you been here?","cn":"你在这里有多少年了？"}},{"pos":"DET 限定词","cn":"(用于比较物或人的数量，与 as 连用)","en":"You use many with 'as' when you are comparing numbers of things or people.","ex":{"en":"I've always entered as many photo competitions as I can","cn":"我总是尽可能多地参加摄影比赛。"}},{"pos":"PRON 代词","cn":"许多人","en":"You use many to mean 'many people'.","ex":{"en":"Not many expected Ferdinand to be such a success this season","cn":"预料到费迪南德在本赛季如此成功的人并不多。"}},{"pos":"N-SING 单数名词","cn":"多数人;（尤指）民众，百姓","en":"The many means a large group of people, especially the ordinary people in society, considered as separate from a particular small group.","ex":{"en":"The printing press gave power to a few to change the world for the many","cn":"印刷机赋予少数人为多数人改变世界的力量。"}},{"pos":"PHRASE 短语","cn":"(用于数字之前表示数目极大)多达…","en":"You use as many as before a number to suggest that it is surprisingly large.","ex":{"en":"As many as four and a half million people watched today's parade.","cn":"观看今天游行的人多达450万。"}},{"pos":"PHRASE 短语","cn":"许多；大量；众多","en":"You use a good many or a great many to emphasize that you are referring to a large number of things or people.","ex":{"en":"We've both had a good many beers","cn":"我俩都喝了很多啤酒。"}},{"pos":"","cn":"","en":"many happy returns→see: ; in so many words→see: ;"}]},"examples":[{"en":"I stayed in England for many/quite a few/ten weeks.","cn":"我在英格兰逗留了许多周/好几周/十周。"},{"en":"New drivers have twice as many accidents as experienced drivers.","cn":"新手司机所出的事故是熟练司机的两倍。"}]},"map":{"media":{"uk":"media/uk/map__gb_1.mp3","us":"media/us/map__us_1.mp3"},"oxford":{"phon":"mæp","pos":"noun","senses":[{"en":"a drawing or plan of the earth’s surface or part of it, showing countries, towns, rivers, etc.","cn":"地图","ex":{"en":"a map of France","cn":"法国地图"}},{"en":"a diagram to show the positions of things over an area","cn":"（区域中物体的）分布图","ex":{"en":"an electron density map","cn":"电子密度图"}},{"en":"a diagram to show the position of genes on a chromosome","cn":"图：显示染色体上基因位置的图","ex":{"en":"a physical and genetic map of the entire human genome","cn":"整个人类基因组的物理和遗传图谱"}},{"en":"to make a map of an area","cn":"绘制…的地图","ex":{"en":"an unexplored region that has not yet been mapped","cn":"一个尚未绘制地图的未经勘察的地区"},"pos":"verb"},{"en":"to discover or give information about something, especially the way it is arranged or organized","cn":"了解信息，提供信息（尤指其编排或组织方式）","ex":{"en":"It is now possible to map the different functions of the brain.","cn":"现在已有可能了解大脑的各种功能。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"地图","en":"A map is a drawing of a particular area such as a city, a country, or a continent, showing its main features as they would appear if you looked at them from above.","ex":{"en":"He unfolded the map and set it on the floor","cn":"他打开地图，放在了地板上。"}},{"pos":"N-COUNT 可数名词","cn":"图;图谱","en":"A map is a drawing that gives special information about an area.","ex":{"en":"...geological maps, books and atlases.","cn":"地质图、书籍与地图册"}},{"pos":"VERB 动词","cn":"绘制（某地区）的地图","en":"To map an area means to make a map of it.","ex":{"en":"...a spacecraft which is using radar to map the surface of Venus.","cn":"使用雷达绘制金星表面地图的宇宙飞船"}},{"pos":"PHRASE 短语","cn":"使出名;使名扬四方","en":"If you say that someone or something put a person, thing, or place on the map, you approve of the fact that they made it become well-known and important.","ex":{"en":"...the attempts of the Edinburgh Festival's organisers to put C.P. Taylor firmly on the map","cn":"爱丁堡艺术节的组织者们为使C.P.泰勒名扬四海所作的努力"}},{"pos":"","cn":"","en":"相关词组：map out"}]},"examples":[{"en":"Grammar information enables students to map the structure of a foreign language onto their own.","cn":"语法知识使学生能够把外语结构和母语结构联系起来。"},{"en":"an unexplored region that has not yet been mapped","cn":"一个尚未绘制地图的未经勘察的地区"}]},"magically":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very enjoyable, exciting, or romantic, in a strange or special way","cn":""},{"en":"relating to magic or able to do magic","cn":""}]},"examples":[{"en":"that magical evening we spent together","cn":"","src":"ld"}],"media":{"uk":"media/uk/magically__gb_1.mp3","us":"media/us/magically__us_1.mp3"},"oxford":{"phon":"ˈmædʒɪkli","pos":"adverb","senses":[{"en":"in a way that cannot easily be explained and seems to involve the use of magic","cn":"神奇地：以一种不易解释的方式，似乎涉及魔术的使用","ex":{"en":"She looked about in the faint hope that Simon might magically appear from nowhere.","cn":"她环顾四周，隐约希望西蒙会神奇地突然出现。"}},{"en":"in a very beautiful or pleasant way","cn":"神奇地：以一种非常美丽或令人愉快的方式迷人地成为","ex":{"en":"Bulgaria is a magically beautiful country.","cn":"保加利亚是一个神奇美丽的国家。"}},{"en":"by magic; using magic","cn":"神奇地 使用魔术","ex":{"en":"He found himself magically transported to 14th-century England.","cn":"他发现自己神奇地穿越到了 14 世纪的英国。"}}]}},"mathematics":{"oxford":{"phon":"ˌmæθəˈmætɪks","pos":"noun","senses":[{"en":"the study of numbers and shapes. Branches of mathematics include arithmetic, algebra, geometry and trigonometry.","cn":"数学","g":"[uncountable]","ex":{"en":"the school mathematics curriculum","cn":"学校数学课程"}},{"en":"the process of calculating using numbers","cn":"运算；计算","g":"[uncountable + singular or plural verb]","ex":{"en":"He worked out the very difficult mathematics in great detail.","cn":"他十分详细地解答了那些很难的运算。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"数学","en":"Mathematics is the study of numbers, quantities, or shapes.","ex":{"en":"Elizabeth studied mathematics and classics.","cn":"伊丽莎白学过数学和古典文学。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"数学运算;(数学题的)运算过程","en":"The mathematics of a problem is the calculations that are involved in it.","ex":{"en":"Once you understand the mathematics of debt you can work your way out of it.","cn":"一旦掌握了债务计算，你就能迎刃而解。"}}]},"media":{"uk":"media/uk/mathematics__gb_1.mp3","us":"media/us/mathematics__us_1.mp3"},"examples":[{"en":"He worked out the very difficult mathematics in great detail.","cn":"他详细地解答了那些很难的运算。"},{"en":"Some people are very mathematically inclined (= interested in and good at mathematics).","cn":"有些人特别喜欢并擅长数学。"}]},"mama":{"media":{"uk":"media/uk/mama__gb_1.mp3","us":"media/us/mama__us_1.mp3"},"oxford":{"phon":"ˈmæmə","pos":"noun","senses":[{"en":"mother","cn":"妈妈","lab":"North American English or old-fashioned, British English，，"},{"en":"in some places in Africa, a mother or older woman (often used as a title that shows respect)","cn":"妈妈，大妈（非洲某些地方对母亲的称呼或对年长妇女的尊称）","ex":{"en":"Leave this work to us, mama.","cn":"这活儿留给我们干吧，妈妈。"}},{"en":"an uncle who is the brother of your mother","cn":"舅舅"},{"en":"a word used to address an older man, expressing respect","cn":"对年长者敬称"}]},"collins":{"senses":[{"pos":"N-FAMILY 家庭成员名词","cn":"同mother","en":"Mama means the same as mother ."},{"pos":"","cn":"","en":"→see: ;"}]},"examples":[{"en":"Miriam Makeba became known as Mama Africa.","cn":"米丽亚姆 · 马凯巴被称为非洲之母。"},{"en":"Leave this work to us, mama.","cn":"这活儿留给我们干吧，妈妈。"}]},"manipulation":{"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to make someone do what you want them to do by cleverly influencing them, especially when they do not realize what you are doing","cn":""},{"en":"to secretly control an organization, country or situation, by controlling the person or group that is officially in charge of it","cn":""}]},"examples":[{"en":"He was one of those men who manipulated people.","cn":"","src":"ld"},{"en":"You have the constant feeling you are being manipulated.","cn":"","src":"ld"}],"media":{"uk":"media/uk/manipulation__gb_1.mp3","us":"media/us/manipulation__us_1.mp3"},"oxford":{"phon":"məˌnɪpjuˈleɪʃn","pos":"noun","senses":[{"en":"behaviour that controls or influences somebody/something, often in a dishonest way so that they do not realize it","cn":"（暗中的）控制，操纵，影响","g":"[uncountable, countable]","lab":"disapproving","ex":{"en":"Advertising like this is a cynical manipulation of the elderly.","cn":"这类广告为了私利控制老年人的思想。"}},{"en":"the control or use of something in a way that shows skill","cn":"（熟练）操作，处理","g":"[uncountable]","lab":"formal","ex":{"en":"data manipulation","cn":"数据处理"}},{"en":"the skill or act of moving a person's bones or joints into the correct position","cn":"正骨；治疗脱臼","g":"[uncountable, countable]","lab":"specialist","ex":{"en":"manipulation of the bones of the back","cn":"脊椎骨的复位"}}]}},"magnetic":{"media":{"uk":"media/uk/magnetic__gb_1.mp3","us":"media/us/magnetic__us_1.mp3"},"oxford":{"phon":"mæɡˈnetɪk","pos":"adjective","senses":[{"en":"behaving like a magnet; that can be attracted by a magnet","cn":"有磁性的","ex":{"en":"magnetic materials","cn":"磁性材料"}},{"en":"connected with or produced by magnetism","cn":"磁的；磁性的","ex":{"en":"magnetic properties/forces","cn":"磁性；磁力"}},{"en":"that people find very powerful and attractive","cn":"富有吸引力的；有魅力的","ex":{"en":"a magnetic personality","cn":"富有魅力的个性"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"磁的;磁性的","en":"If something metal is magnetic, it acts like a magnet.","ex":{"en":"...magnetic particles.","cn":"磁性微粒"}},{"pos":"ADJ 形容词","cn":"磁力(作用)的","en":"You use magnetic to describe something that is caused by or relates to the force of magnetism.","ex":{"en":"The electrically charged gas particles are affected by magnetic forces.","cn":"带电气体粒子会受磁力影响。"}},{"pos":"ADJ 形容词","cn":"磁化的;带磁性的","en":"You use magnetic to describe tapes and other objects which have a coating of a magnetic substance and contain coded information that can be read by computers or other machines.","ex":{"en":"...her magnetic strip ID card.","cn":"她的磁条身份证"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"引人注目的;有吸引力的;有魅力的","en":"If you describe something as magnetic, you mean that it is very attractive to people because it has unusual, powerful, and exciting qualities.","ex":{"en":"...the magnetic effect of the prosperous German economy on would-be immigrants.","cn":"繁荣的德国经济对未来移民的吸引力"}}]},"examples":[{"en":"The block becomes magnetic when the current is switched on.","cn":"一通上电流，这块板就会有磁性。"},{"en":"a magnetic disk (= one containing magnetic tape that stores information to be used by a computer)","cn":"磁盘"}]},"mankind":{"media":{"uk":"media/uk/mankind__gb_1.mp3","us":"media/us/mankind__us_1.mp3"},"oxford":{"phon":"mænˈkaɪnd","pos":"noun","senses":[{"en":"all humans, thought of as one large group; the human race","cn":"人类","lab":"British English","ex":{"en":"the history of mankind","cn":"人类的历史"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"人，人类（该用法存有争议）","en":"You can refer to all human beings as mankind when considering them as a group. Some people dislike this use.","ex":{"en":"...the evolution of mankind.","cn":"人类的进化"}}]},"examples":[{"en":"an invention for the good of all mankind","cn":"造福全人类的一项发明"},{"en":"the history of mankind","cn":"人类的历史"}]},"machine":{"media":{"uk":"media/uk/machine__gb_1.mp3","us":"media/us/machine__us_1.mp3"},"oxford":{"phon":"məˈʃiːn","pos":"noun","senses":[{"en":"a piece of equipment with many parts that work together to do a particular task. The power used to work a machine may be electricity, steam, gas, etc. or human power.","cn":"机器；机械装置","ex":{"en":"Machines have replaced human labour in many industries.","cn":"在许多行业中，机器已经替代了人力。"}},{"en":"a computer","cn":"计算机；电脑","ex":{"en":"The new machines will be shipped next month.","cn":"新计算机将于下个月上市。"}},{"en":"a particular machine, for example in the home, when you do not refer to it by its full name","cn":"（不提全称时的简略说法）机器","lab":"informal","ex":{"en":"Just put those clothes in the machine (= the washing machine).","cn":"把那些衣服放到洗衣机里就行了。"}},{"en":"an organized system for achieving something and the people who control it","cn":"机构；组织","ex":{"en":"the president’s propaganda machine","cn":"总统的宣传团队"}},{"en":"a person who acts without thinking and without allowing their feelings to show or to affect their work","cn":"机器般的人（做事呆板，不受感情影响）","lab":"often disapproving","ex":{"en":"In this movie he plays a lean, mean killing machine.","cn":"在这部电影中，他扮演一个精瘦、冷酷无情的杀手。"}},{"en":"to make or shape something with a machine","cn":"（用机器）制造，加工成型","ex":{"en":"This material can be cut and machined easily.","cn":"这种材料很容易用机器切割并加工成型。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"机器;机械","en":"A machine is a piece of equipment which uses electricity or an engine in order to do a particular kind of work.","ex":{"en":"I put the coin in the machine and pulled the lever","cn":"我把硬币投入机器，拉动控制杆。"}},{"pos":"VERB 动词","cn":"用机器制造;用机器加工","en":"If you machine something, you make it or work on it using a machine.","ex":{"en":"The material is machined in a factory","cn":"这种材料在一家工厂里用机器加工成型。"}},{"pos":"N-COUNT 可数名词","cn":"大型机构;严密组织","en":"You can use machine to refer to a large and well-controlled system or organization.","ex":{"en":"...Nazi Germany's military machine","cn":"纳粹德国的军事机构"}},{"pos":"N-COUNT 可数名词","cn":"（由于工作过于劳累或乏味）机械般工作的人，做工作不动脑筋的人","en":"If you say that someone is a machine, you mean that they are so tired or bored that they do their work without thinking.","ex":{"en":"I think I have got to stop or I might turn into a machine","cn":"我想我得停下来了，否则我就会变成一台机器。"}}]},"examples":[{"en":"This material can be cut and machined easily.","cn":"这种材料很容易用机器切割并加工成型。"},{"en":"Machines have replaced human labour in many industries.","cn":"在许多行业中，机器已经替代了人力。"}]},"match":{"media":{"uk":"media/uk/match__gb_1.mp3","us":"media/us/match__us_1.mp3"},"oxford":{"phon":"mætʃ","pos":"noun","senses":[{"en":"a sports event where people or teams compete against each other","cn":"比赛；竞赛","g":"[countable]","lab":"especially British English","sc":"in sport","ex":{"en":"a football match","cn":"足球比赛"}},{"en":"a person who is equal to somebody else in strength, skill, intelligence, etc.","cn":"敌手；旗鼓相当的人","g":"[singular]","sc":"an equal","ex":{"en":"I was no match for him at tennis.","cn":"打网球我根本不是他的对手。"}},{"en":"a person or thing that combines well with somebody/something else","cn":"相配的人（或物）；般配的人（或物）","g":"[singular]","sc":"somebody/something that combines well","ex":{"en":"The curtains and carpet are a good match.","cn":"窗帘和地毯非常相配。"}},{"en":"a thing that is or looks exactly the same as or very similar to something else","cn":"相同的东西；非常相似的东西","g":"[countable]","sc":"something the same","ex":{"en":"I've found a vase that is an exact match of the one I broke.","cn":"我找到了一只花瓶，和我打碎的那个一模一样。"}},{"en":"a small stick made of wood or cardboard that is used for lighting a fire, cigarette, etc.","cn":"火柴","g":"[countable]","sc":"for lighting fires","ex":{"en":"a box of matches","cn":"一盒火柴"}},{"en":"a marriage or a marriage partner","cn":"婚姻；配偶","g":"[countable]","lab":"old-fashioned","sc":"marriage","ex":{"en":"He was determined that his daughter should make a good match (= find a suitable husband).","cn":"他下定决心要让女儿嫁个好人家（=找一个合适的丈夫）。"}},{"en":"to find somebody/something that goes together with or is connected with another person or thing","cn":"找相称（或相关）的人（或物）；配对","g":"[transitive]","sc":"find something similar/connected","ex":{"en":"Match the words and pictures.","cn":"匹配单词和图片。"},"pos":"verb"},{"en":"if two things match or if one thing matches another, they are the same or very similar","cn":"相同；相似；相一致","g":"[transitive, intransitive]","sc":"be the same","ex":{"en":"Her fingerprints match those found at the scene of the crime.","cn":"她的指纹与犯罪现场的指纹相吻合。"},"pos":"verb"},{"en":"if two things match, or if one thing matches another, they have the same colour, pattern, or style and therefore look attractive together","cn":"般配；相配","g":"[transitive, intransitive]","sc":"combine well","ex":{"en":"Her dark hair matched the colour of her eyes.","cn":"她的深色头发和眼睛的颜色很相配。"},"pos":"verb"},{"en":"to be as good, interesting, successful, etc. as somebody/something else","cn":"与…相匹敌；和…不相上下","g":"[transitive]","sc":"be equal/better","ex":{"en":"The profits made in the first year have never been matched.","cn":"历年获得的利润都比不上第一年的。"},"pos":"verb"},{"en":"to make something the same as or better than something else","cn":"使等同于；使优于","g":"[transitive]","sc":"be equal/better","ex":{"en":"The company was unable to match his current salary.","cn":"当时公司付不起和他现在相同的工资。"},"pos":"verb"},{"en":"to provide something that is suitable for or enough for a particular situation","cn":"适应；满足","g":"[transitive]","sc":"provide something suitable","ex":{"en":"Investment in hospitals is needed now to match the future needs of the country.","cn":"为了适应国家未来的需要，必须现在就投资医院建设。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（体育）比赛;球赛","en":"A match is an organized game of football, tennis, cricket, or some other sport.","ex":{"en":"He was watching a football match","cn":"他正在观看一场足球比赛。"}},{"pos":"N-COUNT 可数名词","cn":"火柴","en":"A match is a small wooden stick with a substance on one end that produces a flame when you rub it along the rough side of a matchbox.","ex":{"en":"...a packet of cigarettes and a box of matches.","cn":"一包香烟和一盒火柴"}},{"pos":"V-RECIP-ERG","cn":"（颜色、样式等）与…相称，与…相配","en":"If something of a particular colour or design matches another thing, they have the same colour or design, or have a pleasing appearance when they are used together.","ex":{"en":"Her nails were painted bright red to match her dress","cn":"她的指甲涂成了大红色，为的是与裙子相配。"}},{"pos":"V-RECIP-ERG","cn":"（数量或质量）比得上,与…不相上下,使一致","en":"If something such as an amount or a quality matches with another amount or quality, they are both the same or equal. If you match two things, you make them the same or equal.","ex":{"en":"Their strengths in memory and spatial skills matched","cn":"他们在记忆力和空间技能方面势均力敌。"}},{"pos":"V-RECIP-ERG","cn":"与…配对;与…匹配","en":"If one thing matches another, they are connected or suit each other in some way.","ex":{"en":"The students are asked to match the books with the authors","cn":"要求学生把书籍与作者对应起来。"}},{"pos":"N-SING 单数名词","cn":"相配的物(或人)","en":"If a combination of things or people is a good match, they have a pleasing effect when placed or used together.","ex":{"en":"Helen's choice of lipstick was a good match for her skin-tone","cn":"海伦选择的唇膏很适合她的肤色。"}},{"pos":"VERB 动词","cn":"比得上;配得上;敌得过","en":"If you match something, you are as good as it or equal to it, for example in speed, size, or quality.","ex":{"en":"They played some fine attacking football, but I think we matched them in every respect","cn":"他们的攻势足球踢得不错，不过我认为我们各方面和他们比起来都不逊色。"}},{"pos":"VERB 动词","cn":"使较量;使竞赛","en":"In a sport or other contest, if you match one person or team against another, in sports or other contests, you make them compete with each other to see which one is better.","ex":{"en":"The finals of the Championship begin today, matching the United States against France","cn":"锦标赛决赛于今天打响，由美国队对法国队。"}},{"pos":"PHRASE 短语","cn":"遇到强劲的对手;棋逢对手","en":"If you meet your match, you find that you are competing or fighting against someone who you cannot beat because they are as good as you, or better than you.","ex":{"en":"I had finally met my match in power and intellect.","cn":"我终于遇上了与我在力量与智力上不相上下的劲敌。"}},{"pos":"PHRASE 短语","cn":"不能与…相比;敌不过…","en":"If one person or thing is no match for another, they are unable to compete successfully with the other person or thing.","ex":{"en":"I was no match for a man with such power","cn":"我根本不是这样强大的男人的对手。"}},{"pos":"","cn":"","en":"相关词组：match up match up to"}]},"examples":[{"en":"Investment in hospitals is needed now to match the future needs of the country.","cn":"为了适应国家未来的需要，必须现在就投资医院建设。"},{"en":"I've found a vase that is an exact match of the one I broke.","cn":"我找到了一只花瓶，和我打碎的那个一模一样。"}]},"marginal":{"media":{"uk":"media/uk/marginal__gb_1.mp3","us":"media/us/marginal__us_1.mp3"},"oxford":{"phon":"ˈmɑːdʒɪnl","pos":"adjective","senses":[{"en":"small and not important","cn":"小的；微不足道的；不重要的","ex":{"en":"a marginal improvement in weather conditions","cn":"天气条件的略微好转"}},{"en":"relating to or resulting from small changes","cn":"写在页边空白处的","lab":"economics","ex":{"en":"All three companies reported marginal revenue growth.","cn":"这三家公司均报告了边际收入增长。"}},{"en":"not part of a main or important group or situation","cn":"非主体的；边缘的","ex":{"en":"marginal groups in society","cn":"社会中的非主流群体"}},{"en":"won or lost by a very small number of votes and therefore very important or interesting as evidence of public opinion","cn":"（议席或选区）边缘的（以微弱票数决定成败）","lab":"especially British English, politics，，","ex":{"en":"a marginal seat/constituency","cn":"边缘席位／选区"}},{"en":"written in the margin of a page","cn":"写在页边空白处的","g":"[only before noun]","ex":{"en":"marginal notes/comments","cn":"页边的注解／评论"}},{"en":"that cannot produce enough good crops to make a profit","cn":"贫瘠的（因而盈利有限）"},{"en":"a seat in a parliament, on a local council, etc. that was won by a very small number of votes","cn":"（议会或地方委员会的）边缘席位","ex":{"en":"a Labour marginal","cn":"工党的边缘席位"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（事情）微小的，不重要的","en":"If you describe something as marginal, you mean that it is small or not very important.","ex":{"en":"This is a marginal improvement on October","cn":"这是对10月份的一个小小改善。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(人)非主流的，边缘的","en":"If you describe people as marginal, you mean that they are not involved in the main events or developments in society because they are poor or have no power.","ex":{"en":"The tribunals were established for the well-integrated members of society and not for marginal individuals","cn":"特别法庭是为主流社会成员、而非个体设立的。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(席位或选区)边缘的，以相差无几的票数获胜（或失败）的","en":"In political elections, a marginal seat or constituency is one which is usually won or lost by only a few votes, and is therefore of great interest to politicians and journalists.","ex":{"en":"...the views of voters in five marginal seats.","cn":"选民对5个边缘席位的看法"}},{"pos":"ADJ 形容词","cn":"（活动、花费、税项等）边际的，边缘的","en":"Marginal activities, costs, or taxes are not the main part of a business or an economic system, but often make the difference between its success or failure, and are therefore important to control.","ex":{"en":"The analysts applaud the cuts in marginal businesses, but insist the company must make deeper sacrifices","cn":"分析家们赞同削减边缘业务，但坚持认为公司必须作出更大牺牲。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(土地)贫瘠的","en":"Marginal land is not very good for growing crops or grass for animals.","ex":{"en":"The poor are forced to farm in more marginal lands higher up the mountains.","cn":"穷人们被迫在山峦更高处的更为贫瘠的土地上耕作。"}}]},"examples":[{"en":"The story will only be of marginal interest to our readers.","cn":"我们的读者对这则故事不会很感兴趣。"},{"en":"a marginal improvement in weather conditions","cn":"天气条件的略微好转"}]},"manhood":{"media":{"uk":"media/uk/manhood__gb_1.mp3","us":"media/us/manhood__us_1.mp3"},"oxford":{"phon":"ˈmænhʊd","pos":"noun","senses":[{"en":"the state or time of being an adult man rather than a boy","cn":"成年；成年时期","g":"[uncountable]","ex":{"en":"to reach manhood","cn":"达到成年"}},{"en":"the qualities that a man is supposed to have, for example courage, strength and sexual power","cn":"男儿气质","g":"[uncountable]","ex":{"en":"Her new-found power was a threat to his manhood.","cn":"她最近具有的能力对他的男子汉气概是个威胁。"}},{"en":"a man’s penis. People use ‘manhood’ to avoid saying ‘penis’.","cn":"（与 penis 同义，即阴茎）","g":"[singular]","lab":"literary or humorous"},{"en":"all the men of a country","cn":"一国的男子","g":"[uncountable]","lab":"literary","ex":{"en":"The nation's manhood died on the battlefields of World War I.","cn":"这个国家的男子都在第一次世界大战的战场上牺牲了。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"(男性的)成年(期)，成人","en":"Manhood is the state of being a man rather than a boy.","ex":{"en":"They were failing lamentably to help their sons grow from boyhood to manhood.","cn":"他们抱憾未能帮助儿子们顺利地长大成人。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(男人的)成年期","en":"Manhood is the period of a man's life during which he is a man rather than a boy.","ex":{"en":"His handwriting, from earliest young manhood, was flowing and graceful.","cn":"自青年时代起，他就写得一手飘逸雅致的好字。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(总称)男人，男子","en":"If you refer to American manhood or French manhood for example, you are referring to American men or French men considered as a group.","ex":{"en":"Italian manhood was appalled.","cn":"意大利男人吓坏了。"}}]},"examples":[{"en":"The nation's manhood died on the battlefields of World War I.","cn":"这个国家的男子都在第一次世界大战的战场上牺牲了。"},{"en":"Her new-found power was a threat to his manhood.","cn":"她最近具有的能力对他的男子汉气概是个威胁。"}]},"maybe":{"media":{"uk":"media/uk/maybe__gb_1.mp3","us":"media/us/maybe__us_1.mp3"},"oxford":{"phon":"ˈmeɪbi","pos":"adverb","senses":[{"en":"used when you are not certain that something will happen or that something is true or is a correct number","cn":"（不确定）大概，或许，可能","ex":{"en":"Maybe he'll come, maybe he won't.","cn":"他可能来，也可能不来。"}},{"en":"used when making a suggestion","cn":"（提出建议）或许，也许","ex":{"en":"I thought maybe we could go together.","cn":"我觉得或许我们可以一起去。"}},{"en":"used when replying to a question or an idea, especially when you are not sure whether to agree or disagree","cn":"（不置可否）也许，或许","ex":{"en":"‘I think he should resign.’ ‘Maybe.’","cn":"“我觉得他应该辞职。”“也许是吧。”"}},{"en":"something that is only a possibility and is not certain to happen or succeed","cn":"可能的事；不确定的事","ex":{"en":"These are all maybes—there is no certainty.","cn":"这些都有可能，都不确定。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"或许;大概;可能","en":"You use maybe to express uncertainty, for example when you do not know that something is definitely true, or when you are mentioning something that may possibly happen in the future in the way you describe.","ex":{"en":"Maybe she is in love","cn":"她大概是恋爱了。"}},{"pos":"ADV 副词","cn":"也许，或许(用于提出建议、作出礼貌的请求等)","en":"You use maybe when you are making suggestions or giving advice. Maybe is also used to introduce polite requests.","ex":{"en":"Maybe we can go to the movies or something","cn":"也许我们可以去看场电影什么的。"}},{"pos":"ADV 副词","cn":"可能，也许(用于表示某一观点部分属实，但另一观点也应该加以考虑)","en":"You use maybe to indicate that, although a comment is partly true, there is also another point of view that should be considered.","ex":{"en":"Maybe there is jealousy, but I think the envy is more powerful","cn":"也许是羡慕，但我认为更多的是嫉妒。"}},{"pos":"ADV 副词","cn":"可能吧(用于表示未置可否)","en":"You can say maybe as a response to a question or remark, when you do not want to agree or disagree.","ex":{"en":"'Do you think that another country will step in to become the dominant military power in the region?' — 'Maybe.'","cn":"“您认为另一个国家会介入在该地区建立军事霸权吗？”——“可能吧。”"}},{"pos":"ADV 副词","cn":"大概,大约(用于对数目、数量或价值等作出约略的估计)","en":"You use maybe when you are making a rough guess at a number, quantity, or value, rather than stating it exactly.","ex":{"en":"The men were maybe a hundred feet away and coming closer.","cn":"那些人大约有100英尺远，正在向这里靠近。"}},{"pos":"ADV 副词","cn":"有时(尤用于笼统地描述某人的行为或经常发生的事情)","en":"People use maybe to mean 'sometimes', particularly in a series of general statements about what someone does, or about something that regularly happens.","ex":{"en":"They'll come to the bar for a year, or maybe even two, then they'll find another favourite spot.","cn":"他们会在一年，有时甚至是两年里一直光顾这个酒吧，然后再另寻好去处。"}}]},"examples":[{"en":"‘You should stop work when you have the baby.’ ‘Maybe, but I can't afford to.’ “","cn":"有了孩子你就不应该工作了。” “或许是吧，可我负担不起呀。”"},{"en":"‘I think he should resign.’ ‘Maybe.’ “","cn":"我觉得他应该辞职。” “也许是吧。”"}]},"mask":{"oxford":{"phon":"mɑːsk","pos":"noun","senses":[{"en":"something that you wear over your face to hide it, or to frighten or entertain other people","cn":"面具；面罩","ex":{"en":"The robbers wore stocking masks.","cn":"强盗戴着长筒袜面罩。"}},{"en":"something that you wear over part or all of your face in order to protect it","cn":"防护面罩；口罩","ex":{"en":"a surgical/gas mask","cn":"医用外科口罩；防毒面具"}},{"en":"a thick cream made of various substances that you put on your face and neck in order to improve the quality of your skin","cn":"护肤膜；面膜","ex":{"en":"a face mask","cn":"面膜"}},{"en":"a manner or an expression that hides your true character or feelings","cn":"伪装；掩饰","g":"[usually singular]","ex":{"en":"He longed to throw off the mask of respectability.","cn":"他渴望丢掉那副道貌岸然的伪装。"}},{"en":"to hide a feeling, smell, fact, etc. so that it cannot be easily seen or noticed","cn":"掩饰；掩藏","ex":{"en":"She masked her anger with a smile.","cn":"她用微笑来掩饰她的愤怒。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"面具;面罩;假面","en":"A mask is a piece of cloth or other material, which you wear over your face so that people cannot see who you are, or so that you look like someone or something else.","ex":{"en":"The gunman, whose mask had slipped, fled.","cn":"面罩掉落的持枪歹徒逃之夭夭了。"}},{"pos":"N-COUNT 可数名词","cn":"（防细菌或有害物质的）防护面罩,面具，口罩","en":"A mask is a piece of cloth or other material that you wear over all or part of your face to protect you from germs or harmful substances.","ex":{"en":"You must wear goggles and a mask that will protect you against the fumes","cn":"为了免受烟雾危害，你必须戴上护目镜和面罩。"}},{"pos":"N-COUNT 可数名词","cn":"(掩盖真实感情或性格的)伪装，掩饰","en":"If you describe someone's behaviour as a mask, you mean that they do not show their real feelings or character.","ex":{"en":"His mask of detachment cracked, and she saw for an instant an angry and violent man.","cn":"他冷静超然的伪装破碎了，一瞬间她的面前出现了一个愤怒而又狂暴的男人。"}},{"pos":"N-COUNT 可数名词","cn":"（护肤用的）面膜","en":"A mask is a thick cream or paste made of various substances, which you spread over your face and leave for some time in order to improve your skin.","ex":{"en":"This mask leaves your complexion feeling soft and supple.","cn":"这种面膜能使你的皮肤变得柔软细嫩。"}},{"pos":"VERB 动词","cn":"掩饰(情感);伪装","en":"If you mask your feelings, you deliberately do not show them in your behaviour, so that people cannot know what you really feel.","ex":{"en":"Dena lit a cigarette, trying to mask her agitation.","cn":"德娜点燃了一根烟，试图掩饰不安。"}},{"pos":"VERB 动词","cn":"遮住;掩蔽;使…不易察觉","en":"If one thing masks another, it prevents people from noticing or recognizing the other thing.","ex":{"en":"A thick grey cloud masked the sun","cn":"一片厚厚的乌云遮住了太阳。"}}]},"media":{"img":["media/pic/mask_comp.jpg","media/thumb/mask.jpg"],"uk":"media/uk/mask__gb_1.mp3","us":"media/us/mask__us_1.mp3"},"examples":[{"en":"Her face was a cold blank mask.","cn":"她装出一副冷冰冰毫无表情的样子。"},{"en":"He longed to throw off the mask of respectability.","cn":"他渴望丢掉那副道貌岸然的伪装。"}]},"mall":{"media":{"uk":"media/uk/mall__gb_1.mp3","us":"media/us/mall__us_1.mp3"},"oxford":{"phon":"mɔːl","pos":"noun","senses":[{"en":"a large building or covered area that has many shops, restaurants, etc. inside it","cn":"购物商场；购物广场","lab":"especially British English","ex":{"en":"Let's go to the mall.","cn":"我们去商场吧。"}},{"en":"mobile assisted language learning (a method of learning languages with the help of a mobile phone)","cn":"移动辅助语言学习（全写为 mobile assisted language learning，利用手机等移动设备来学习语言）","pos":"abbreviation"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（封闭式）大型购物区，购物中心","en":"A mall is a very large enclosed shopping area."}]},"examples":[{"en":"Some teenagers were hanging out at the mall.","cn":"有些青少年在大型购物中心里闲逛。"},{"en":"Let's go to the mall.","cn":"我们去商场吧。"}]},"magistrate":{"oxford":{"phon":"ˈmædʒɪstreɪt","pos":"noun","senses":[{"en":"an official who acts as a judge in the lowest courts of law","cn":"治安法官；基层司法官员","ex":{"en":"to come up before the magistrates","cn":"在地方法院出庭"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（处理轻罪或纠纷的）地方法官，治安法官","en":"A magistrate is an official who acts as a judge in law courts which deal with minor crimes or disputes."}]},"media":{"uk":"media/uk/magistrate__gb_1.mp3","us":"media/us/magistrate__us_1.mp3"},"examples":[{"en":"to come up before the magistrates","cn":"在地方法院出庭"},{"en":"a magistrates' court","cn":"地方治安法庭"}]},"maintenance":{"media":{"uk":"media/uk/maintenance__gb_1.mp3","us":"media/us/maintenance__us_1.mp3"},"oxford":{"phon":"ˈmeɪntənəns","pos":"noun","senses":[{"en":"the act of keeping something in good condition by checking or repairing it regularly","cn":"维护；保养","ex":{"en":"The school pays for heating and the maintenance of the buildings.","cn":"学校负担这些大楼的供热和维修费用。"}},{"en":"the act of making a state or situation continue","cn":"维持；保持","ex":{"en":"the maintenance of international peace","cn":"维护世界和平"}},{"en":"the money needed for somebody's living expenses; the act of providing this money","cn":"生活费；维持生计","ex":{"en":"Most students need to take out loans for maintenance as well as tuition fees.","cn":"大多数学生需要贷款来维持生活和支付学费。"}},{"en":"money that somebody must pay regularly to their former wife, husband or partner, especially when they have had children together","cn":"（依法应负担的）生活费，抚养费","lab":"British English, law，，","ex":{"en":"He has to pay maintenance to his ex-wife.","cn":"他必须付给前妻生活费。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"（对建筑物、道路、机器等的）定期维修，检修，保养","en":"The maintenance of a building, vehicle, road, or machine is the process of keeping it in good condition by regularly checking it and repairing it when necessary.","ex":{"en":"...maintenance work on government buildings","cn":"政府大楼的修缮工作"}},{"pos":"N-UNCOUNT 不可数名词","cn":"赡养费；生活费","en":"Maintenance is money that someone gives regularly to another person to pay for the things that the person needs.","ex":{"en":"...the government's plan to make absent fathers pay maintenance for their children.","cn":"使弃家的父亲支付孩子抚养费的政府计划"}},{"pos":"N-UNCOUNT 不可数名词","cn":"（状态、进程等的）维持，保持","en":"If you ensure the maintenance of a state or process, you make sure that it continues.","ex":{"en":"...the maintenance of peace and stability in Asia.","cn":"维护亚洲的和平与稳定"}}]},"examples":[{"en":"The school pays for heating and the maintenance of the buildings.","cn":"学校负担这些大楼的供热和维修费用。"},{"en":"a maintenance order (= given by a court of law) （","cn":"法院下达的）生活费支付令"}]},"master":{"media":{"uk":"media/uk/master__gb_1.mp3","us":"media/us/master__us_1.mp3"},"oxford":{"phon":"ˈmɑːstə(r)","pos":"noun","senses":[{"en":"a man who has people working for him, often as servants in his home","cn":"（男）主人，雇主","sc":"of servants","ex":{"en":"They lived in fear of their master.","cn":"他们惧怕主人，提心吊胆地过日子。"}},{"en":"a person who is in charge of an organization or group","cn":"（组织或团体的）头领，主管","sc":"person in control","ex":{"en":"The police had to obey their political masters.","cn":"警察必须服从他们的政治主人。"}},{"en":"a person who is able to control something","cn":"主宰；主人；有控制力的人","sc":"person in control","ex":{"en":"She was no longer master of her own future.","cn":"她已无法把握自己的未来。"}},{"en":"a person who shows a lot of skill at something","cn":"能手；擅长…者","sc":"person with skill","ex":{"en":"a master of disguise","cn":"精于伪装的人"}},{"en":"a famous painter who lived in the past","cn":"（已故）著名画家，绘画大师","sc":"famous painter","ex":{"en":"an exhibition of work by the French master, Monet","cn":"法国著名画家莫奈的作品展"}},{"en":"a second university degree, or, in Scotland, a first university degree, such as an MA","cn":"硕士学位；（苏格兰）学士学位","sc":"university degree","ex":{"en":"He has a Master's in Business Administration.","cn":"他有工商管理硕士学位。"}},{"en":"a person who has a master’s degree","cn":"硕士；有硕士学位的人","sc":"university degree","ex":{"en":"a Master of Arts/Science","cn":"文科／理科硕士"}},{"en":"the owner of an animal, especially a dog or horse","cn":"（动物，尤指狗或马的）主人","sc":"animal owner","ex":{"en":"The dog saved its master's life.","cn":"这条狗救了它的主人。"}},{"en":"a male teacher at a school, especially a private school","cn":"（尤指私立学校的）男教师","lab":"British English, old-fashioned，，","sc":"teacher","ex":{"en":"the physics master","cn":"物理老师"}},{"en":"the captain of a ship that transports goods","cn":"（货船的）船长","sc":"captain of ship"},{"en":"a version of a recording from which copies are made","cn":"母带；母片；原始拷贝","sc":"original record/tape/movie","ex":{"en":"the master copy","cn":"原始拷贝"}},{"en":"a title used when speaking to or about a boy who is too young to be called Mr (also used in front of the name on an envelope, etc.)","cn":"（对年龄小而不便称作“先生”的男孩的称谓；也用在信封等处的人名前）少爷，君","lab":"old-fashioned","sc":"title"},{"en":"(in the UK) the title of the head of some schools and university colleges","cn":"（英国）校长，院长","sc":"title","ex":{"en":"the Master of Wolfson College","cn":"沃尔夫森学院院长"}},{"en":"a title used for speaking to or about some religious teachers or leaders","cn":"（对宗教导师或领袖的称谓）大师，师父","sc":"title"},{"en":"to learn or understand something completely","cn":"精通；掌握","sc":"learn/understand","ex":{"en":"She never completely mastered the art of lip-reading.","cn":"她从未完全掌握唇读术。"},"pos":"verb"},{"en":"to manage to control an emotion","cn":"控制（情绪）","sc":"control","ex":{"en":"She struggled hard to master her temper.","cn":"她竭力按住性子，不发脾气。"},"pos":"verb"},{"en":"to gain control of an animal or a person","cn":"控制（动物或人）","sc":"control","pos":"verb"},{"en":"used to describe a person who shows a lot of skill at the job mentioned, especially one who is able to teach the skills to others","cn":"技艺精湛的；大师级别的","sc":"showing skill","ex":{"en":"the skills of a master craftsman","cn":"工艺大师的技艺"},"pos":"adjective"},{"en":"the largest and/or most important","cn":"最大的；最重要的","sc":"most important","ex":{"en":"the master bedroom","cn":"主卧室"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"主人;雇主;老板","en":"A servant's master is the man that he or she works for.","ex":{"en":"My master ordered me not to deliver the message except in private","cn":"我的主人命令我务必私下里传递消息。"}},{"pos":"N-COUNT 可数名词","cn":"(狗的)拥有者，主人","en":"A dog's master is the man or boy who owns it.","ex":{"en":"The dog yelped excitedly when his master opened a desk drawer and produced his leash.","cn":"主人打开抽屉拿出牵狗用的皮带时，狗兴奋地叫了起来。"}},{"pos":"N-COUNT 可数名词","cn":"专家;能手;高手","en":"If you say that someone is a master of a particular activity, you mean that they are extremely skilled at it.","ex":{"en":"She was a master of the English language","cn":"她是英文高手。"}},{"pos":"N-VAR 可变名词","cn":"（局势的）控制者，主宰者","en":"If you are master of a situation, you have complete control over it.","ex":{"en":"Jackson remained calm and always master of his passions","cn":"杰克逊镇定自若，始终克制着情绪。"}},{"pos":"VERB 动词","cn":"掌握;精通","en":"If you master something, you learn how to do it properly or you succeed in understanding it completely.","ex":{"en":"Duff soon mastered the skills of radio production","cn":"达夫很快掌握了广播节目制作的技能。"}},{"pos":"VERB 动词","cn":"控制;掌控","en":"If you master a difficult situation, you succeed in controlling it.","ex":{"en":"When you have mastered one situation you have to go on to the next","cn":"一旦控制住了一个局面，又得接着应付下一个。"}},{"pos":"N-COUNT 可数名词","cn":"男教师","en":"A master is a male teacher.","ex":{"en":"Mr Palmer was a retired maths master.","cn":"帕尔默先生是一名退休的数学教师。"}},{"pos":"N-COUNT 可数名词","cn":"(已故)著名画家，艺术大师","en":"A famous male painter of the past is often called a master .","ex":{"en":"...a portrait by the Dutch master, Vincent Van Gogh.","cn":"一幅由荷兰著名画家文森特·凡·高所作的画像"}},{"pos":"ADJ 形容词","cn":"（电影、录音等）原始拷贝的，母盘的，母带的","en":"A master copy of something such as a film or a tape recording is an original copy that can be used to produce other copies.","ex":{"en":"Keep one as a master copy for your own reference and circulate the others.","cn":"一盘留作母带自用，其余的都分发出去。"}},{"pos":"N-COUNT 可数名词","cn":"(商船的)船长","en":"The master of a ship that carries passengers or goods is its captain.","ex":{"en":"...the Royal Pacific's master.","cn":"“皇家太平洋”号的船长"}},{"pos":"N-SING 单数名词","cn":"硕士学位","en":"A master's degree can be referred to as a master's .","ex":{"en":"I've a master's in economics.","cn":"我获得了经济学硕士学位。"}},{"pos":"N-COUNT 可数名词","cn":"长老(信徒对宗教法师或领袖的称呼)","en":"Master is sometimes used by the followers of a male religious teacher or leader as a way of referring to him or addressing him.","ex":{"en":"She believed that she had been selected by the Master to reveal forgotten wisdom.","cn":"她认为自己是被长老选中来揭示被人们遗忘的智慧的。"}},{"pos":"N-TITLE 头衔名词","cn":"(旧时的)少爷，小主人;君(现在用于信件中对男孩的称谓)","en":"In the past, Master was used before a boy's name as a polite way of referring to him or addressing him. Nowadays, Master can be written before a boy's name when addressing a letter to him.","ex":{"en":"Nice to see you, Master Simon.","cn":"很高兴见到您，西蒙少爷。"}},{"pos":"PHRASE 短语","cn":"自己作主;独立自主","en":"If you say that you are your own master, you mean that your decisions are not controlled by other people and you are free to do what you want.","ex":{"en":"It was no place for a man who liked to be his own master.","cn":"这绝非喜爱独立自主的人能呆下去的地方。"}}]},"examples":[{"en":"They lived in fear of their master.","cn":"他们惧怕主人，提心吊胆地过日子。"},{"en":"He has a Master's in Business Administration.","cn":"他获得了工商管理硕士学位。"}]},"marc":{"media":{"uk":"media/uk/marc__gb_1.mp3","us":"media/us/marc__us_1.mp3"},"oxford":{"phon":"mɑːk","pos":"noun","senses":[{"en":"the substance left after grapes have been pressed to make wine","cn":"（酿酒时将葡萄压榨后的）残渣；葡萄果渣","g":"[uncountable, singular]"},{"en":"a strong alcoholic drink made from this substance","cn":"葡萄渣酒","g":"[uncountable, countable]"}]}},"mail":{"media":{"uk":"media/uk/mail__gb_1.mp3","us":"media/us/mail__us_1.mp3"},"oxford":{"phon":"meɪl","pos":"noun","senses":[{"en":"the official system used for sending and delivering letters, packages, etc.","cn":"邮政；邮递系统","g":"[uncountable]","lab":"British English also","ex":{"en":"a mail service/train/van","cn":"邮政服务／列车／汽车"}},{"en":"letters, packages, etc. that are sent and delivered","cn":"邮件；信件；邮包","g":"[uncountable]","lab":"British English also","ex":{"en":"There isn't much mail today.","cn":"今天邮件不多。"}},{"en":"messages/a message sent or received on a computer","cn":"电子邮件；电邮","g":"[uncountable, countable]","ex":{"en":"Check regularly for new mail.","cn":"定期查看新邮件。"}},{"en":"used in the title of some newspapers","cn":"（用于报纸名）邮报","ex":{"en":"the Mail on Sunday","cn":"《星期日邮报》"}},{"en":"armour (= clothing to protect the body when fighting) made of small metal rings linked together","cn":"锁子甲（护身铠甲）","g":"[uncountable]","ex":{"en":"a coat of mail","cn":"一副锁子甲"}},{"en":"to send something to somebody using the postal system","cn":"邮寄","lab":"especially North American English","ex":{"en":"Don't forget to mail that letter to your mother.","cn":"别忘了把那封信给你妈寄去。"},"pos":"verb"},{"en":"to send a message to somebody by email","cn":"用电子邮件传送；发电邮给","ex":{"en":"Please mail us at the following email address.","cn":"请按下面的电邮地址发电邮给我们。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"邮政;邮政系统","en":"The mail is the public service or system by which letters and parcels are collected and delivered.","ex":{"en":"Your check is in the mail","cn":"您的支票正在邮递中。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"邮件;信件;邮包","en":"You can refer to letters and parcels that are delivered to you as mail .","ex":{"en":"There was no mail except the usual junk addressed to the occupier","cn":"除了寄给业主的常见垃圾信件之外，再没有其他邮件了。"}},{"pos":"VERB 动词","cn":"寄出;邮寄","en":"If you mail a letter or parcel to someone, you send it to them by putting it in a post box or taking it to a post office.","ex":{"en":"Last year, he mailed the documents to French journalists","cn":"他去年把这些文件寄给了法国记者。"}},{"pos":"VERB 动词","cn":"发送(电子邮件)","en":"To mail a message to someone means to send it to them by means of e-mail or a computer network.","ex":{"en":"...if a report must be electronically mailed to an office by 9 am the next day.","cn":"如果一份报告必须在次日早晨9时之前以电子邮件的形式发送至办公室"}},{"pos":"","cn":"","en":"相关词组：mail out"}]},"examples":[{"en":"The virus mails itself forward to everyone in your address book.","cn":"这种病毒通过电子邮件自动转发给通讯录中的所有人。"},{"en":"The company intends to mail 50 000 households in the area.","cn":"公司计划给当地的 5 万个家庭寄信。"}]},"manager":{"media":{"uk":"media/uk/manager__gb_1.mp3","us":"media/us/manager__us_1.mp3"},"oxford":{"phon":"ˈmænɪdʒə(r)","pos":"noun","senses":[{"en":"a person who is in charge of running a business, a shop or a similar organization or part of one","cn":"（企业、店铺等的）经理，经营者，老板","ex":{"en":"a bank/hotel manager","cn":"银行／酒店经理"}},{"en":"a person who deals with the business affairs of an actor, a musician, etc.","cn":"（演员、音乐家等的）经理人，经纪人，个人经理","ex":{"en":"The comedian is unavailable for comment, according to her manager.","cn":"据经纪人说，这名喜剧演员无法作出评论。"}},{"en":"a person who trains and organizes a sports team","cn":"（运动队的）主教练","ex":{"en":"the new manager of Italy","cn":"意大利队的新主教练"}},{"en":"a person who is good at managing resources","cn":"善于管理资源的人","ex":{"en":"She's a good manager who never throws any food away.","cn":"她很会过日子，从不扔掉食物。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"经理;管理人","en":"A manager is a person who is responsible for running part of or the whole of a business organization.","ex":{"en":"The chef, staff and managers are all Chinese.","cn":"厨师、工作人员和经理都是中国人。"}},{"pos":"N-COUNT 可数名词","cn":"(明星、艺人等的)经纪人，业务管理人","en":"The manager of a pop star or other entertainer is the person who looks after their business interests."},{"pos":"N-COUNT 可数名词","cn":"(球队的)主教练(在美国英语中，该词只用于棒球球队，其他运动则用 coach 一词指主教练)","en":"The manager of a sports team is the person responsible for training the players and organizing the way they play. In American English, manager is only used for baseball; in other sports, coach is used instead."}]},"examples":[{"en":"the sales/marketing/personnel manager","cn":"销售部/市场部/人事部经理"},{"en":"the new manager of Italy","cn":"意大利队的新经理"}]},"may":{"media":{"uk":"media/uk/may__gb_1.mp3","us":"media/us/may__us_1.mp3"},"oxford":{"phon":"meɪ","pos":"modal verb","senses":[{"en":"used to say that something is possible","cn":"（有可能但不肯定）也许，可能","ex":{"en":"That may or may not be true.","cn":"这可能是真的，也可能不是。"}},{"en":"used to ask for or give permission","cn":"（征求同意或表示允许）可以","lab":"formal","ex":{"en":"May I come in?","cn":"我可以进来吗？"}},{"en":"used when admitting that something is true before introducing another point, argument, etc.","cn":"（转折前所述情况属实）也许，可能","ex":{"en":"They may be well-meaning, but they are wrong.","cn":"他们可能是善意的，但他们错了。"}},{"en":"used as a polite way of making a comment, asking a question, etc.","cn":"（礼貌地评价或提问等）可以","lab":"formal","ex":{"en":"You look lovely, if I may say so.","cn":"我觉得你看上去很可爱。"}},{"en":"used to express wishes and hopes","cn":"（表示愿望）但愿","lab":"formal","ex":{"en":"May she rest in peace.","cn":"愿她安息。"}},{"en":"used to say what the purpose of something is","cn":"（表明目的）可以，能够","lab":"formal","ex":{"en":"There is a need for more resources so that all children may have a decent education.","cn":"需要更多的资源投入，让所有的孩子都受到良好的教育。"}},{"en":"the white or pink flowers of the hawthorn","cn":"山楂花","pos":"noun"},{"en":"the fifth month of the year, between April and June","cn":"五月","lab":"British English","ex":{"en":"She was born in May.","cn":"她出生于五月。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"五月","en":"May is the fifth month of the year in the Western calendar.","ex":{"en":"On May 18, the employee wrote to the council that he would be taking the doctor's advice","cn":"5月18日，这位雇员致信委员会，称他将遵照医嘱…"}}]},"examples":[{"en":"Business has been thriving in the past year. Long may it continue to do so.","cn":"在过去的一年里生意蒸蒸日上。但愿这种情况能持续下去。"},{"en":"There is a need for more resources so that all children may have a decent education.","cn":"需要更多的财力支持，让所有的孩子都受到良好的教育。"}]},"mane":{"oxford":{"phon":"meɪn","pos":"noun","senses":[{"en":"the long hair on the neck of a horse or a lion","cn":"（马）鬃；（狮）鬣毛","ex":{"en":"She spent ages braiding her horse's mane.","cn":"她花了很长时间辫马鬃。"}},{"en":"a person’s long or thick hair","cn":"长发；浓密的头发","lab":"informal or literary","ex":{"en":"She tossed back her mane of chestnut hair.","cn":"她把栗色的头发向后甩去。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(马或狮子的)鬃毛","en":"The mane on a horse or lion is the long thick hair that grows from its neck."},{"pos":"N-COUNT 可数名词","cn":"浓密的头发","en":"If you refer to a person's hair as their mane, you mean that they have a lot of hair.","ex":{"en":"He had a great mane of white hair.","cn":"他满头浓密的白发。"}}]},"media":{"uk":"media/uk/mane__gb_1.mp3","us":"media/us/mane__us_1.mp3","img":["media/ldoce/img/lion.jpg"]},"examples":[{"en":"her mane of hair","cn":"她那一头浓密的长发"}]},"main":{"media":{"uk":"media/uk/main__gb_1.mp3","us":"media/us/main__us_1.mp3"},"oxford":{"phon":"meɪn","pos":"adjective","senses":[{"en":"being the largest or most important of its kind","cn":"主要的；最重要的","ex":{"en":"Be careful crossing the main road.","cn":"过大马路时小心点儿。"}},{"en":"a large pipe that carries water or gas to a building; a large cable that carries electricity to a building","cn":"（通往建筑物的）主管道，总管，输电干线","g":"[countable]","ex":{"en":"a leaking gas main","cn":"漏气的煤气总管"},"pos":"noun"},{"en":"a large pipe that carries waste water and sewage (= human waste, etc.) away from a building","cn":"（建筑物的）污水总管道","pos":"noun"},{"en":"the place where the supply of water, gas or electricity to a building or an area starts; the system of providing gas, water and electricity to a building or of carrying it away from a building","cn":"水源；煤气源；电源；（水、煤气、电等的）供应系统；下水道系统","g":"[uncountable, plural]","lab":"British English","ex":{"en":"The house is not yet connected to the mains.","cn":"这房子还没有通水电。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"主要的;最重要的","en":"The main thing is the most important one of several similar things in a particular situation.","ex":{"en":"...one of the main tourist areas of Amsterdam","cn":"阿姆斯特丹的主要旅游区之一"}},{"pos":"PHRASE 短语","cn":"大体上;基本上","en":"If you say that something is true in the main, you mean that it is generally true, although there may be exceptions.","ex":{"en":"Tourists are, in the main, sympathetic people","cn":"大体说来，游客们都富有同情心。"}},{"pos":"N-COUNT 可数名词","cn":"(室内煤气、自来水或污水的)总管道，主管道","en":"The mains are the pipes which supply gas or water to buildings, or which take sewage away from them.","ex":{"en":"...the water supply from the mains","cn":"总管道的自来水供应"}},{"pos":"N-PLURAL 复数名词","cn":"电力线;电源","en":"The mains are the wires which supply electricity to buildings, or the place where the wires end inside the building.","ex":{"en":"...amplifiers which plug into the mains","cn":"接通电源的扩音器"}}]},"examples":[{"en":"Our major concern here is combatting poverty.","cn":"在这里我们最关心的是解决贫穷问题。"},{"en":"He played a major role in setting up the system.","cn":"他对建立这个系统起了重要的作用。"}]},"making":{"media":{"uk":"media/uk/making__gb_1.mp3","us":"media/us/making__us_1.mp3"},"oxford":{"phon":"ˈmeɪkɪŋ","pos":"noun","senses":[{"en":"the act or process of making or producing something","cn":"生产；制造","ex":{"en":"strategic decision-making","cn":"战略决策"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"制作;制造;形成","en":"The making of something is the act or process of producing or creating it.","ex":{"en":"...Salamon's book about the making of this movie","cn":"萨拉蒙有关本片制作过程的书"}},{"pos":"PHRASE 短语","cn":"在成长中;在形成中","en":"If you describe a person or thing as something in the making, you mean that they are going to become known or recognized as that thing.","ex":{"en":"Her drama teacher is confident Julie is a star in the making","cn":"朱莉的戏剧老师相信她会成为一颗冉冉升起的明星。"}},{"pos":"PHRASE 短语","cn":"是…成功(或改善)的原因","en":"If something is the making of a person or thing, it is the reason that they become successful or become very much better than they used to be.","ex":{"en":"This discovery may yet be the making of him.","cn":"这次的发现也许会成为他成功的契机。"}},{"pos":"PHRASE 短语","cn":"具备成为…的素质(或内在因素、必要条件、潜在能力)","en":"If you say that a person or thing has the makings of something, you mean it seems possible or likely that they will become that thing, as they have the necessary qualities.","ex":{"en":"Godfrey had the makings of a successful journalist.","cn":"戈弗雷具有成为一名成功记者的潜质。"}},{"pos":"PHRASE 短语","cn":"(问题等)自己造成的;咎由自取","en":"If you say that something such as a problem you have is of your own making, you mean you have caused or created it yourself.","ex":{"en":"Some of the university's financial troubles are of its own making","cn":"这所大学的一些经济困难是由其自身造成的。"}}]},"examples":[{"en":"Her first novel has all the makings of a classic.","cn":"她的第一部小说堪称经典之作。"},{"en":"This model was two years in the making.","cn":"这种型号是用两年时间制成的。"}]},"manufacturing":{"media":{"uk":"media/uk/manufacturing__gb_1.mp3","us":"media/us/manufacturing__us_1.mp3"},"oxford":{"phon":"ˌmænjuˈfæktʃərɪŋ","pos":"noun","senses":[{"en":"the business or industry of producing goods in large quantities in factories, etc.","cn":"制造业","ex":{"en":"Many jobs in manufacturing were lost during the recession.","cn":"在经济衰退期，制造业有很多人失业了。"}}]},"examples":[{"en":"Many jobs in manufacturing were lost during the recession.","cn":"在经济衰退期，制造业有很多人失业了。"},{"en":"Thousands of jobs had been lost in manufacturing.","cn":"制造行业已有数以千计的人失业。"}]},"made":{"media":{"uk":"media/uk/made__gb_1.mp3","us":"media/us/made__us_1.mp3"},"oxford":{"phon":"meɪd","pos":"","senses":[{"en":"made in the way, place, etc. mentioned","cn":"…制造的；制作…的","ex":{"en":"well-made","cn":"制作精良的"}}]},"collins":{"senses":[{"pos":"","cn":"","en":"Made is the past tense and past participle of make ."},{"pos":"ADJ 形容词","cn":"（由…）构成的；（由…）制成的","en":"If something is made of or made out of a particular substance, that substance was used to build it.","ex":{"en":"The top of the table is made of glass","cn":"桌面由玻璃制成。"}},{"pos":"PHRASE 短语","cn":"有成功的把握;具备所需的一切条件","en":"If you say that someone has it made or has got it made, you mean that they are certain to be rich or successful.","ex":{"en":"When I was at school, I thought I had it made.","cn":"上学的时候，我觉得自己一定会出人头地。"}}]},"examples":[{"en":"Peter and Judy seem made for each other, don't they?","cn":"彼得和朱迪像是天生的一对，不是吗？"},{"en":"well-made","cn":"制作精良的"}]},"mandatory":{"oxford":{"phon":"ˈmændətəri","pos":"adjective","senses":[{"en":"required by law","cn":"强制的；法定的；义务的","ex":{"en":"The offence carries a mandatory life sentence.","cn":"这种罪行依照法律要判无期徒刑。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"强制性的; 法定的;义务的","en":"If an action or procedure is mandatory, people have to do it, because it is a rule or a law.","ex":{"en":"...the mandatory retirement age of 65","cn":"65岁的法定退休年龄"}},{"pos":"ADJ 形容词","cn":"(惩罚)强制性的，法定的","en":"If a crime carries a mandatory punishment, that punishment is fixed by law for all cases, in contrast to crimes for which the judge or magistrate has to decide the punishment for each particular case.","ex":{"en":"...the mandatory life sentence for murder.","cn":"谋杀罪必然会面临的终身监禁"}}]},"media":{"uk":"media/uk/mandatory__gb_1.mp3","us":"media/us/mandatory__us_1.mp3"},"examples":[{"en":"It is mandatory for blood banks to test all donated blood for the virus.","cn":"血库必须检查所有捐献的血是否含有这种病毒。"},{"en":"The offence carries a mandatory life sentence.","cn":"这种罪行依照法律要判无期徒刑。"}]},"maximize":{"media":{"uk":"media/uk/maximize__gb_1.mp3","us":"media/us/maximize__us_1.mp3"},"oxford":{"phon":"ˈmæksɪmaɪz","pos":"verb","senses":[{"en":"to increase something as much as possible","cn":"使增加到最大限度","lab":"computing","ex":{"en":"to maximize efficiency/fitness/profits","cn":"最大限度地提高效率／增强体质／增加利润"}},{"en":"to make the best use of something","cn":"充分利用；最大限度地利用","ex":{"en":"to maximize opportunities/resources","cn":"充分利用机会／资源"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"使增加至最大限度;充分利用(或重视)","en":"If you maximize something, you make it as great in amount or importance as you can.","ex":{"en":"In order to maximize profit the firm would seek to maximize output","cn":"为了获得最大利润，这家公司会把产量增至最大。"}},{"pos":"VERB 动词","cn":"使(计算机屏幕上的窗口)最大化","en":"If you maximize a window on a computer screen, you make it as large as possible.","ex":{"en":"Click on the square icon to maximize the window.","cn":"点击方框，把窗口最大化。"}}]},"examples":[{"en":"Maximize the window to full screen.","cn":""},{"en":"( computing","cn":"计 ) Maximize the window to full screen. 将窗口放至最大。"}]},"manicured":{"media":{"uk":"media/uk/manicured__gb_1.mp3","us":"media/us/manicured__us_1.mp3"},"oxford":{"phon":"ˈmænɪkjʊəd","pos":"adjective","senses":[{"en":"with nails that are neatly cut and polished","cn":"精心护理的；修剪整齐的"},{"en":"very neat and well cared for","cn":"整齐的；护理得很好的"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（草坪、花园）修剪整齐的","en":"A manicured lawn, park, or garden has very short neatly cut grass.","ex":{"en":"She stared out at the impeccably manicured garden.","cn":"她向外望去，注视着修剪得整整齐齐、无可挑剔的花园。"}}]},"examples":[{"en":"The ball rolled across the immaculately manicured lawn.","cn":"球滚过修剪得平平整整的草坪。"},{"en":"slim, perfectly manicured fingers","cn":"指甲修得很漂亮的纤纤手指"}]},"magnify":{"oxford":{"phon":"ˈmæɡnɪfaɪ","pos":"verb","senses":[{"en":"to make something look bigger than it really is, for example by using a lens or microscope","cn":"放大","ex":{"en":"bacteria magnified to 1 000 times their actual size","cn":"放大了 1 000 倍的细菌"}},{"en":"to make something bigger, louder or stronger","cn":"扩大；增强","ex":{"en":"The sound was magnified by the high roof.","cn":"高高的屋顶使声音更响亮。"}},{"en":"to make something seem more important or serious than it really is","cn":"夸大（重要性或严重性）；夸张","ex":{"en":"The daring of his exploits had been hugely magnified by constant telling.","cn":"他的英勇行为几经流传已被极大地夸大了。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"放大;扩大","en":"To magnify an object means to make it appear larger than it really is, by means of a special lens or mirror.","ex":{"en":"This version of the Digges telescope magnifies images 11 times","cn":"这种型号的迪格斯望远镜可将图像放大11倍。"}},{"pos":"VERB 动词","cn":"加强;加大;加剧","en":"To magnify something means to increase its effect, size, loudness, or intensity.","ex":{"en":"Poverty and human folly magnify natural disasters","cn":"贫困和人类的愚昧加剧了自然灾难。"}},{"pos":"VERB 动词","cn":"夸大;夸张","en":"If you magnify something, you make it seem more important or serious than it really is.","ex":{"en":"They do not grasp the broad situation and spend their time magnifying ridiculous details","cn":"他们不去把握大局，而是在细枝末节上花费时间大做文章。"}}]},"media":{"uk":"media/uk/magnify__gb_1.mp3","us":"media/us/magnify__us_1.mp3"},"examples":[{"en":"bacteria magnified to 1 000 times their actual size","cn":"放大了 1 000 倍的细菌"},{"en":"The dry summer has magnified the problem of water shortages.","cn":"干燥的夏季加剧了缺水的问题。"}]},"manner":{"media":{"uk":"media/uk/manner__gb_1.mp3","us":"media/us/manner__us_1.mp3"},"oxford":{"phon":"ˈmænə(r)","pos":"noun","senses":[{"en":"behaviour that is considered to be polite in a particular society or culture","cn":"礼貌；礼仪","g":"[plural]","ex":{"en":"to have good/bad manners","cn":"有／没有礼貌"}},{"en":"the way that something is done or happens","cn":"方式；方法","g":"[singular]","lab":"formal","ex":{"en":"She answered in a businesslike manner.","cn":"她回答时显出一副公事公办的样子。"}},{"en":"the way that somebody behaves towards other people","cn":"举止；行为方式","g":"[singular]","ex":{"en":"to have an aggressive/a friendly/a relaxed manner","cn":"带着一副咄咄逼人的／友好的／悠闲的样子"}},{"en":"the habits and customs of a particular group of people","cn":"规矩；习俗","g":"[plural]","lab":"formal","ex":{"en":"the social morals and manners of the seventeenth century","cn":"17 世纪的社会道德和习俗"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"做法;方式","en":"The manner in which you do something is the way that you do it.","ex":{"en":"She smiled again in a friendly manner","cn":"她又友好地微笑了一下。"}},{"pos":"N-SING 单数名词","cn":"用…的方式;以…的风格","en":"If something is done in the manner of something else, it is done in the style of that thing.","ex":{"en":"It's a satire somewhat in the manner of Dickens","cn":"这部讽刺作品有点狄更斯的风格。"}},{"pos":"N-SING 单数名词","cn":"态度;举止","en":"Someone's manner is the way in which they behave and talk when they are with other people, for example whether they are polite, confident, or bad-tempered.","ex":{"en":"His manner was self-assured and brusque","cn":"他态度傲慢无礼。"}},{"pos":"N-PLURAL 复数名词","cn":"有礼貌/没礼貌","en":"If someone has good manners, they are polite and observe social customs. If someone has bad manners, they are impolite and do not observe these customs.","ex":{"en":"He dressed well and had impeccable manners","cn":"他衣冠楚楚，待人接物无可挑剔。"}},{"pos":"PHRASE 短语","cn":"各种各样的;形形色色的","en":"If you refer to all manner of objects or people, you are talking about objects or people of many different kinds.","ex":{"en":"Mr Winchester is impressively knowledgeable about all manner of things.","cn":"温切斯特先生知识广博，通晓万事。"}},{"pos":"PHRASE 短语","cn":"不妨说;也可以说;从某种意义上说","en":"You say in a manner of speaking to indicate that what you have just said is true, but not absolutely or exactly true.","ex":{"en":"An attorney is your employee, in a manner of speaking","cn":"律师也可以说是你的雇员。"}},{"pos":"PHRASE 短语","cn":"（指人或物非同寻常或未知的）什么样的","en":"You use what manner of to suggest that the person or thing you are about to mention is of an unusual or unknown kind.","ex":{"en":"There was much curiosity about what manner of man he was","cn":"他究竟是什么样的人，大家都十分好奇。"}}]},"examples":[{"en":"to have an aggressive/a friendly/a relaxed manner","cn":"带着一副咄咄逼人的/友好的/悠闲的样子"},{"en":"It is bad manners to talk with your mouth full.","cn":"嘴里塞满了东西跟人说话是不礼貌的。"}]},"marks":{"oxford":{"phon":"mɑːk","pos":"verb","senses":[{"en":"to write or draw a symbol, line, etc. on sth in order to give information about it","cn":"作记号；作标记"},{"en":"to make a mark on sth in a way that spoils or damages it; to become spoilt or damaged in this way","cn":"留下痕迹；弄污；使有污点"}]},"media":{"uk":"media/uk/mark__gb_1.mp3","us":"media/us/mark__us_1.mp3"}},"maturity":{"media":{"uk":"media/uk/maturity__gb_1.mp3","us":"media/us/maturity__us_1.mp3"},"oxford":{"phon":"məˈtʃʊərəti","pos":"noun","senses":[{"en":"the quality of thinking and behaving in a sensible, adult manner","cn":"（思想行为、作品等）成熟","ex":{"en":"He has maturity beyond his years.","cn":"他过于老成。"}},{"en":"the state of being fully grown or developed","cn":"成熟；成年；完全长成","ex":{"en":"The forest will take 100 years to reach maturity.","cn":"这片森林要花 100 年时间才能成材。"}},{"en":"understanding and skill that an artist develops over a period of time","cn":"（艺术水平的）成熟","ex":{"en":"These latest paintings show how the artist has really grown in maturity.","cn":"这些最新的画作表明这位画家如何已真正走向了成熟。"}},{"en":"the time when money you have invested is ready to be paid","cn":"到期（应付款）","lab":"business"}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"成熟;长大成人","en":"Maturity is the state of being fully developed or adult.","ex":{"en":"Humans experience a delayed maturity; we arrive at all stages of life later than other mammals.","cn":"人类发育较缓——在生命的各个阶段，我们都晚于其他哺乳动物。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(性格、行为等的)成熟","en":"Someone's maturity is their quality of being fully developed in their personality and emotional behaviour.","ex":{"en":"Her speech showed great maturity and humanity","cn":"她的演讲非常老练，极富人情味。"}},{"pos":"N-VAR 可变名词","cn":"(存单、养老金计划等的)到期","en":"When an investment such as a savings policy or pension plan reaches maturity, it reaches the stage when you stop paying money and the company pays you back the money you have saved, and the interest your money has earned.","ex":{"en":"Customers are told what their policies will be worth on maturity","cn":"客户被告知保险单到期时的价值。"}}]},"examples":[{"en":"The forest will take 100 years to reach maturity.","cn":"这片森林要花 100 年时间才能成材。"},{"en":"Her poems show great maturity.","cn":"她的诗歌显得非常成熟。"}]},"matching":{"oxford":{"phon":"ˈmætʃɪŋ","pos":"adjective","senses":[{"en":"having the same colour, pattern, style, etc. and therefore looking attractive together","cn":"（颜色、形状、款式等）相同的，相称的，相配的","ex":{"en":"The two sisters wore matching outfits.","cn":"两姐妹穿着同款衣服。"}},{"en":"equal in number or amount; having the same qualities, etc.","cn":"数量相同的；品质一样的","ex":{"en":"The college will provide matching funds (= equal to the amount already raised) to complete the project.","cn":"学院将提供等额配套资金来完成该项目。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"(颜色、款式)相同的，一致的，相配的，相称的","en":"Matching is used to describe things which are of the same colour or design.","ex":{"en":"She bought more fabric in the same design so she could make matching curtains and cushions.","cn":"她又买了些图案相同的布，好做些配套的窗帘和垫子。"}}]},"media":{"uk":"media/uk/matching__gb_1.mp3","us":"media/us/matching__us_1.mp3"},"examples":[{"en":"a pine table with four matching chairs","cn":"一张松木桌子和四把配套的椅子"},{"en":"a necklace with matching earrings","cn":"配有耳环的项链"}]},"mastery":{"media":{"uk":"media/uk/mastery__gb_1.mp3","us":"media/us/mastery__us_1.mp3"},"oxford":{"phon":"ˈmɑːstəri","pos":"noun","senses":[{"en":"great knowledge about or understanding of a particular thing","cn":"精通；熟练掌握","g":"[uncountable, singular]","ex":{"en":"She has mastery of several languages.","cn":"她精通数门语言。"}},{"en":"control or power","cn":"控制；驾驭；控制力量","g":"[uncountable]","ex":{"en":"human mastery of the natural world","cn":"人类对自然界的控制"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"精通;掌握","en":"If you show mastery of a particular skill or language, you show that you have learned or understood it completely and have no difficulty using it.","ex":{"en":"He doesn't have mastery of the basic rules of grammar","cn":"他还没有完全掌握基本的语法规则。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"统治;控制","en":"Mastery is power or control over something.","ex":{"en":"Mesopotamia was probably the first region of the world where humans gained mastery over major rivers.","cn":"美索不达米亚地区可能是世界上人类最早征服主干河流的地区。"}}]},"examples":[{"en":"human mastery of the natural world","cn":"人类对自然界的控制"},{"en":"She has mastery of several languages.","cn":"她精通数门语言。"}]},"marionette":{"oxford":{"phon":"ˌmæriəˈnet","pos":"noun","senses":[{"en":"a puppet whose arms, legs and head are moved by strings","cn":"牵线木偶"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"牵线木偶","en":"A marionette is a puppet whose different parts you can move using strings or wires."}]},"media":{"uk":"media/uk/marionette__gb_1.mp3","us":"media/us/marionette__us_1.mp3"}},"manifest":{"media":{"uk":"media/uk/manifest__gb_1.mp3","us":"media/us/manifest__us_1.mp3"},"oxford":{"phon":"ˈmænɪfest","pos":"verb","senses":[{"en":"to show something clearly, especially a feeling, an attitude or a quality","cn":"表明，清楚显示（尤指情感、态度或品质）","ex":{"en":"Social tensions were manifested in the recent political crisis.","cn":"最近的政治危机显示了社会关系的紧张。"}},{"en":"to appear or become easy to notice","cn":"显现；使人注意到","ex":{"en":"The symptoms of the disease manifested themselves ten days later.","cn":"十天后，这种病的症状显现出来。"}},{"en":"easy to see or understand","cn":"明显的；显而易见的","ex":{"en":"His nervousness was manifest to all those present.","cn":"所有在场的人都看出了他很紧张。"},"pos":"adjective"},{"en":"a list of goods or passengers on a ship or an aircraft","cn":"（船或飞机的）货单，旅客名单","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"明显的;显而易见的","en":"If you say that something is manifest, you mean that it is clearly true and that nobody would disagree with it if they saw it or considered it.","ex":{"en":"...the manifest failure of the policies","cn":"政策明显的失败之处"}},{"pos":"V-ERG 及物/不及物动词","cn":"显示;显露","en":"If you manifest a particular quality, feeling, or illness, or if it manifests itself, it becomes visible or obvious.","ex":{"en":"He manifested a pleasing personality on stage","cn":"在台上他表现出惹人喜爱的个性。"}}]},"examples":[{"en":"Social tensions were manifested in the recent political crisis.","cn":"最近的政治危机显示了社会关系的紧张。"},{"en":"The anger he felt is manifest in his paintings.","cn":"他的愤怒明显地表现在他的绘画之中。"}]},"male":{"media":{"uk":"media/uk/male__gb_1.mp3","us":"media/us/male__us_1.mp3"},"oxford":{"phon":"meɪl","pos":"adjective","senses":[{"en":"being a man or boy","cn":"男的","ex":{"en":"a male friend/colleague/partner","cn":"男性朋友／同事／伴侣"}},{"en":"belonging to the sex that does not lay eggs or give birth to babies","cn":"雄性的；男性的","ex":{"en":"a male bird","cn":"雄鸟"}},{"en":"of men; typical of men; affecting men","cn":"男人的；男性特有的","lab":"British English","ex":{"en":"male attitudes to women","cn":"男人对女人的看法"}},{"en":"producing pollen","cn":"雄性的","lab":"biology","ex":{"en":"Live oaks produce male flowers called catkins.","cn":"弗吉尼亚栎开雄花，名为柔荑花序。"}},{"en":"having a part that sticks out that is designed to fit into a hole, socket, etc.","cn":"阳的；凸形的","lab":"specialist","ex":{"en":"male connectors/adapters","cn":"公头连接器／适配器"}},{"en":"a male person, animal or plant","cn":"男性；雄性；雄株","lab":"formal","ex":{"en":"The male of the species has a white tail.","cn":"这一物种的雄性有一条白色的尾巴。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"男人的;男性的","en":"Someone who is male is a man or a boy.","ex":{"en":"Many women achievers appear to pose a threat to their male colleagues","cn":"许多事业有成的女性似乎对她们的男同事构成了一种威胁。"}},{"pos":"N-COUNT 可数名词","cn":"男子;男性","en":"Men and boys are sometimes referred to as males when they are being considered as a type.","ex":{"en":"...the remains of a Caucasian male, aged 65-70","cn":"65岁至70岁之间的白人男性的遗骸"}},{"pos":"ADJ 形容词","cn":"男人的;男性的","en":"Male means relating, belonging, or affecting men rather than women.","ex":{"en":"The rate of male unemployment in Britain is now the third worst in Europe.","cn":"英国男性的失业率目前高居欧洲第三位。"}},{"pos":"N-COUNT 可数名词","cn":"雄性","en":"You can refer to any creature that belongs to the sex that cannot lay eggs or have babies as a male .","ex":{"en":"Males and females take turns brooding the eggs.","cn":"雄鸟和雌鸟轮流孵蛋。"}},{"pos":"ADJ 形容词","cn":"（植物）雄株的;（花卉）雄蕊的","en":"A male flower or plant fertilizes the part that will become the fruit."}]},"examples":[{"en":"All the attackers were male, aged between 25 and 30.","cn":"所有的袭击者都是男性，年龄在 25 到 30 岁之间。"},{"en":"( formal ) The body is that of a white male aged about 40.","cn":"尸体是一名 40 岁上下的白人男子。"}]},"materialistic":{"media":{"uk":"media/uk/materialistic__gb_1.mp3","us":"media/us/materialistic__us_1.mp3"},"oxford":{"phon":"məˌtɪəriəˈlɪstɪk","pos":"adjective","senses":[{"en":"caring more about money and possessions than anything else","cn":"物质享乐主义的；贪图享乐的","ex":{"en":"We're living in a highly materialistic society.","cn":"我们生活在一个高度物质化的社会。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"实利主义的;物质至上主义的","en":"If you describe a person or society as materialistic, you are critical of them because they attach too much importance to money and material possessions.","ex":{"en":"During the 1980s Britain became a very materialistic society.","cn":"20世纪80年代期间，英国变成一个物质至上的社会。"}}]},"examples":[{"en":"He’s so materialistic.","cn":"他太实利主义了。"},{"en":"the materialistic values of American society","cn":"美国社会的实利主义价值观"}]},"malicious":{"media":{"uk":"media/uk/malicious__gb_1.mp3","us":"media/us/malicious__us_1.mp3"},"oxford":{"phon":"məˈlɪʃəs","pos":"adjective","senses":[{"en":"having or showing a desire to harm somebody or hurt their feelings, caused by a feeling of hate","cn":"怀有恶意的；恶毒的","ex":{"en":"malicious gossip/lies/rumours","cn":"恶毒的流言蜚语／谎言／谣言"}},{"en":"intended to damage somebody's computer or data files","cn":"恶意的；有病毒的","lab":"computing","ex":{"en":"These are nasty pieces of malicious code such as viruses, Trojan horses and worms.","cn":"这些是令人讨厌的恶意代码，例如病毒、特洛伊木马和蠕虫。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"心怀恶意的;恶毒的;怀恨的","en":"If you describe someone's words or actions as malicious, you mean that they are intended to harm people or their reputation, or cause them embarrassment and upset.","ex":{"en":"That might merely have been malicious gossip","cn":"那也许仅仅是些不怀好意的流言蜚语罢了。"}}]},"examples":[{"en":"He took malicious pleasure in telling me what she had said.","cn":"他幸灾乐祸地告诉我她说的那些话。"},{"en":"malicious gossip/lies/rumours","cn":"恶毒的流言蜚语/谎言/谣言"}]},"manageable":{"media":{"uk":"media/uk/manageable__gb_1.mp3","us":"media/us/manageable__us_1.mp3"},"oxford":{"phon":"ˈmænɪdʒəbl","pos":"adjective","senses":[{"en":"possible to deal with or control","cn":"可操纵的；可处理的","ex":{"en":"Use conditioner regularly to make your hair soft and manageable.","cn":"经常使用护发剂来使你的头发柔软而且易于梳理。"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"容易管理的;容易对付的","en":"Something that is manageable is of a size, quantity, or level of difficulty that people are able to deal with.","ex":{"en":"He will now try to cut down the task to a manageable size","cn":"他现在要努力把任务的规模降至可控的范围。"}}]},"examples":[{"en":"Use conditioner regularly to make your hair soft and manageable.","cn":"经常使用护发剂来使你的头发柔软而且易于梳理。"},{"en":"The debt has been reduced to a more manageable level.","cn":"债务减到了比较能够应付的程度。"}]},"marriage":{"media":{"uk":"media/uk/marriage__gb_1.mp3","us":"media/us/marriage__us_1.mp3"},"oxford":{"phon":"ˈmærɪdʒ","pos":"noun","senses":[{"en":"the legal relationship between two people who are married to each other","cn":"婚姻","g":"[countable]","ex":{"en":"a happy/an unhappy marriage","cn":"幸福的／不幸福的婚姻"}},{"en":"the state of being married","cn":"婚姻生活；已婚状态","g":"[uncountable]","ex":{"en":"They don't believe in marriage.","cn":"他们不相信婚姻。"}},{"en":"the ceremony in which two people marry each other","cn":"婚礼","g":"[countable]","lab":"especially North American English","ex":{"en":"Their marriage took place in a local church.","cn":"他们的婚礼在当地一所教堂举行。"}},{"en":"a combination of two things","cn":"（两者的）结合","ex":{"en":"The new collection is a marriage of fashion and technology.","cn":"新系列是时尚与科技的结合。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"婚姻","en":"A marriage is the relationship between a husband and wife.","ex":{"en":"In a good marriage, both husband and wife work hard to solve any problems that arise","cn":"美满的婚姻中，夫妻双方会共同努力去解决出现的任何问题。"}},{"pos":"N-VAR 可变名词","cn":"结婚;婚礼","en":"A marriage is the act of marrying someone, or the ceremony at which this is done.","ex":{"en":"I opposed her marriage to Darryl.","cn":"我反对她嫁给达里尔。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"婚姻生活;已婚状态","en":"Marriage is the state of being married.","ex":{"en":"Marriage might not suit you","cn":"婚姻也许并不适合你。"}}]},"examples":[{"en":"My parents are celebrating 30 years of marriage.","cn":"我的父母亲即将庆祝结婚 30 周年。"},{"en":"Their marriage took place in a local church.","cn":"他们的婚礼是在当地一所教堂里举行的。"}]},"mailing":{"media":{"uk":"media/uk/mailing__gb_1.mp3","us":"media/us/mailing__us_1.mp3"},"oxford":{"phon":"ˈmeɪlɪŋ","pos":"noun","senses":[{"en":"the act of sending items by mail or email","cn":"邮递；邮寄；以电邮发送","g":"[uncountable]","ex":{"en":"The strike has delayed the mailing of tax reminders.","cn":"罢工耽搁了催税单的投寄。"}},{"en":"an item that is sent by mail or email, especially one that is sent to a large number of people","cn":"邮件（尤指成批寄发的）","g":"[countable]","lab":"especially in North American English","ex":{"en":"An order form is included in the mailing.","cn":"随信寄上订单一份。"}}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"邮寄;投寄","en":"Mailing is the activity of sending things to people through the postal service.","ex":{"en":"The newsletter was printed towards the end of June in readiness for mailing","cn":"快到6月底的时候，时事通讯印刷完毕准备投寄。"}},{"pos":"N-COUNT 可数名词","cn":"邮件","en":"A mailing is something that is sent to people through the postal service.","ex":{"en":"The seniors organizations sent out mailings to their constituencies.","cn":"老年人组织向各自的会员寄送了邮件。"}}]},"examples":[{"en":"The strike has delayed the mailing of tax reminders.","cn":"罢工耽搁了催税单的投寄。"},{"en":"An order form is included in the mailing.","cn":"随信寄上订购单一份。"}]},"mate":{"media":{"uk":"media/uk/mate__gb_1.mp3","us":"media/us/mate__us_1.mp3"},"oxford":{"phon":"meɪt","pos":"noun","senses":[{"en":"a friend","cn":"朋友","g":"[countable]","lab":"British English, Australian English, informal，，，，","sc":"friend","ex":{"en":"They've been best mates since school.","cn":"他们从上学时期以来就是最要好的朋友。"}},{"en":"used as a friendly way of addressing somebody, especially between men","cn":"（男人之间常用）哥儿们，伙计，老兄","g":"[countable]","lab":"British English, Australian English, informal，，，，","sc":"friendly name","ex":{"en":"Sorry mate, you'll have to wait.","cn":"对不起，伙计，你得等着。"}},{"en":"a person you share an activity or accommodation with","cn":"同伴；同事；一同居住的人","g":"[countable]","sc":"somebody you share with","ex":{"en":"workmates/teammates/playmates/classmates","cn":"工友；队友；游戏伙伴；同学"}},{"en":"the sexual partner of a bird or animal","cn":"偶；伴侣","g":"[countable]","sc":"bird/animal","ex":{"en":"A male bird sings to attract a mate.","cn":"雄鸟鸣唱以吸引雌鸟。"}},{"en":"a husband, wife or other sexual partner","cn":"配偶；性伴侣","g":"[countable]","lab":"informal","sc":"sexual partner","ex":{"en":"Many matchmaking sites compile lists of potential mates using basic information.","cn":"许多婚介网站会利用基本信息编制潜在婚配对象名单。"}},{"en":"a person whose job is to help a worker who has had training in a skill","cn":"（熟练工人的）助手，帮手","g":"[countable]","lab":"British English","sc":"job","ex":{"en":"a builder’s/plumber’s mate","cn":"建筑工的／管子工的助手"}},{"en":"an officer in a commercial ship below the rank of captain or master","cn":"（商船的）大副","g":"[countable]","sc":"on ship"},{"en":"a position in which one player cannot prevent their king (= the most important piece) being captured and therefore loses the game","cn":"将死；输棋","g":"[uncountable]","sc":"in chess"},{"en":"a situation in which somebody has been completely defeated","cn":"败局；败北；彻底战败","g":"[uncountable]","sc":"in chess"},{"en":"to have sex in order to produce young","cn":"交配；交尾","g":"[intransitive]","sc":"animals/birds","ex":{"en":"Do foxes ever mate with dogs?","cn":"狐狸会和狗交配吗？"},"pos":"verb"},{"en":"to put animals or birds together so that they will have sex and produce young","cn":"使交配","g":"[transitive]","sc":"animals/birds","pos":"verb"},{"en":"to put your opponent in a position in which they cannot prevent their king (= the most important piece) being captured and therefore lose the game","cn":"队友：将对手置于无法阻止其国王被捕获并因此输掉比赛的位置","g":"[transitive]","sc":"in chess","pos":"verb"},{"en":"to defeat somebody completely","cn":"彻底打败；击溃","g":"[transitive]","sc":"in chess","pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"伙伴，朋友(尤指男性之间)","en":"You can refer to someone's friends as their mates, especially when you are talking about a man and his male friends.","ex":{"en":"He's off drinking with his mates","cn":"他跟哥儿们出去喝酒了。"}},{"pos":"N-VOC 称呼名词","cn":"(用于男性之间的称呼)老兄，老弟","en":"Some men use mate as a way of addressing other men when they are talking to them.","ex":{"en":"Come on mate, things aren't that bad.","cn":"别灰心，兄弟，事情没那么糟。"}},{"pos":"N-COUNT 可数名词","cn":"配偶;性伙伴","en":"Someone's wife, husband, or sexual partner can be referred to as their mate .","ex":{"en":"He has found his ideal mate.","cn":"他找到了理想的伴侣。"}},{"pos":"N-COUNT 可数名词","cn":"(动物的)配偶，交配对象","en":"An animal's mate is its sexual partner.","ex":{"en":"The males guard their mates zealously.","cn":"雄性动物死死地守护着他们的配偶。"}},{"pos":"V-RECIP 相互动词","cn":"交配;交尾","en":"When animals mate, a male and a female have sex in order to produce young.","ex":{"en":"This allows the pair to mate properly and stops the hen staying in the nest-box","cn":"这样可以使这对公鸡和母鸡正常交配，让母鸡不再呆在鸡窝里。"}},{"pos":"N-COUNT 可数名词","cn":"(商船上的)大副；（亦指）船员","en":"On a commercial ship, the mate or the first mate is the most important officer except for the captain. Officers of lower rank are also called mates .","ex":{"en":"...the mate of a fishing trawler.","cn":"拖网渔船上的大副"}},{"pos":"N-COUNT 可数名词","cn":"(美国海军的)军士","en":"In the United States Navy, a mate is a petty officer who has a particular set of skills and who assists a warrant officer."},{"pos":"N-UNCOUNT 不可数名词","cn":"(象棋中) 同 checkmate","en":"In chess, mate is the same as checkmate ."}]},"examples":[{"en":"They've been best mates since school.","cn":"他们从上学时期以来就是最要好的朋友。"},{"en":"Sorry mate, you'll have to wait.","cn":"对不起，伙计，你得等着。"}]},"magnificence":{"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"used to describe something that looks, feels, sounds etc so good that it gives you a lot of pleasure","cn":""},{"en":"used when saying that something looks, feels, or sounds very nice","cn":""}]},"examples":[{"en":"The twelve-mile coastline has magnificent scenery.","cn":"","src":"ld"},{"en":"She looked magnificent in a long red dress.","cn":"","src":"ld"}],"media":{"uk":"media/uk/magnificence__gb_1.mp3","us":"media/us/magnificence__us_1.mp3"},"oxford":{"phon":"mæɡˈnɪfɪsns","pos":"noun","senses":[{"en":"the quality of being extremely attractive and impressive","cn":"极具吸引力和令人印象深刻的品质","ex":{"en":"the magnificence of the scenery","cn":"景色的壮美"}}]}},"marketplace":{"media":{"uk":"media/uk/marketplace__gb_1.mp3","us":"media/us/marketplace__us_1.mp3"},"oxford":{"phon":"ˈmɑːkɪtpleɪs","pos":"noun","senses":[{"en":"the activity of competing with other companies to buy and sell goods, services, etc.","cn":"市场竞争","g":"[singular]","ex":{"en":"Companies must be able to survive in the marketplace.","cn":"公司必须有能力在市场竞争中生存下去。"}},{"en":"an open area in a town where a market is held","cn":"集市；市场","g":"[countable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"买卖;市场交易;商业(活动)","en":"The marketplace refers to the activity of buying and selling products.","ex":{"en":"It's our hope that we will play an increasingly greater role in the marketplace and, therefore, supply more jobs.","cn":"我们希望在市场中扮演越来越重要的角色，从而提供更多的就业机会。"}},{"pos":"N-COUNT 可数名词","cn":"集市;市场;(常指)露天市场","en":"A marketplace is a small area in a town or city where goods are bought and sold, often outdoors.","ex":{"en":"The marketplace was jammed with a noisy crowd of buyers and sellers.","cn":"集市上熙熙攘攘挤满了买卖东西的人。"}}]},"examples":[{"en":"Companies must be able to survive in the marketplace.","cn":"公司必须有能力在市场竞争中生存下去。"},{"en":"the education marketplace","cn":"教育市场"}]},"maker":{"media":{"uk":"media/uk/maker__gb_1.mp3","us":"media/us/maker__us_1.mp3"},"oxford":{"phon":"ˈmeɪkə(r)","pos":"noun","senses":[{"en":"a person, company or piece of equipment that makes or produces something","cn":"生产者；制造者；制定者","g":"[countable]","ex":{"en":"a decision/law/policy maker","cn":"作出决定／制定法律／制定政策的人"}},{"en":"God","cn":"造物主；上帝","g":"[singular]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"生产商;制造商","en":"The maker of a product is the firm that manufactures it.","ex":{"en":"...Japan's two largest car makers.","cn":"日本最大的两家汽车制造商"}},{"pos":"N-COUNT 可数名词","cn":"制造者;制作人","en":"You can refer to the person who makes something as its maker .","ex":{"en":"...the makers of news and current affairs programmes.","cn":"新闻和时事节目制作人"}}]},"examples":[{"en":"a new film/movie from the makers of ‘Terminator’","cn":"由《终结者》的制作班子制作的一部新电影"},{"en":"If it doesn't work, send it back to the maker.","cn":"如果不管用，就把它退还给制造厂家。"}]},"magnet":{"media":{"img":["media/pic/laboratory_equipment_comp.jpg","media/thumb/magnet.jpg"],"uk":"media/uk/magnet__gb_1.mp3","us":"media/us/magnet__us_1.mp3"},"oxford":{"phon":"ˈmæɡnət","pos":"noun","senses":[{"en":"a piece of iron that attracts objects made of iron towards it, either naturally or because of an electric current that is passed through it","cn":"磁铁；磁石；吸铁石"},{"en":"a person, place or thing that somebody/something is attracted to","cn":"有吸引力的人（或地方、事物）","g":"[usually singular]","ex":{"en":"In the 1990s the area became a magnet for new investment.","cn":"这个地区在 20 世纪 90 年代成了新的投资热点。"}},{"en":"an object with a magnetic surface that you can stick onto a metal surface","cn":"磁体；磁性物体","ex":{"en":"fridge magnets of your favourite cartoon characters","cn":"你最喜欢的动画人物冰箱贴"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"有吸引力的事物","en":"If you say that something is a magnet or is like a magnet, you mean that people are very attracted by it and want to go to it or look at it.","ex":{"en":"Prospect Park, with its vast lake, is a magnet for all health freaks","cn":"拥有一大片湖区的普罗斯佩克特公园吸引着所有注重健康的人。"}},{"pos":"N-COUNT 可数名词","cn":"磁铁;磁体","en":"A magnet is a piece of iron or other material which attracts iron towards it.","ex":{"en":"...a fridge magnet.","cn":"冰箱磁铁"}}]},"examples":[{"en":"In the 1990s the area became a magnet for new investment.","cn":"这个地区在 20 世纪 90 年代成了新的投资热点。"},{"en":"fridge magnets of your favourite cartoon characters","cn":"可吸附于冰箱表面的你最喜欢的动画人物磁体"}]},"major":{"media":{"uk":"media/uk/major__gb_1.mp3","us":"media/us/major__us_1.mp3"},"oxford":{"phon":"ˈmeɪdʒə(r)","pos":"adjective","senses":[{"en":"very large or important","cn":"主要的；重要的；大的","g":"[usually before noun]","ex":{"en":"a major road","cn":"一条大马路"}},{"en":"serious","cn":"严重","g":"[not before noun]","ex":{"en":"Never mind—it's not major.","cn":"别担心，这不严重。"}},{"en":"based on a scale (= a series of eight notes) in which the third note is two whole tones / steps higher than the first note","cn":"大调的","lab":"music","ex":{"en":"the key of D major","cn":"D 大调"}},{"en":"related to somebody’s main subject of study in college","cn":"（课程）主修的","lab":"North American English"},{"en":"an officer of fairly high rank in the army or the US air force","cn":"少校","g":"[countable]","ex":{"en":"Major Smith","cn":"史密斯少校"},"pos":"noun"},{"en":"the main subject or course of a student at college or university","cn":"主修课程；专业","g":"[countable]","lab":"North American English","ex":{"en":"Her major is French.","cn":"她的专业是法语。"},"pos":"noun"},{"en":"a student studying a particular subject as the main part of their course","cn":"主修学生；主修生","g":"[countable]","lab":"North American English","ex":{"en":"She's a French major.","cn":"她是法语专业的学生。"},"pos":"noun"},{"en":"a major organization or competition","cn":"主要机构；重要比赛","ex":{"en":"The output of the big five oil majors has fallen in recent years.","cn":"近年来，五大石油巨头的产量都下降了。"},"pos":"noun"},{"en":"the major leagues","cn":"大联盟","g":"[plural]","lab":"North American English, sport，，","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"较重要的;较重大的;主要的","en":"You use major when you want to describe something that is more important, serious, or significant than other things in a group or situation.","ex":{"en":"The major factor in the decision to stay or to leave was usually professional","cn":"职业上的考虑往往是决定去留的主要因素。"}},{"pos":"N-COUNT; N-TITLE; N-VOC可数名词；头衔名词；称呼名词","cn":"(英国)陆军(或海军陆战队)少校;(美国)陆军(或空军、海军陆战队)少校","en":"A major is an officer who is one rank above captain in the British army or the United States army, air force, or marines.","ex":{"en":"I was a major in the war, you know.","cn":"你知道，战争期间我是一名陆军少校。"}},{"pos":"N-COUNT 可数名词","cn":"(美国大学中的)主修课程，专业","en":"At a university or college in the United States, a student's major is the main subject that they are studying.","ex":{"en":"English majors would be asked to explore the roots of language.","cn":"英语专业的学生会被要求探究语言的根源。"}},{"pos":"N-COUNT 可数名词","cn":"(美国大学中)主修…的学生，…专业的学生","en":"At a university or college in the United States, if a student is, for example, a geology major, geology is the main subject they are studying.","ex":{"en":"She was named the outstanding undergraduate history major at the University of Oklahoma.","cn":"她被评选为俄克拉何马大学历史专业的优等生。"}},{"pos":"VERB 动词","cn":"(在美国大学)主修，专攻","en":"If a student at a university or college in the United States majors in a particular subject, that subject is the main one they study.","ex":{"en":"He majored in finance at Claremont Men's College in California.","cn":"他在加利福尼亚州的克莱尔蒙特男子学院主修金融专业。"}},{"pos":"ADJ 形容词","cn":"(音乐)大调的，大音阶的","en":"In music, a major scale is one in which the third note is two tones higher than the first.","ex":{"en":"...Mozart's Symphony No 35 in D Major.","cn":"莫扎特D大调第35号交响曲"}},{"pos":"N-COUNT 可数名词","cn":"大型公司;重要企业","en":"A major is a large or important company.","ex":{"en":"Oil majors need not fear being unable to sell their crude.","cn":"大型石油公司无需担心原油销售不出去。"}},{"pos":"N-PLURAL 复数名词","cn":"职业体育总会;(尤指美国)职业棒球联合总会，职业棒球大联盟","en":"The majors are groups of professional sports teams that compete against each other, especially in American baseball.","ex":{"en":"I knew what I could do in the minor leagues, I just wanted a chance to prove myself in the majors.","cn":"我知道自己在职业棒球小联合会中实力如何，我只是想有个机会能在职业棒球大联盟中证明一下自己。"}},{"pos":"N-COUNT 可数名词","cn":"大型体育比赛;(尤指高尔夫球或网球)大赛","en":"A major is an important sporting competition, especially in golf or tennis.","ex":{"en":"Sarazen became the first golfer to win all four majors.","cn":"萨拉岑成为了首位高尔夫四大满贯赛冠军。"}}]},"examples":[{"en":"There were calls for major changes to the welfare system.","cn":"有人要求对福利制度进行重大改革。"},{"en":"She's a French major.","cn":"她是法语专业的学生。"}]},"mats":{"oxford":{"phon":"mæt","pos":"noun","senses":[{"en":"a small piece of thick carpet or strong material that is used to cover part of a floor","cn":"小地毯；垫子"},{"en":"a piece of thick material such as rubber or plastic used especially in some sports for people to lie on or fall onto （","cn":"体育运动用的）厚垫子"}]}},"mattered":{"oxford":{"phon":"ˈmætə(r)","pos":"noun","senses":[{"en":"a subject or situation that you must consider or deal with","cn":"课题；事情；问题"},{"en":"the present situation, or the situation that you are talking about","cn":"事态；当前的状况"}]}},"manners":{"oxford":{"phon":"ˈmænə(r)","pos":"noun","senses":[{"en":"( formal ) the way that sth is done or happens","cn":"方式；方法"},{"en":"the way that sb behaves towards other people","cn":"举止；行为方式"}]}},"manufactured":{"oxford":{"phon":"ˌmænjuˈfæktʃə(r)","pos":"verb","senses":[{"en":"to make goods in large quantities, using machinery （","cn":"用机器）大量生产，成批制造"},{"en":"to invent a story, an excuse, etc.","cn":"编造；捏造"}]}},"marriages":{"oxford":{"phon":"ˈmærɪdʒ","pos":"noun","senses":[{"en":"the legal relationship between a husband and wife","cn":"结婚；婚姻"},{"en":"the state of being married","cn":"婚姻生活；已婚状态"}]}},"makes":{"oxford":{"phon":"meɪk","pos":"verb","senses":[{"en":"to create or prepare sth by combining materials or putting parts together","cn":"制造；做；组装"},{"en":"to write, create or prepare sth","cn":"写；出产；制订"}]}},"makers":{"oxford":{"phon":"ˈmeɪkə(r)","pos":"noun","senses":[{"en":"( often in compounds","cn":"常构成复合词 ) a person, company, or piece of equipment that makes or produces sth 生产者；制造者；制订者"},{"en":"God","cn":"上帝"}]}},"marvelous":{"oxford":{"phon":"ˈmɑːvələs","pos":"adj.","senses":[{"en":"extremely good; wonderful","cn":"极好的；非凡的"}]}},"managers":{"oxford":{"phon":"ˈmænɪdʒə(r)","pos":"noun","senses":[{"en":"a person who is in charge of running a business, a shop/store or a similar organization or part of one （","cn":"企业、店铺等的）经理，经营者，老板"},{"en":"a person who deals with the business affairs of an actor, a musician, etc. （","cn":"演员、音乐家等的）经理人，个人经理"}]}},"marching":{"oxford":{"phon":"mɑːtʃ","pos":"verb","senses":[{"en":"to walk with stiff regular steps like a soldier","cn":"齐步走；行进"},{"en":"to walk somewhere quickly in a determined way （","cn":"坚定地向某地）前进，进发"}]}},"materials":{"oxford":{"phon":"məˈtɪəriəl","pos":"noun","senses":[{"en":"cloth used for making clothes, curtains, etc.","cn":"布料"},{"en":"a substance that things can be made from","cn":"材料；原料"}]}},"majors":{"oxford":{"phon":"ˈmeɪdʒə(r)","pos":"adjective","senses":[{"en":"very large or important","cn":"主要的；重要的；大的"},{"en":"( NAmE ) serious","cn":"严重"}]}},"matters":{"oxford":{"phon":"ˈmætə(r)","pos":"noun","senses":[{"en":"a subject or situation that you must consider or deal with","cn":"课题；事情；问题"},{"en":"the present situation, or the situation that you are talking about","cn":"事态；当前的状况"}]}},"marched":{"oxford":{"phon":"mɑːtʃ","pos":"verb","senses":[{"en":"to walk with stiff regular steps like a soldier","cn":"齐步走；行进"},{"en":"to walk somewhere quickly in a determined way （","cn":"坚定地向某地）前进，进发"}]}},"maintaining":{"oxford":{"phon":"meɪnˈteɪn","pos":"verb","senses":[{"en":"to make sth continue at the same level, standard, etc.","cn":"维持；保持"},{"en":"to keep a building, a machine, etc. in good condition by checking or repairing it regularly","cn":"维修；保养"}]}},"males":{"oxford":{"phon":"meɪl","pos":"adjective","senses":[{"en":"belonging to the sex that does not give birth to babies; connected with this sex","cn":"男性的；雄性的；男的"},{"en":"producing pollen","cn":"雄性的"}]}},"markets":{"oxford":{"phon":"ˈmɑːkɪt","pos":"noun","senses":[{"en":"an occasion when people buy and sell goods; the open area or building where they meet to do this","cn":"集市；市场；商场"},{"en":"business or trade, or the amount of trade in a particular type of goods","cn":"交易；买卖；交易量"}]}},"masters":{"oxford":{"phon":"ˈmɑːstə(r)","pos":"noun","senses":[{"en":"( old-fashioned ) a man who has people working for him, often as servants in his home （","cn":"男）主人，雇主"},{"en":"a person who is able to control sth","cn":"主宰；主人；有控制力的人"}]}},"matchsticks":{"oxford":{"phon":"ˈmætʃstɪk","pos":"noun","senses":[{"en":"a single wooden match","cn":"火柴杆；火柴棍"}]}},"mayors":{"oxford":{"phon":"meə(r)","pos":"noun","senses":[{"en":"(in England, Wales and Northern Ireland) the head of a town, borough or county council, chosen by other members of the council to represent them at official ceremonies, etc. （","cn":"英格兰、威尔士和北爱尔兰由议员选举产生的）镇长，市长，郡长"},{"en":"the head of the government of a town or city, etc., elected by the public （","cn":"民选的）市长，镇长"}]}},"manufacturers":{"oxford":{"phon":"ˌmænjuˈfæktʃərə(r)","pos":"noun","senses":[{"en":"a person or company that produces goods in large quantities","cn":"生产者；制造者；生产商"}]}},"martin":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"燕科小鸟","en":"A martin is a small bird with a forked tail."}]},"media":{"uk":"media/ldoce/hwd/bre/d/martin0205.mp3","us":"media/ldoce/hwd/ame/d/marten.mp3"},"oxford":{"phon":"ˈmɑːtɪn","pos":"","senses":[{"en":"a first name for boys","cn":"马丁（男子名）"}]}},"materialized":{"oxford":{"phon":"məˈtɪəriəlaɪz","pos":"verb","senses":[{"en":"( usually used in negative sentences","cn":"通常用于否定句 ) to take place or start to exist as expected or planned 实现；发生；成为现实"},{"en":"to appear suddenly and/or in a way that cannot be explained","cn":"突然显现；奇怪地出现"}]}},"magazines":{"oxford":{"phon":"ˌmæɡəˈziːn","pos":"noun","senses":[{"en":"a type of large thin book with a paper cover that you can buy every week or month, containing articles, photographs, etc., often on a particular topic","cn":"杂志；期刊"},{"en":"a radio or television programme that is about a particular topic （","cn":"电视、广播）专题节目"}]}},"matched":{"oxford":{"phon":"mætʃ","pos":"noun","senses":[{"en":"a small stick made of wood or cardboard that is used for lighting a fire, cigarette, etc.","cn":"火柴"},{"en":"( especially BrE ) a sports event where people or teams compete against each other","cn":"比赛；竞赛"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"相配的;相称的","en":"If you say that two people are well matched, you mean that they have qualities that will enable them to have a good relationship.","ex":{"en":"They were well matched, I thought","cn":"我认为他们十分般配。"}},{"pos":"ADJ 形容词","cn":"(体育等竞赛中)不相上下的,势均力敌的","en":"In sports and other competitions, if the two opponents or teams are well matched, they are both of the same standard in strength or ability.","ex":{"en":"Two well-matched sides conjured up an entertaining game","cn":"双方势均力敌，奉献了一场精彩的比赛。"}}]}},"malls":{"oxford":{"phon":"mɔːl","pos":"noun","senses":[{"en":"( both especially NAmE ) a large building or covered area that has many shops/stores, restaurants, etc. inside it","cn":"购物商场；购物广场"}]}},"mattresses":{"oxford":{"phon":"ˈmætrəs","pos":"noun","senses":[{"en":"the soft part of a bed, that you lie on","cn":"床垫"}]}},"mails":{"oxford":{"phon":"meɪl","pos":"noun","senses":[{"en":"the official system used for sending and delivering letters, packages, etc.","cn":"邮政；邮递系统"},{"en":"letters, packages, etc. that are sent and delivered","cn":"邮件；信件；邮包"}]}},"maintained":{"oxford":{"phon":"meɪnˈteɪn","pos":"verb","senses":[{"en":"to make sth continue at the same level, standard, etc.","cn":"维持；保持"},{"en":"to keep a building, a machine, etc. in good condition by checking or repairing it regularly","cn":"维修；保养"}]}},"machines":{"oxford":{"phon":"məˈʃiːn","pos":"noun","senses":[{"en":"( often in compounds","cn":"常构成复合词 ) a piece of equipment with moving parts that is designed to do a particular job. The power used to work a machin"},{"en":"( informal ) a particular machine, for example in the home, when you do not refer to it by its full name （","cn":"不提全称时的简略说法）机器"}]}},"mathematician":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"数学家","en":"A mathematician is a person who is trained in the study of numbers and calculations.","ex":{"en":"The risks can be so complex that banks hire mathematicians to puzzle them out.","cn":"由于风险过高，银行便聘请数学家来解决这些问题。"}},{"pos":"N-COUNT 可数名词","cn":"善于计算的人;有数学头脑的人","en":"A mathematician is a person who is good at doing calculations and using numbers.","ex":{"en":"I'm not a very good mathematician.","cn":"我不太擅长计算。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who studies or teaches mathematics, or is a specialist in mathematics","cn":"数学家﹔数学教师"}]},"vocab":{"pos":"n","senses":[{"en":"Use the noun mathematician when you talk about someone who is highly educated in — and good at — math. Your math teacher might be a great mathematician who's also gifted at explaining math to students."}]},"collocations":{"phrases":["ADJ. brilliant | distinguished, great one of the greatest mathematicians of all time | applied, pure"]},"media":{"uk":"media/ldoce/hwd/bre/9/mathematician0205.mp3","us":"media/ldoce/hwd/ame/0/mathematician.mp3"},"oxford":{"phon":"ˌmæθəməˈtɪʃn","pos":"noun","senses":[{"en":"a person who is an expert in mathematics","cn":"数学家","ex":{"en":"one of the greatest mathematicians of all time","cn":"有史以来最伟大的数学家之一"}}]}},"maine":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a state in the northeast of the US, next to the Atlantic coast and the border with Canada. Maine is the largest state in new england , and is known for its beautiful forests, mountains, and coast.","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/4/p028-000007812.mp3","us":"media/ldoce/hwd/ame/e/main1.mp3"},"oxford":{"phon":"meɪn","pos":"","senses":[{"en":"the most northerly of the New England states in the US. Its popular name is the Pine Tree State, and people from Maine are called Down Easters. The capital city is Augusta and the largest city is Portland. Maine was separated from Massachusetts in 1820 as a free state under the Missouri Compromise. It is a popular area for outdoor holidays and sports, and the northern end of the Appalachian Trail is in Maine. Maine's products include paper, apples, blueberries and canned sardines (= small fish).","cn":"缅因（美国新英格兰诸州中最北部的州，首府奥古斯塔，最大城市波特兰）"}]}},"manuscript":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"手稿;原稿","en":"A manuscript is a handwritten or typed document, especially a writer's first version of a book before it is published.","ex":{"en":"He had seen a manuscript of the book","cn":"他见过这本书的手稿。"}},{"pos":"N-COUNT 可数名词","cn":"(未发明印刷术之前的)手抄本，手写本","en":"A manuscript is an old document that was written by hand before printing was invented.","ex":{"en":"...early printed books and rare manuscripts.","cn":"早期的印刷书籍与手抄珍本"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"writing, especially a small amount of writing","cn":""},{"en":"the written part of a book, newspaper etc, not including notes, pictures etc","cn":""},{"en":"a copy of a book which is written by hand or typed, often before it is printed","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A manuscript is a handwritten work. It's still a manuscript if it's typed — if a publisher asks for your manuscript , don't send her something scrawled on notebook paper!"}]},"collocations":{"phrases":["ADJ. original | autograph, handwritten the original autograph manuscript of the poem | unpublished | unfinished | literary, music/musical","QUANT. copy I only have one copy of the manuscript.","VERB + MANUSCRIPT write | type | edit, revise | submit (for publication) He submitted the manuscript to an editor at Longman. | accept/rejec","PREP. in ~ Her autobiography remained in manuscript (= was not published) . 2 very old book/document, written by hand","ADJ. ancient, early, medieval | contemporary One contemporary manuscript shows Henry II crowned by the hand of Christ. | rare | surviving th","MANUSCRIPT + VERB survive earlier manuscripts which no longer survive"]},"media":{"uk":"media/ldoce/hwd/bre/1/manuscript0205.mp3","us":"media/ldoce/hwd/ame/4/manuscript.mp3"},"examples":[{"en":"I read her poems in manuscript.","cn":"我读过她的诗作的手稿。"},{"en":"an unpublished/original manuscript","cn":"未经发表的/原始的手稿"}],"oxford":{"phon":"ˈmænjuskrɪpt","pos":"noun","senses":[{"en":"a copy of a book, piece of music, etc. before it has been printed","cn":"手稿；原稿","ex":{"en":"an unpublished/original manuscript","cn":"未经发表的／原始的手稿"}},{"en":"a very old book or document that was written by hand before printing was invented","cn":"（印刷术发明以前书籍或文献的）手写本，手抄本","ex":{"en":"medieval illuminated manuscripts","cn":"中世纪装饰精美的手抄本"}}]}},"margarine":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"人造黄油;麦淇淋","en":"Margarine is a yellow substance made from vegetable oil and animal fats that is similar to butter. You spread it on bread or use it for cooking."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a yellow substance similar to butter but made from vegetable or animal fats, which you eat with bread or use for cooking","cn":"麦淇淋﹐人造黄油"}]},"collocations":{"phrases":["ADJ. hard | soft | low-fat, polyunsaturated a tub of low-fat margarine | sunflower, vegetable","QUANT. tub","VERB + MARGARINE put on, spread (sth with) She put some margarine on her roll. Spread some margarine on the toast, please. | heat, melt, sof"]},"media":{"uk":"media/ldoce/hwd/bre/8/margarine0205.mp3","us":"media/ldoce/hwd/ame/8/margarine.mp3"},"oxford":{"phon":"ˌmɑːdʒəˈriːn","pos":"noun","senses":[{"en":"a yellow substance like butter made from animal or vegetable fats, used in cooking or spread on bread, etc.","cn":"人造黄油；人造奶油","ex":{"en":"Cream the margarine and sugar together.","cn":"把人造黄油和糖一起搅成糊状。"}}]}},"maul":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(动物)袭击，严重伤害","en":"If you are mauled by an animal, you are violently attacked by it and badly injured.","ex":{"en":"He had been mauled by a bear","cn":"他被熊袭击过。"}},{"pos":"VERB 动词","cn":"猛烈攻击;抨击;重创","en":"If someone is mauled, they are attacked aggressively, and often harmed in some way.","ex":{"en":"The troops were severely mauled and lost a quarter of their strength before evacuating the island","cn":"部队遭到重创，从岛上撤退前损失了四分之一的兵力。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"if an animal mauls someone, it injures them badly by tearing their flesh 〔","cn":"动物〕袭击﹐撕咬"},{"en":"to strongly criticize something, especially a new book, play etc","cn":"抨击〔尤对新书﹑新戏剧等〕"},{"en":"to touch someone in a rough sexual way which they think is unpleasant","cn":"对〔某人〕粗野地动手动脚"}]},"vocab":{"pos":"v n","senses":[{"en":"Maul is both the name of a heavy hammer, and also a verb meaning beating and scratching. Tigers, lions, bears––animals with powerful paws and sharp claws, will maul their victims."}]},"collocations":{"phrases":["ADV. badly, severely She was badly mauled by a lion."]},"media":{"uk":"media/ldoce/hwd/bre/a/mall0205.mp3","us":"media/ldoce/hwd/ame/0/mall.mp3"},"examples":[{"en":"They face a mauling by last year's winners.","cn":"他们面临去年的优胜者的严重威胁。"},{"en":"The play received a mauling from the critics.","cn":"这出戏受到了剧评人无情的抨击。"}],"oxford":{"phon":"mɔːl","pos":"verb","senses":[{"en":"to attack and injure somebody by tearing their body","cn":"袭击；撕咬"},{"en":"to touch somebody/something in an unpleasant and/or violent way","cn":"粗手粗脚地摆弄；粗暴地对待","ex":{"en":"She was mauled by guards at the border.","cn":"她在边境被警卫殴打。"}},{"en":"to criticize something/somebody severely and publicly","cn":"狠狠地批评；猛烈抨击"},{"en":"to defeat somebody easily","cn":"轻易击败；轻取","lab":"informal"}]}},"manslaughter":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"过失杀人;非预谋杀人罪","en":"Manslaughter is the illegal killing of a person by someone who did not intend to kill them.","ex":{"en":"A judge accepted her plea that she was guilty of manslaughter, not murder.","cn":"她申诉说自己并非蓄意谋杀，而是过失杀人，法官接受了她的申诉。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the act or crime of deliberately killing someone","cn":""},{"en":"the crime of killing someone, especially deliberately - used especially in American legal contexts","cn":""},{"en":"the crime of killing someone by accident, or while you are trying to defend yourself","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Manslaughter means killing someone without planning it beforehand. A defendant who's convicted of manslaughter is guilty of a serious crime, though less serious than murder."}]},"collocations":{"phrases":["ADJ. attempted | involuntary | reckless | corporate The directors of the railway company could be charged with corporate manslaughter. • Not"]},"media":{"uk":"media/ldoce/hwd/bre/e/manslaughter0205.mp3","us":"media/ldoce/hwd/ame/2/manslaughter.mp3"},"examples":[{"en":"She was cleared of murder but found guilty of manslaughter.","cn":"她洗脱了谋杀的罪名﹐但被判过失杀人。"}],"oxford":{"phon":"ˈmænslɔːtə(r)","pos":"noun","senses":[{"en":"the crime of killing somebody illegally in circumstances that make it a less serious crime than murder (for example because it was not deliberate or not planned in advance)","cn":"过失杀人","ex":{"en":"The charge has been reduced to manslaughter.","cn":"指控已减轻为过失杀人。"}}]}},"manoeuvre":{"collins":{"senses":[{"pos":"VERB 动词","cn":"(熟练地)移动，调动，转动，操纵","en":"If you manoeuvre something into or out of an awkward position, you skilfully move it there.","ex":{"en":"We attempted to manoeuvre the canoe closer to him","cn":"我们试图让独木舟靠他更近一些。"}},{"pos":"VERB 动词","cn":"操纵;控制;耍花招","en":"If you manoeuvre a situation, you change it in a clever and skilful way so that you can benefit from it.","ex":{"en":"The authorities have to manoeuvre the markets into demanding a cut in interest rates","cn":"当局不得不干预市场，迫其提出削减利率的要求。"}},{"pos":"N-PLURAL 复数名词","cn":"军事演习","en":"Military manoeuvres are training exercises which involve the movement of soldiers and equipment over a large area.","ex":{"en":"Allied troops begin maneuvers tomorrow to show how quickly forces could be mobilized in case of a new invasion","cn":"盟军明日演习，来展示一旦发生新的入侵，其集结速度之快。"}},{"pos":"","cn":"","en":"room for manoeuvre→see: ;"}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a skilful or careful movement that you make, for example in order to avoid something or go through a narrow space","cn":"熟练[谨慎]的动作"},{"en":"a skilful or carefully planned action intended to gain an advantage for yourself","cn":"策略﹐巧计﹐花招"},{"en":"military activities, such as pretending to fight a battle, which are done as practice or training","cn":"军事演习"}]},"collocations":{"phrases":["ADV. carefully | easily | expertly, skilfully","VERB + MANOEUVRE be difficult to, be easy to","PREP. around, past, through, etc. He skilfully manoeuvred the motor boat past the rocks.","PHRASES manoeuvre (sth) into position, manoeuvre your way (figurative) He had manoevred his way into a position of strength in the party. | "]},"media":{"uk":"media/ldoce/hwd/bre/d/maneuver0205.mp3","us":"media/ldoce/hwd/ame/b/maneuver1.mp3"},"examples":[{"en":"You will be asked to perform some standard manoeuvres during your driving test.","cn":"驾驶考试中会要求你做几个标准的机动动作。"},{"en":"She manoeuvred her way to the top of the company.","cn":"她施展手腕使自己进入了公司最高领导层。"}],"oxford":{"phon":"məˈnuːvə(r)","pos":"noun","senses":[{"en":"a movement performed with care and skill","cn":"细致巧妙的移动；机动动作","g":"[countable]","ex":{"en":"a complicated/skilful manoeuvre","cn":"复杂的／熟练的移动"}},{"en":"a clever plan, action or movement that is used to give somebody an advantage","cn":"策略；手段；花招；伎俩","g":"[countable, uncountable]","ex":{"en":"diplomatic manoeuvres","cn":"外交策略"}},{"en":"military exercises involving a large number of soldiers, ships, etc.","cn":"军事演习；作战演习","g":"[plural]","ex":{"en":"The army is on manoeuvres in the desert.","cn":"军队在沙漠中进行军事演习。"}},{"en":"to move or turn with skill or care; to move or turn something with skill or care","cn":"（使灵巧或谨慎地）移动，转动","g":"[intransitive, transitive]","ex":{"en":"The yachts manoeuvred for position.","cn":"那些游艇灵活地寻找位置。"},"pos":"verb"},{"en":"to control or influence a situation in a way that shows skill but is sometimes dishonest","cn":"操纵；控制；使花招","g":"[intransitive, transitive]","ex":{"en":"The new laws have left us little room to manoeuvre (= not much opportunity to change or influence a situation).","cn":"新法律没给我们留下多少回旋的余地。"},"pos":"verb"}]}},"mammal":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"哺乳动物","en":"Mammals are animals such as humans, dogs, lions, and whales. In general, female mammals give birth to babies rather than laying eggs, and feed their young with milk."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a living thing such as a dog, cow, or tiger, but not an insect, fish, or bird","cn":""},{"en":"an animal – used especially when describing a particular animal’s characteristics or when referring to animals generally","cn":""},{"en":"an animal, especially a large or dangerous one","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"What do you have in common with your hamster, a whale, a bat, a giraffe, and the kid who packs your groceries? Every one is a mammal — a hairy, warm-blooded, milk-drinking vertebrate, just like you."}]},"collocations":{"phrases":["ADJ. large, small | higher, lower | common | endangered, rare | wild | aquatic, marine, sea | land, terrestrial | carnivorous, grazing, herb","MAMMAL + NOUN species | prey","PREP. among ~s deaths among marine mammals"]},"media":{"uk":"media/ldoce/hwd/bre/1/mammal0205.mp3","us":"media/ldoce/hwd/ame/c/mammal.mp3"},"oxford":{"phon":"ˈmæml","pos":"noun","senses":[{"en":"any animal that gives birth to live young, not eggs, and feeds its young on milk. Cows, humans and whales are all mammals.","cn":"哺乳动物","ex":{"en":"deaths among marine mammals","cn":"海洋哺乳动物的死亡"}}]}},"mansion":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"宅邸;大厦","en":"A mansion is a very large house.","ex":{"en":"...an eighteenth century mansion in Hampshire","cn":"汉普郡的一座18世纪的宅邸"}},{"pos":"N-IN-NAMES 名称名词","cn":"（常用于公寓楼的专有名称中）公寓，大厦","en":"Mansions is often used in the names of blocks of flats.","ex":{"en":"...Delaware Mansions, a block of 167 flats opposite the BBC Radio studios.","cn":"特拉华公寓——一座位于英国广播公司电台对面拥有167间套房的公寓楼"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a building that someone lives in, especially one that is intended for one family, person, or couple to live in","cn":""},{"en":"a house that is not joined to another house","cn":""},{"en":"a house that is joined to another house on one side","cn":""}]},"collocations":{"phrases":["ADJ. great, huge, imposing, large | lavish, luxurious, luxury, palatial | fine | country | old | stone | historic | 17th century, 200-year-o","VERB + MANSION live in | build","MANSION + VERB stand The historic mansion stands in 160 acres of parkland.","MANSION + NOUN block, flat, house"]},"media":{"uk":"media/ldoce/hwd/bre/8/mansion0205.mp3","us":"media/ldoce/hwd/ame/a/mansion.mp3"},"examples":[{"en":"an 18th century country mansion * 18","cn":"世纪的乡村宅第"},{"en":"2 Moscow Mansions, Cromwell Road","cn":"克伦威尔路莫斯科公寓 2 号"}],"oxford":{"phon":"ˈmænʃn","pos":"noun","senses":[{"en":"a large, impressive house","cn":"公馆；宅第","g":"[countable]","ex":{"en":"an 18th century country mansion","cn":"18 世纪的乡村宅第"}},{"en":"used in the names of blocks of flats","cn":"（用于公寓楼名）","g":"[plural]","lab":"British English","ex":{"en":"2 Moscow Mansions, Cromwell Road","cn":"克伦威尔路莫斯科公寓 2 号"}}]}},"manure":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"粪肥;肥料","en":"Manure is animal faeces, sometimes mixed with chemicals, that is spread on the ground in order to make plants grow healthy and strong.","ex":{"en":"...bags of manure.","cn":"一袋袋的肥料"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"waste matter from animals that is mixed with soil to improve the soil and help plants grow","cn":"粪肥"}]},"vocab":{"pos":"n v","senses":[{"en":"Gardeners use the word manure to mean a fertilizer made from animal waste. Manure is good for helping plants grow and stay healthy."}]},"collocations":{"phrases":["ADJ. animal, chicken, cow, horse, pig | farmyard, garden | green A green manure is a crop grown mainly to improve soil fertility. | organic ","VERB + MANURE apply, spread the best time to spread manure on the fields | dig in, work in Work in plenty of well-rotted manure.","MANURE + NOUN heap"]},"media":{"uk":"media/ldoce/hwd/bre/6/manure0205.mp3","us":"media/ldoce/hwd/ame/8/manure1.mp3"},"oxford":{"phon":"məˈnjʊə(r)","pos":"noun","senses":[{"en":"the waste matter from animals that is spread over or mixed with the soil to help plants and crops grow","cn":"粪肥；肥料","ex":{"en":"Dig plenty of well-rotted manure into the soil.","cn":"将大量腐熟的粪便挖入土壤中。"}},{"en":"to put manure on or in soil to help plants grow","cn":"给…施肥","pos":"verb"}]}},"maths":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"同 mathematics","en":"Maths is the same as mathematics .","ex":{"en":"He taught science and maths.","cn":"他教科学和数学这两门课。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"mathematics","cn":"数学"}]},"collocations":{"phrases":["ADJ. basic | complicated Working out the quantities of the ingredients involved some complicated maths.","MATHS + NOUN problem The class were struggling to find the solution to a maths problem. • Note at SUBJECT"]},"media":{"uk":"media/ldoce/hwd/bre/1/maths0205.mp3","us":"media/ldoce/hwd/ame/5/ld41maths.mp3"},"examples":[{"en":"If my maths is/are right, the answer is 142.","cn":"如果我计算没错，答案是 142。"},{"en":"The core subjects are English, Maths and Science.","cn":"主课是英语、数学和自然科学。"}],"oxford":{"phon":"mæθs","pos":"noun","senses":[{"en":"mathematics, especially as a subject in school","cn":"数学（尤作为学校课程）","g":"[uncountable]","ex":{"en":"The core subjects are English, maths and science.","cn":"主课是英语、数学和自然科学。"}},{"en":"the process of calculating using numbers","cn":"运算；计算","g":"[uncountable + singular or plural verb]","ex":{"en":"If my maths is/are right, the answer is 142.","cn":"如果我计算没错，答案是 142。"}}]}},"manuel":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"a character in the humorous British television programme fawlty towers . Manuel is a Spanish waiter who does not speak or understand much English, so he is always asking ‘Qué?’, the Spanish word for ‘What?’. People in the UK sometimes say this as a joke when t","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/6/lpd_manuel.mp3","us":"media/ldoce/hwd/ame/6/lpd_manuel.mp3"}},"marshal":{"collins":{"senses":[{"pos":"VERB 动词","cn":"召集;收集;安排;组织","en":"If you marshal people or things, you gather them together and arrange them for a particular purpose.","ex":{"en":"Richard was marshalling the doctors and nurses, showing them where to go.","cn":"理查德正在召集医护人员，向他们说明去哪里。"}},{"pos":"N-COUNT 可数名词","cn":"司仪，典礼官；(尤指体育赛事的)总指挥","en":"A marshal is an official who helps to supervise a public event, especially a sports event.","ex":{"en":"The grand prix is controlled by well-trained marshals","cn":"大奖赛由训练有素的典礼官协调指挥。"}},{"pos":"N-COUNT 可数名词","cn":"(美国等的地方)警察局局长","en":"In the United States and some other countries, a marshal is a police officer, often one who is responsible for a particular area.","ex":{"en":"A federal marshal was killed in a shoot-out.","cn":"枪战中一名联邦警察局局长身亡。"}},{"pos":"N-COUNT 可数名词","cn":"消防队长","en":"A marshal is an officer in a fire department.","ex":{"en":"...a Cleveland county fire marshal.","cn":"克利夫兰县的消防队长"}},{"pos":"N-COUNT; N-TITLE 可数名词；头衔名词","cn":"(英国等的)陆军元帅，空军元帅","en":"In Britain and some other countries, a marshal is an officer who has the highest rank in an army or air force.","ex":{"en":"...Air Chief Marshal Sir Kenneth Cross.","cn":"空军上将肯尼思·克罗斯爵士"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an officer of the highest rank in the army or air force of some countries 〔","cn":"一些国家陆军或空军的〕元帅"},{"en":"an official in charge of an important public event or ceremony","cn":"司礼官﹐典礼官﹐司仪〔主持重要公众活动或典礼的官员〕"},{"en":"a person who controls crowds, traffic etc at a sports event or other public event 〔","cn":"体育竞赛或其他公共活动的〕主事官员"}]},"vocab":{"pos":"n v","senses":[{"en":"A federal marshal knocks on your door. You panic: a marshal is a law officer. What do you do? You marshal your thoughts, that is, put them in order."}]},"media":{"uk":"media/ldoce/hwd/bre/7/marshal_n0205.mp3","us":"media/ldoce/hwd/ame/4/marshal1.mp3"},"examples":[{"en":"They have begun marshalling forces to send relief to the hurricane victims.","cn":"他们已经开始结集队伍将救济物资送给遭受飓风侵害的灾民。"},{"en":"Police were brought in to marshal the crowd.","cn":"警察奉命来维持秩序。"}],"oxford":{"phon":"ˈmɑːʃl","pos":"noun","senses":[{"en":"an officer of the highest rank in the armed forces of some countries","cn":"元帅","ex":{"en":"Field Marshal Lord Haig","cn":"陆军元帅黑格勋爵"}},{"en":"a person responsible for making sure that public events, especially sports events, take place without any problems, and for controlling crowds","cn":"司仪；典礼官"},{"en":"(in the US) an officer whose job is to put court orders into effect","cn":"（美国法院的）执行官","ex":{"en":"a federal marshal","cn":"联邦法庭的执行官"}},{"en":"(in some US cities) an officer of high rank in a police or fire department","cn":"（一些美国城市的）警察局长，消防局长"},{"en":"to gather together and organize the people, things, ideas, etc. that you need for a particular purpose","cn":"结集；收集；安排","ex":{"en":"They have begun marshalling forces to send relief to the hurricane victims.","cn":"他们已经开始结集队伍将救济物资送给遭受飓风侵害的灾民。"},"pos":"verb"},{"en":"to control or organize a large group of people, especially soldiers","cn":"率领；指挥；组织","ex":{"en":"The general marshalled his troops.","cn":"将军指挥部队。"},"pos":"verb"}]}},"maniac":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"疯子;狂人","en":"A maniac is a mad person who is violent and dangerous.","ex":{"en":"The cabin looked as if a maniac had been let loose there.","cn":"小屋看上去像是被疯子在那撒过野一样。"}},{"pos":"ADJ 形容词","cn":"极其愚蠢的;疯狂的","en":"If you describe someone's behaviour as maniac, you are emphasizing that it is extremely foolish and uncontrolled.","ex":{"en":"A maniac driver sped 35 miles along the wrong side of a motorway at 110 mph.","cn":"一个疯狂的司机以每小时110英里的速度在高速公路上逆行飙车35英里。"}},{"pos":"N-COUNT 可数名词","cn":"(宗教或体育的)狂热分子，过激分子","en":"If you call someone, for example, a religious maniac or a sports maniac, you are critical of them because they have such a strong interest in religion or sport.","ex":{"en":"My mum is turning into a religious maniac.","cn":"我妈妈正在变为一个宗教狂热分子。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"someone who behaves in a crazy and often amusing way and who has strange ideas","cn":""},{"en":"someone who behaves in a stupidly dangerous way","cn":""},{"en":"someone who has strange ideas or who behaves in a strange and often frightening way","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"A maniac is a crazy person. Screaming like a maniac is never a good way to get your point across."}]},"collocations":{"phrases":["ADJ. sex | homicidal | religious","PREP. like a ~ He was driving like a maniac."]},"media":{"uk":"media/ldoce/hwd/bre/f/maniac0205.mp3","us":"media/ldoce/hwd/ame/0/maniac.mp3"},"examples":[{"en":"He was driving like a maniac.","cn":"他发了疯似地开车。"},{"en":"a maniac driver/fan/killer","cn":"发了疯的司机；狂热的爱好者；疯狂杀手"}],"oxford":{"phon":"ˈmeɪniæk","pos":"adjective","senses":[{"en":"behaving in an extremely dangerous, violent, wild or crazy way","cn":"躁狂的；疯狂的；狂妄的；狂热的","ex":{"en":"a maniac driver/killer","cn":"极其危险的司机／杀手"}},{"en":"a person who behaves in a dangerous, violent or wild way and who you think is crazy or strange","cn":"行为极其危险（或狂暴、愚蠢）的人；疯子；狂人","lab":"informal, sometimes offensive，，","ex":{"en":"He was driving like a maniac.","cn":"他发了疯似的开车。"},"pos":"noun"},{"en":"a person who has an extremely strong interest in or enthusiasm for something, to an extent that other people think is strange","cn":"狂热分子；过激分子","ex":{"en":"He's a movie maniac.","cn":"他是个电影狂。"},"pos":"noun"},{"en":"a person who has a severe mental illness, especially mania","cn":"躁狂症患者；疯子","lab":"old use, psychology，，","ex":{"en":"the ravings of a maniac","cn":"疯子的胡言乱语"},"pos":"noun"},{"en":"a person suffering from a mental illness of a particular type","cn":"（某方面）精神失常的人","ex":{"en":"a pyromaniac","cn":"纵火狂患者"},"pos":"combining form"}]}},"mandate":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(政府或经选举组建的机构的)授权，委托","en":"If a government or other elected body has a mandate to carry out a particular policy or task, they have the authority to carry it out as a result of winning an election or vote.","ex":{"en":"The President and his supporters are almost certain to read this vote as a mandate for continued economic reform","cn":"总统及其支持者几乎肯定地认为这次投票是对继续进行经济改革的授权。"}},{"pos":"N-COUNT 可数名词","cn":"授权;委托;委任","en":"If someone is given a mandate to carry out a particular policy or task, they are given the official authority to do it.","ex":{"en":"How much longer does the independent prosecutor have a mandate to pursue this investigation?","cn":"独立检察官受命调查这件事还要多长时间？"}},{"pos":"N-COUNT 可数名词","cn":"任期；在任期；统治期","en":"You can refer to the fixed length of time that a country's leader or government remains in office as their mandate .","ex":{"en":"...his intention to leave politics once his mandate ends.","cn":"他关于任期一满就离开政界的打算。"}},{"pos":"VERB 动词","cn":"授权;委任","en":"When someone is mandated to carry out a particular policy or task, they are given the official authority to do it.","ex":{"en":"He'd been mandated by the West African Economic Community to go in and to enforce a ceasefire","cn":"他受西非经济共同体的委托介入并执行停火协定。"}},{"pos":"VERB 动词","cn":"批准;颁布;强制执行","en":"To mandate something means to make it mandatory.","ex":{"en":"The proposed initiative would mandate a reduction of carbon dioxide of 40%","cn":"倡议将强制规定把二氧化碳排放量降低40%。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"if a government or official has a mandate to make important decisions, they have the authority to make the decisions because they have been elected by the people to do so 〔","cn":"政府或官员等经选举而获得的〕授权"},{"en":"an official instruction given to a person or organization, allowing them to do something 〔","cn":"给某人或某机构的〕授权令﹐命令﹐训令"},{"en":"the power given to one country to govern another country","cn":"委任统治权﹐托管权"}]},"vocab":{"pos":"1 n v 2 n","senses":[{"en":"A mandate is like an official command or a go-ahead. When a politician wins an election by a lot, that's a mandate for their ideas."}]},"collocations":{"phrases":["ADJ. popular | clear | legal | presidential | electoral It is undemocratic to govern an area without an electoral mandate.","VERB + MANDATE have | give sb, issue | seek The party sought a mandate to reform the constitution. | get, obtain, receive, win | extend, imp","MANDATE + VERB run The mandate ran until 1947.","PREP. in your ~ He failed in his mandate. | under a/the ~ They ruled the country under a United Nations mandate. | with a/the ~ The party wa","PHRASES an extension/a renewal of a mandate"]},"media":{"uk":"media/ldoce/hwd/bre/c/mandate_n0205.mp3","us":"media/ldoce/hwd/ame/e/l3mandate.mp3"},"examples":[{"en":"The election victory gave the party a clear mandate to continue its programme of reform.","cn":"选举获胜使得这个政党拥有了明确的继续推行改革的权力。"},{"en":"The presidential mandate is limited to two terms of four years each.","cn":"总统的任期不得超过两届，每届四年。"}],"oxford":{"phon":"ˈmændeɪt","pos":"noun","senses":[{"en":"the authority to do something, given to a government or other organization by the people who vote for it in an election","cn":"（政府或组织等经选举而获得的）授权","ex":{"en":"It is undemocratic to govern an area without an electoral mandate.","cn":"没有选民授权就统辖一个地区是不民主的。"}},{"en":"the period of time for which a government is given power","cn":"（政府的）任期","ex":{"en":"The presidential mandate is limited to two terms of four years each.","cn":"总统的任期不得超过两届，每届四年。"}},{"en":"an official order given to somebody to perform a particular task","cn":"委托书；授权令","lab":"formal","ex":{"en":"The bank had no mandate to honour the cheque.","cn":"银行没有得到指令来承兑这张支票。"}},{"en":"the power given to a country to govern another country or region, especially in the past","cn":"（尤指旧时授予某国对别国或地区的）委任统治权","ex":{"en":"The Cook Islands mandate was given to New Zealand.","cn":"库克群岛托管地授予新西兰。"}},{"en":"to order somebody to behave, do something or vote in a particular way; to order something to be done","cn":"强制执行；命令","lab":"especially North American English","ex":{"en":"The law mandates that imported goods be identified as such.","cn":"法律规定进口货物必须如实标明。"},"pos":"verb"},{"en":"to give somebody, especially a government or a committee, the authority to do something","cn":"授权","g":"[often passive]","ex":{"en":"The assembly was mandated to draft a constitution.","cn":"大会获授权起草一份章程。"},"pos":"verb"}]}},"make-up":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"化妆品","en":"Make-up consists of things such as lipstick, eye shadow, and powder which some women put on their faces to make themselves look more attractive or which actors use to change or improve their appearance.","ex":{"en":"Normally she wore little make-up","cn":"她一般不怎么化妆。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"天性;性格","en":"Some-one's make-up is their nature and the various qualities in their character.","ex":{"en":"There was some fatal flaw in his makeup, and as time went on he lapsed into long silences or became off-hand.","cn":"他的性格有致命的缺陷，随着时间的推移，他陷入了久久的沉默，或者变得漠然。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"组成成分;构成方式","en":"The make-up of something consists of its different parts and the way these parts are arranged.","ex":{"en":"The ideological make-up of the unions is now radically different from what it had been.","cn":"协会的思想观念与过去截然不同。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"coloured substances that are put on your face to improve or change your appearance","cn":"化妆品"},{"en":"creams, powders etc that you use on your face and body in order to look more attractive","cn":""},{"en":"a substance you use for adding colour to your lips, in the shape of a small stick","cn":""}]},"collocations":{"phrases":["ADJ. heavy, thick | eye | stage VERB + MAKE-UP use, wear I never wear make-up. | apply, put on | remove, take off | touch up | smudge MAKE-U","ADJ. genetic, physical, psychological","PHRASES part of sb's make-up Jealousy is not part of his make-up."]},"media":{"uk":"media/ldoce/hwd/bre/8/make_up0205.mp3","us":"media/ldoce/hwd/ame/e/amelasdemake-up.mp3"},"examples":[{"en":"Jealousy is not part of his make-up.","cn":"嫉妒不是他的本质。"},{"en":"She never wears make-up.","cn":"她从来不化妆。"}],"oxford":{"phon":"ˈmeɪk ʌp","pos":"noun","senses":[{"en":"coloured substances used on the skin to make yourself look more attractive or to change your appearance","cn":"化妆品","g":"[uncountable]","lab":"North American English also","ex":{"en":"eye make-up","cn":"眼妆"}},{"en":"the different qualities that combine to form somebody’s character or being","cn":"性格；气质","g":"[singular]","ex":{"en":"Jealousy is not part of his make-up.","cn":"嫉妒不是他的本质。"}},{"en":"the different things, people, etc. that combine to form something; the way in which they combine","cn":"组成成分；构成方式","g":"[singular]","lab":"specialist","ex":{"en":"the make-up of a TV audience","cn":"电视观众的构成"}},{"en":"a special exam taken by students who missed or failed an earlier one","cn":"补考","g":"[countable]","lab":"North American English"}]}},"manifesto":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（尤指政党或政府的）宣言，声明","en":"A manifesto is a statement published by a person or group of people, especially a political party, or a government, in which they say what their aims and policies are.","ex":{"en":"The Tories are currently drawing up their election manifesto","cn":"保守党人目前正在起草竞选宣言。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a written statement by a political party, saying what they believe in and what they intend to do","cn":"宣言"}]},"vocab":{"pos":"n","senses":[{"en":"A manifesto is a public statement stating your views or your intention to do something. If you feel you should be voted \"Most Likely to Succeed,\" you could issue a manifesto describing all the reasons why you deserve to win."}]},"collocations":{"phrases":["ADJ. Conservative, Labour, etc. | party, party's We must all support the party manifesto. | election","VERB + MANIFESTO draft, draw up, write | sign | issue, launch, publish | support","MANIFESTO + VERB pledge sth, promise sth The manifesto promised reform of the social security system. | call for sth, demand sth | contain s","MANIFESTO + NOUN commitment, pledge, promise | proposal","PREP. in a/the ~ The policy is outlined in the party's election manifesto. | on a/the ~ Labour won the election on this manifesto. | ~ for a"]},"media":{"uk":"media/ldoce/hwd/bre/4/manifesto0205.mp3","us":"media/ldoce/hwd/ame/0/manifesto.mp3"},"examples":[{"en":"an election manifesto","cn":"竞选宣言"},{"en":"the party manifesto","cn":"政党宣言"}],"oxford":{"phon":"ˌmænɪˈfestəʊ","pos":"noun","senses":[{"en":"a written statement in which a group of people explain their beliefs and aims, especially one published by a political party to say what they will do if they win an election","cn":"宣言（尤指政党竞选纲领）","ex":{"en":"an election manifesto","cn":"竞选宣言"}}]}},"malice":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"恶意;怨恨","en":"Malice is behaviour that is intended to harm people or their reputations, or cause them embarrassment and upset.","ex":{"en":"There was a strong current of malice in many of his portraits","cn":"他的许多肖像画中都透着一股强烈的怨恨。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the desire to harm someone because you hate them","cn":"恶意﹔害人之心"},{"en":"with the deliberate intention of doing something that is against the law 〔","cn":"犯罪〕蓄意地﹐恶意地"}]},"vocab":{"pos":"n","senses":[{"en":"Malice is the intention to cause harm. If someone feels malice toward you, look out! They've got bad intentions."}]},"collocations":{"phrases":["ADJ. pure, sheer","VERB + MALICE bear (sb), feel, have He bore me no malice. She felt no malice. She has no malice in her.","PREP. out of ~ She sacked him out of sheer malice. | with/without ~ &lsquo;You're lying,&rsquo; he said, without malice. | ~ towards I bear "]},"media":{"uk":"media/ldoce/hwd/bre/a/malice0205.mp3","us":"media/ldoce/hwd/ame/7/malice.mp3"},"examples":[{"en":"He certainly bears you no malice (= does not want to harm you).","cn":"他对你一定不会有什么恶意。"},{"en":"He sent the letter out of malice.","cn":"他出于恶意寄出了这封信。"}],"oxford":{"phon":"ˈmælɪs","pos":"noun","senses":[{"en":"a desire to harm somebody caused by a feeling of hate","cn":"恶意；怨恨","ex":{"en":"She is entirely without malice.","cn":"她完全没有恶意。"}}]}},"massacre":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"大屠杀;大残杀","en":"A massacre is the killing of a large number of people at the same time in a violent and cruel way. →see usage note at:","ex":{"en":"Maria lost her 62-year-old mother in the massacre.","cn":"在大屠杀中玛丽亚失去了62岁的母亲。"}},{"pos":"VERB 动词","cn":"大规模屠杀;大规模残杀","en":"If people are massacred, a large number of them are attacked and killed in a violent and cruel way.","ex":{"en":"300 civilians are believed to have been massacred by the rebels","cn":"据信有300位平民被叛乱分子残杀。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"when a large number of people are easily killed, because they are not able to defend themselves","cn":""},{"en":"when a large number of people are killed in a very cruel or violent way","cn":""},{"en":"when a large number of people are violently killed, especially in a war - used especially in newspapers","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"A massacre is a big bloody mess of killing, and usually for no good reason. Not that there’s ever a good reason for killing, but massacres are especially pointless and gory."}]},"collocations":{"phrases":["ADJ. appalling, bloody, cold-blooded, horrible, terrible an appalling massacre of women and children","VERB + MASSACRE be responsible for, carry out, perpetrate, take part in The massacre was carried out by enemy troops. As many as fifty men t","MASSACRE + VERB take place","PREP. ~ by a massacre by rebel soldiers","PHRASES the victims of a massacre"]},"media":{"uk":"media/ldoce/hwd/bre/2/massacre_n0205.mp3","us":"media/ldoce/hwd/ame/d/massacre1.mp3"},"examples":[{"en":"The game was a 10–0 massacre for our team.","cn":"这场比赛我们队以 0:10 惨败。"},{"en":"the bloody massacre of innocent civilians","cn":"对无辜平民的血腥屠杀"}],"oxford":{"phon":"ˈmæsəkə(r)","pos":"noun","senses":[{"en":"the killing of a large number of people especially in a cruel way","cn":"屠杀；残杀","ex":{"en":"the bloody massacre of innocent civilians","cn":"对无辜平民的血腥屠杀"}},{"en":"a very big defeat in a game or competition","cn":"（运动或比赛中的）惨败","lab":"informal","ex":{"en":"The game was a 10–0 massacre for our team.","cn":"这场比赛我们队以 0:10 惨败。"}},{"en":"to kill a large number of people, especially in a cruel way","cn":"屠杀；杀戮","ex":{"en":"Hundreds of innocent women and children were massacred.","cn":"数百名无辜的妇女和儿童惨遭杀戮。"},"pos":"verb"},{"en":"to defeat somebody in a game or competition by a high score","cn":"（在运动或比赛中）使惨败","lab":"informal","ex":{"en":"Our team was massacred in the final.","cn":"我们队在决赛中惨遭屠杀。"},"pos":"verb"}]}},"manifestation":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"表现;显示;表示","en":"A manifestation of something is one of the different ways in which it can appear.","ex":{"en":"Different animals in the colony had different manifestations of the disease","cn":"在这一群体里，这种疾病在不同的动物身上有着不同的表现。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an event or fact that shows that something is true or that something is happening","cn":""},{"en":"something, especially someone's behaviour or what they say, that makes you believe that something is probably happening or has probably happened","cn":""},{"en":"facts, objects etc that show that something exists or is true","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"A manifestation is the public display of emotion or feeling, or something theoretical made real."}]},"collocations":{"phrases":["ADJ. concrete, physical, visible | obvious | public the public manifestation of private grief","PREP. ~ in The manifestation of the disease in adults is less dramatic.","PHRASES in all its manifestations combating racism in all its manifestations"]},"media":{"uk":"media/ldoce/hwd/bre/4/manifestation0205.mp3","us":"media/ldoce/hwd/ame/2/manifestation.mp3"},"examples":[{"en":"The riots are a clear manifestation of the people's discontent.","cn":"骚乱清楚地表明了人们的不满情绪。"},{"en":"Some manifestation of your concern would have been appreciated.","cn":"你当时要是表现出一些关心就好了。"}],"oxford":{"phon":"ˌmænɪfeˈsteɪʃn","pos":"noun","senses":[{"en":"an event, action or thing that is a sign that something exists or is happening; the act of appearing as a sign that something exists or is happening","cn":"显示；表明；表示","g":"[countable, uncountable]","ex":{"en":"The riots are a clear manifestation of the people's discontent.","cn":"骚乱清楚地表明了人民的不满情绪。"}},{"en":"an appearance of a ghost or spirit","cn":"（幽灵的）显现，显灵","g":"[countable]","ex":{"en":"The church is the site of a number of supernatural manifestations.","cn":"这座教堂是个鬼魂屡次出没的地方。"}}]}},"mater":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"mother – now used humorously","cn":"母亲﹐妈妈〔现作幽默用法〕"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41mater.mp3","us":"media/ldoce/hwd/ame/5/ld41mater.mp3"},"oxford":{"phon":"ˈmɑːtə(r)","pos":"noun","senses":[{"en":"mother","cn":"妈；妈妈"}]}},"martyr":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"殉道者;殉教者;烈士","en":"A martyr is someone who is killed or made to suffer greatly because of their religious or political beliefs, and is admired and respected by people who share those beliefs.","ex":{"en":"...a glorious martyr to the cause of liberty.","cn":"为自由事业光荣献身的烈士"}},{"pos":"VERB 动词","cn":"(因宗教或政治信仰)处死，使殉难，折磨","en":"If someone is martyred, they are killed or made to suffer greatly because of their religious or political beliefs.","ex":{"en":"St Pancras was martyred in 304 AD.","cn":"圣潘克拉斯于公元304年殉道。"}},{"pos":"N-COUNT 可数名词","cn":"(为博取同情或赞赏的)假装受苦者，诉苦者，乞怜者","en":"If you refer to someone as a martyr, you disapprove of the fact that they pretend to suffer, or exaggerate their suffering, in order to get sympathy or praise from other people.","ex":{"en":"When are you going to quit acting like a martyr?","cn":"你什么时候才能不再摆出一副可怜样？"}},{"pos":"N-COUNT 可数名词","cn":"深受…之苦者;受…折磨的人","en":"If you say that someone is a martyr to something, you mean that they suffer as a result of it.","ex":{"en":"Ellsworth was a martyr to his sense of honour and responsibility","cn":"埃尔斯沃思深为自己的荣誉感和责任感所累。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"to die in order to save someone, or because of something that you believe in","cn":""},{"en":"someone who is killed because of their religious or political beliefs, and becomes very famous because of this","cn":""},{"en":"someone who attacks and kills people with a bomb etc even though they know they will die as well","cn":""}]},"vocab":{"pos":"n v","senses":[{"en":"Someone who suffers, or is even killed, for his or her political or religious beliefs is called a martyr."}]},"collocations":{"phrases":["ADJ. early | Christian","VERB + MARTYR make sb Killing him would only make him a martyr.","PREP. ~ to a martyr to the cause","PHRASES a martyr's death 2 sb who tries to gain sympathy","VERB + MARTYR play Stop playing the martyr.","PHRASES make a martyr of yourself"]},"media":{"uk":"media/ldoce/hwd/bre/b/martyr_v0205.mp3","us":"media/ldoce/hwd/ame/b/martyr1.mp3"},"examples":[{"en":"a martyr to the cause of freedom","cn":"为了自由事业而献身的烈士"},{"en":"She's a martyr to her nerves.","cn":"她长期忍受神经紧张之苦。"}],"oxford":{"phon":"ˈmɑːtə(r)","pos":"noun","senses":[{"en":"a person who is killed because of their religious or political beliefs","cn":"殉道者；烈士","ex":{"en":"the early Christian martyrs","cn":"早期基督教殉道者"}},{"en":"a person who tries to get sympathy from other people by telling them how much he or she is suffering","cn":"乞怜者（向人诉苦以博取同情）","lab":"usually disapproving","ex":{"en":"He makes a martyr of himself whenever it’s his turn to do the housework.","cn":"他一到做家务的时候就爱装可怜博同情。"}},{"en":"a person who suffers very much because of an illness, problem or situation","cn":"（因疾病或困难局面）长期受苦者，长期受折磨者","lab":"informal","ex":{"en":"She's a martyr to her nerves.","cn":"她长期忍受神经紧张之苦。"}},{"en":"to kill somebody because of their religious or political beliefs","cn":"（因宗教或政治信仰）使殉难，处死","ex":{"en":"Many first-century Christians were martyred for their faith.","cn":"公元1世纪，许多基督徒因信仰而殉道。"},"pos":"verb"}]}},"mania":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"狂热;癖好","en":"If you say that a person or group has a mania for something, you mean that they enjoy it very much or spend a lot of time on it.","ex":{"en":"It seemed to some observers that the English had a mania for travelling","cn":"在某些观察家看来，英国人对旅行似乎抱有一种狂热。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"躁狂症","en":"Mania is a mental illness which causes the sufferer to become very worried or concerned about something.","ex":{"en":"...the treatment of mania","cn":"对躁狂症的治疗"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an unreasonably strong and continuous interest in someone or something, so that you cannot stop thinking about them and your behaviour is seriously affected","cn":""},{"en":"a very strong desire for something or interest in something, especially one that affects a lot of people at the same time","cn":""},{"en":"an unnaturally strong interest in or love for someone or something","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Mania is an extreme interest, desire, or craze. If you dye your dog's fur to match the colors of your favorite football team, you might be suffering from sports mania."}]},"collocations":{"phrases":["ADJ. gambling, railway, sex, etc.","VERB + MANIA have","PREP. ~ for She had a mania for fast cars. 2 serious mental illness","ADJ. collective The violence of the crowd can only be explained as a sign of some collective mania. | religious","VERB + MANIA suffer from","PHRASES a state of mania"]},"media":{"uk":"media/ldoce/hwd/bre/b/mania0205.mp3","us":"media/ldoce/hwd/ame/e/mania.mp3"},"examples":[{"en":"Football mania is sweeping the country.","cn":"足球热正风靡全国。"},{"en":"He had a mania for fast cars.","cn":"他是个飞车狂。"}],"oxford":{"phon":"ˈmeɪniə","pos":"noun","senses":[{"en":"an extremely strong desire or enthusiasm for something, often shared by a lot of people at the same time","cn":"（通常指许多人共有的）强烈的欲望，狂热，极大的热情","g":"[countable, usually singular, uncountable]","ex":{"en":"She attacked fashion's mania for thinness.","cn":"她抨击了时尚界对瘦身的狂热。"}},{"en":"a mental illness in which somebody feels extremely active and excited with a lot of energy, may not feel like sleeping or eating, and may see or believe things that are not real","cn":"躁狂症","g":"[uncountable]","lab":"psychology","ex":{"en":"During periods of mania she felt extremely creative.","cn":"在狂热时期，她感到非常有创造力。"}},{"en":"a mental illness of a particular type","cn":"躁狂症","ex":{"en":"kleptomania","cn":"偷窃癖"},"pos":"combining form"}]}},"massage":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"按摩;推拿","en":"Massage is the action of squeezing and rubbing someone's body, as a way of making them relax or reducing their pain.","ex":{"en":"Alex asked me if I wanted a massage","cn":"亚力克斯问我是否想做按摩。"}},{"pos":"VERB 动词","cn":"为…按摩;给…推拿","en":"If you massage someone or a part of their body, you squeeze and rub their body, in order to make them relax or reduce their pain.","ex":{"en":"She continued massaging her right foot, which was bruised and aching.","cn":"她继续按摩又肿又疼的右脚。"}},{"pos":"VERB 动词","cn":"修改，改动,窜改(数据或证据以掩人耳目)","en":"If you say that someone massages statistics, figures, or evidence, you are criticizing them for changing or presenting the facts in a way that misleads people.","ex":{"en":"Their governments have no reason to 'massage' the statistics.","cn":"他们的政府没有理由“窜改”这些数据。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the action of pressing and rubbing someone’s body with your hands, to help them relax or to reduce pain in their muscles or joints","cn":"按摩﹔推拿"},{"en":"to press and rub someone’s body with your hands, to help them relax or to reduce pain in their muscles","cn":"为…按摩﹐给…推拿"},{"en":"to change official numbers or information in order to make them seem better than they are – used to show disapproval","cn":"篡改〔官方数字或资料﹔含贬义〕"}]},"vocab":{"pos":"n v","senses":[{"en":"When someone rubs your muscles to help relax them, that's a massage . Feels good, doesn't it? When someone tells you how great you are to gain favor, they massage your ego. Not bad, either."}]},"collocations":{"phrases":["ADV. firmly, vigorously | gently, lightly","PREP. into Gently massage the cream into your skin. | with He massaged her back with scented oil. Massage it lightly with your fingertips."]},"media":{"uk":"media/ldoce/hwd/bre/5/massage_v0205.mp3","us":"media/ldoce/hwd/ame/3/massage1.mp3"},"examples":[{"en":"He massaged the aching muscles in her feet.","cn":"他给她按摩脚上疼痛的肌肉。"},{"en":"The government was accused of massaging the unemployment figures.","cn":"政府被指责谎报了失业数字。"}],"oxford":{"phon":"ˈmæsɑːʒ","pos":"noun","senses":[{"en":"the action of rubbing and pressing a person’s body with the hands, especially to reduce pain in the muscles and joints","cn":"按摩","ex":{"en":"Massage will help the pain.","cn":"按摩能减轻疼痛。"}},{"en":"to rub and press a person’s body with the hands, especially to reduce pain in the muscles and joints","cn":"按摩；推拿","ex":{"en":"He massaged the aching muscles in her feet.","cn":"他给她按摩脚上疼痛的肌肉。"},"pos":"verb"},{"en":"to rub a substance into the skin, hair, etc.","cn":"用…揉擦（皮肤、头发等）","ex":{"en":"Massage the cream into your skin.","cn":"将护肤霜揉擦到皮肤上。"},"pos":"verb"},{"en":"to change facts, figures, etc. in order to make them seem better than they really are","cn":"美化（事实）；虚报（数量）；粉饰","lab":"disapproving","ex":{"en":"The government was accused of massaging the unemployment figures.","cn":"政府被指责谎报了失业数字。"},"pos":"verb"}]}},"masochism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"性受虐狂","en":"Masochism is behaviour in which someone gets sexual pleasure from their own pain or suffering.","ex":{"en":"The tendency towards masochism is however always linked with elements of sadism.","cn":"不过，性受虐狂的倾向中总是有一些施虐的成分。"}},{"pos":"N-UNCOUNT 不可数名词","cn":"自虐狂;受虐狂","en":"If you describe someone's behaviour as masochism, you mean that they seem to be trying to get into a situation which causes them suffering or great difficulty.","ex":{"en":"Once you have tasted life in southern California, it takes a peculiar kind of masochism to return to a British winter.","cn":"一旦体验过南加州的生活，再重返寒冬腊月里的英国就有点自讨苦吃。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"use this humorously about someone who seems to like being put in situations where they will suffer, when it could have been avoided","cn":""},{"en":"someone who enjoys suffering because they make other people feel guilty about it, and therefore get sympathy and attention","cn":""},{"en":"sexual behaviour in which someone gains pleasure from being hurt or punished","cn":"性受虐癖"}]},"vocab":{"pos":"n","senses":[{"en":"Someone into masochism gets sexual pleasure from being hurt: they are turned on by pain."}]},"collocations":{"phrases":["ADJ. pure, sheer","QUANT. streak, touch There's a streak of masochism in his personality.","PHRASES a form of masochism"]},"media":{"uk":"media/ldoce/hwd/bre/b/masochism0205.mp3","us":"media/ldoce/hwd/ame/8/masochism.mp3"},"examples":[{"en":"You spent the whole weekend in a tent in the rain? That's masochism!","cn":"下着雨，你就在帐篷里度过了整个周末？真是自讨苦吃！"},{"en":"masochistic behaviour/tendencies","cn":"受虐狂行为/倾向"}],"oxford":{"phon":"ˈmæsəkɪzəm","pos":"noun","senses":[{"en":"the practice of getting sexual pleasure from being hurt or controlled by somebody else","cn":"性受虐狂"},{"en":"pleasure in something that most people would find unpleasant or painful","cn":"受虐狂","lab":"informal","ex":{"en":"You spent the whole weekend in a tent in the rain? That's masochism!","cn":"下着雨，你就在帐篷里度过了整个周末？真是自讨苦吃！"}}]}},"marvellous":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"绝妙的;非凡的;不可思议的","en":"If you describe someone or something as marvellous, you are emphasizing that they are very good.","ex":{"en":"He certainly is a marvellous actor","cn":"他真是个很棒的演员。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"extremely good, in a way that makes you feel excited and happy – used mainly in spoken English","cn":""},{"en":"extremely good – used mainly in spoken English","cn":""},{"en":"extremely good – used especially about the quality of something. Excellent is more formal than fantastic/terrific or great , and is used in both spoken and written English","cn":""}]},"collocations":{"phrases":["VERBS be, feel, look, sound","ADV. bloody (taboo, ironic) , really This is really marvellous news! | absolutely, quite, simply The food looks absolutely marvellous! | pre"]},"media":{"uk":"media/ldoce/hwd/bre/5/marvellous0205.mp3","us":"media/ldoce/hwd/ame/1/laadmarvellous.mp3"},"examples":[{"en":"It's marvellous what modern technology can do.","cn":"现代技术所能做的真是太了不起了。"},{"en":"This will be a marvellous opportunity for her.","cn":"这对她可是千载难逢的机会。"}],"oxford":{"phon":"ˈmɑːvələs","pos":"adjective","senses":[{"en":"extremely good; wonderful","cn":"极好的；非凡的","ex":{"en":"This will be a marvellous opportunity for her.","cn":"这对她可是千载难逢的机会。"}}]}},"masterpiece":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"杰作;名著","en":"A masterpiece is an extremely good painting, novel, film, or other work of art.","ex":{"en":"His book, I must add, is a masterpiece.","cn":"我必须补充一点：他的书是一部杰作。"}},{"pos":"N-COUNT 可数名词","cn":"(画家、作家或作曲家的)最佳作品，代表作","en":"An artist's, writer's, or composer's masterpiece is the best work that they have ever produced."},{"pos":"N-COUNT 可数名词","cn":"典范","en":"A masterpiece is an extremely clever or skilful example of something.","ex":{"en":"The whole thing was a masterpiece of crowd management.","cn":"整件事情就是人群管理的典范。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a picture, sculpture, piece of music etc","cn":""},{"en":"something produced by an artist, especially something that most people agree is of very high quality","cn":""},{"en":"a picture, sculpture, film etc that is of extremely high quality, especially one that is believed to be the best work of a particular artist","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Many people have to agree that a painting or a novel is wonderful, and they usually need to feel that way for years, in order for it to be considered a true masterpiece ."}]},"collocations":{"phrases":["ADJ. great It's one of the greatest masterpieces of Western art. | minor | architectural, literary, musical","VERB + MASTERPIECE create, produce | be considered, be hailed as, be recognized as Within a week of publication, the novel was hailed as a m","PREP. ~ by a masterpiece by Picasso | ~ of a masterpiece of classical architecture • Note at ART"]},"media":{"uk":"media/ldoce/hwd/bre/3/masterpiece0205.mp3","us":"media/ldoce/hwd/ame/6/masterpiece.mp3"},"examples":[{"en":"The museum houses several of his Cubist masterpieces.","cn":"博物馆收藏了他的几件立体派杰作。"},{"en":"Her work is a masterpiece of (= an excellent example of) simplicity.","cn":"她的作品是朴实的典范。"}],"oxford":{"phon":"ˈmɑːstəpiːs","pos":"noun","senses":[{"en":"a work of art such as a painting, film, book, etc. that is an excellent, or the best, example of the artist’s work","cn":"代表作；杰作；名著","ex":{"en":"The museum houses several of his Cubist masterpieces.","cn":"博物馆收藏了他的几件立体派杰作。"}},{"en":"a US television series on PBS showing many of the best British programmes. It was formerly known as Masterpiece Theater. It began in 1971 and was presented by Alistair Cooke until 1994. The programmes have included Upstairs, Downstairs (1974-7), The Jewel in the Crown (1984) and recently Downton Abbey (from 2011).","cn":"杰作：美国PBS电视连续剧，播放了许多英国最好的节目。它以前被称为杰作剧院。它始于1971年，一直由Alistair Cooke提出，一直持续到1994年。这些节目包括Upstairs，Downstairs（1974-7），The Jewel in the Crown（1984）和最近的Downton Abbey（从2011年开始）。","pos":""}]}},"mannerism":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（某人特有的说话或动作的）习性，习气，习惯","en":"Someone's mannerisms are the gestures or ways of speaking which are very characteristic of them, and which they often use.","ex":{"en":"His mannerisms are more those of a preoccupied math professor","cn":"他的举手投足更像是一个全神贯注的数学教授。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"something you do regularly, often without thinking about it","cn":""},{"en":"a way of speaking or a small movement of your face or body that is part of your usual behaviour","cn":""},{"en":"something that people in a particular society do because it is traditional or the accepted thing to do","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Does someone you know always shrug in a particular way or say \"You know what I mean?\" at the end of every sentence? Well, that's a mannerism , a habitual gesture or way of speaking."}]},"collocations":{"phrases":["ADJ. odd | irritating","VERB + MANNERISM have | acquire, adopt","PREP. ~ of He has this irritating mannerism of constantly scratching his nose."]},"media":{"uk":"media/ldoce/hwd/bre/d/mannerism0205.mp3","us":"media/ldoce/hwd/ame/2/mannerism.mp3"},"examples":[{"en":"nervous/odd/irritating mannerisms","cn":"紧张的/古怪的/令人不快的习惯"},{"en":"He has the same mannerisms as his father.","cn":"他举手投足跟他父亲一样。"}],"oxford":{"phon":"ˈmænərɪzəm","pos":"noun","senses":[{"en":"a particular habit or way of speaking or behaving that somebody has but is not aware of","cn":"习性；言谈举止","g":"[countable]","ex":{"en":"nervous/odd/irritating mannerisms","cn":"紧张的／古怪的／令人不快的习惯"}},{"en":"too much use of a particular style in painting or writing","cn":"（绘画、写作中）过分的独特风格","g":"[uncountable]"},{"en":"a style in 16th century Italian art that did not show things in a natural way but made them look strange or out of their usual shape","cn":"风格主义，矫饰主义（16 世纪意大利的一种艺术风格，以怪诞、变形的方式表现事物）","g":"[uncountable]"}]}},"mat":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(杯、盘的)垫,垫子","en":"A mat is a small piece of something such as cloth, card, or plastic which you put on a table to protect it from plates or cups.","ex":{"en":"The food is served on polished tables with mats.","cn":"饭菜摆放在擦得铮亮、铺着衬垫的餐桌上。"}},{"pos":"N-COUNT 可数名词","cn":"地毯;地垫;地席","en":"A mat is a small piece of carpet or other thick material which is put on the floor for protection, decoration, or comfort.","ex":{"en":"There was a letter on the mat","cn":"地毯上有一封信。"}},{"pos":"N-COUNT 可数名词","cn":"一簇;一丛;一团","en":"A mat of something such as grass or moss is a thick, untidy layer of it.","ex":{"en":"The houses are well spaced out, each on its own plot of ground and mat of coarse grass","cn":"房屋稀稀疏疏地坐落着，每栋都有自己的一片地和粗草坪。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a small piece of thick rough material which covers part of a floor","cn":"地垫﹔地席﹔蒲席"},{"en":"a small flat piece of wood, cloth etc which protects a surface, especially on a table 〔","cn":"尤指用以保护桌面的木质或布质〕小垫子"},{"en":"a piece of thick soft material used in some activities for people to sit on, fall onto etc 〔","cn":"某些活动用的〕厚软垫"}]},"vocab":{"pos":"1 n 2 n v 3 n v adj","senses":[{"en":"When you walk into someone else's house, it's polite to wipe your feet on the mat — the pad that covers part of the floor inside the front door."}]},"collocations":{"phrases":["ADJ. dense, thick a thick mat of hair","PREP. ~ of the dense mat of roots at the bottom of the tree"]},"media":{"img":["media/ldoce/img/rug.jpg"],"uk":"media/ldoce/hwd/bre/a/mat_n0205.mp3","us":"media/ldoce/hwd/ame/c/mat1.mp3"},"examples":[{"en":"Wipe your feet on the mat before you come in, please.","cn":"请在垫子上擦擦脚再进来。"},{"en":"a judo/an exercise mat","cn":"柔道垫；健身垫"}],"oxford":{"phon":"mæt","pos":"noun","senses":[{"en":"a small piece of thick carpet or strong material that is used to cover part of a floor","cn":"小地毯；垫子","ex":{"en":"Wipe your feet on the mat before you come in, please.","cn":"请在垫子上擦擦脚再进来。"}},{"en":"a piece of thick material such as rubber or plastic used especially in some sports for people to lie on or fall onto","cn":"（体育运动用的）厚垫子","ex":{"en":"a judo/an exercise mat","cn":"柔道垫；健身垫"}},{"en":"a small piece of plastic, wood or cloth used on a table for decoration or to protect the surface from heat or damage","cn":"（装饰或保护桌面的）衬垫，小垫"},{"en":"a thick mass of something that is stuck together","cn":"团；簇；丛","ex":{"en":"a mat of hair","cn":"一团毛发"}},{"en":"not shiny","cn":"不光亮的；无光泽的；亚光的","pos":"adjective"}]}},"marvel":{"collins":{"senses":[{"pos":"VERB 动词","cn":"惊讶不已;不胜惊羡;大为赞叹","en":"If you marvel at something, you express your great surprise, wonder, or admiration.","ex":{"en":"Her fellow members marveled at her seemingly infinite energy","cn":"她的同事们对她似乎无穷的精力大为惊叹。"}},{"pos":"N-COUNT 可数名词","cn":"不可思议的事(或人);奇迹","en":"You can describe something or someone as a marvel to indicate that you think that they are wonderful.","ex":{"en":"The whale, like the dolphin, has become a symbol of the marvels of creation","cn":"鲸和海豚一样，已经成为造物杰作的象征。"}},{"pos":"N-COUNT 可数名词","cn":"奇迹;令人惊奇的成就","en":"Marvels are things that people have done, or that have happened, which are very unexpected or surprising.","ex":{"en":"She almost died, but the hospital's skill achieved great marvels","cn":"她已经奄奄一息，但是医院的技术却创造了伟大的奇迹。"}}]},"ldoce":{"phon":"hwd","pos":"verb","senses":[{"en":"to feel or express great surprise or admiration at something, especially someone’s behaviour 〔","cn":"尤指对他人的行为〕感到惊讶﹐钦佩﹔赞美"},{"en":"something or someone that is extremely useful or skilful","cn":"十分有用[灵巧]的物[人]"}]},"vocab":{"pos":"v n","senses":[{"en":"The Latin source of the word marvel is mirari , \"to wonder at,\" and that's exactly what marvel means when it's a verb. You may marvel at the depth of the Grand Canyon or at the size of a pimple."}]},"collocations":{"phrases":["VERB + MARVEL can/could only One can only marvel at the way the building has been constructed. | never cease to I never cease to marvel at h","PREP. at He marvelled at how easy it was to make money."]},"media":{"uk":"media/ldoce/hwd/bre/c/marvel_v0205.mp3","us":"media/ldoce/hwd/ame/3/marvel1.mp3"},"examples":[{"en":"Everyone marvelled at his courage.","cn":"人人都对他的勇气惊叹不已。"},{"en":"The doctors have done marvels for her.","cn":"医生为她创造了奇迹。"}],"oxford":{"phon":"ˈmɑːvl","pos":"noun","senses":[{"en":"a wonderful and surprising person or thing","cn":"令人惊异的人（或事）；奇迹","ex":{"en":"the marvels of nature/technology","cn":"大自然的／技术的奇迹"}},{"en":"wonderful results or things that have been achieved","cn":"不平凡的成果；成就；奇迹","g":"[plural]","ex":{"en":"The doctors have done marvels for her.","cn":"医生为她创造了奇迹。"}},{"en":"to be very surprised or impressed by something","cn":"感到惊奇；大为赞叹","ex":{"en":"Everyone marvelled at his courage.","cn":"人人都对他的勇气惊叹不已。"},"pos":"verb"}]}},"marathon":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"马拉松赛跑(全程26英里，约合42公里)","en":"A marathon is a race in which people run a distance of 26 miles, which is about 42 km.","ex":{"en":"...running in his first marathon","cn":"参加他生平第一次马拉松比赛"}},{"pos":"ADJ 形容词","cn":"马拉松式的;漫长而累人的;耗时费力的","en":"If you use marathon to describe an event or task, you are emphasizing that it takes a long time and is very tiring.","ex":{"en":"People make marathon journeys to buy glass here.","cn":"人们千里迢迢赶到这里购买玻璃。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a long race of about 26 miles or 42 kilometres","cn":"马拉松赛跑〔全程约26英里或42公里〕"},{"en":"an activity that continues for a long time and needs a lot of energy, patience, or determination 〔","cn":"需要很大精力﹑耐心或决心的〕持久活动﹐马拉松式活动"},{"en":"continuing for a long time","cn":""}]},"collocations":{"phrases":["ADJ. half, full","VERB + MARATHON prepare for, train for | compete in, run, take part in | complete, finish | win","MARATHON + NOUN champion, runner | racing, running He says that he keeps fit by marathon running. 2 long activity","ADJ. 12-hour, 700-mile, etc. | car, cycling, etc.","MARATHON + NOUN journey, walk | effort | match, race a marathon five-set tennis match"]},"media":{"uk":"media/ldoce/hwd/bre/3/brelasdemarathon.mp3","us":"media/ldoce/hwd/ame/f/marathon1.mp3"},"examples":[{"en":"a marathon journey lasting 56 hours","cn":"持续了 56 小时的马拉松式的旅程"},{"en":"The interview was a real marathon.","cn":"这次面试真是一场马拉松。"}],"oxford":{"phon":"ˈmærəθən","pos":"adjective","senses":[{"en":"lasting a long time and requiring a lot of effort, concentration, etc.","cn":"马拉松式的活动（或工作）","ex":{"en":"a marathon journey lasting 56 hours","cn":"56 小时的漫长旅程"}},{"en":"a long running race of about 42 kilometres or 26 miles","cn":"马拉松赛跑（距离约 42 公里，合 26 英里）","ex":{"en":"the London marathon","cn":"伦敦马拉松赛跑"},"pos":"noun"},{"en":"an activity or a piece of work that lasts a long time and requires a lot of effort, concentration, etc.","cn":"马拉松式的活动（或工作）","ex":{"en":"The interview was a real marathon.","cn":"这次面试真是一场马拉松。"},"pos":"noun"}]}},"magical":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"施魔法的;产生魔力的","en":"Something that is magical seems to use magic or to be able to produce magic.","ex":{"en":"...the story of Sin-Sin, a little boy who has magical powers.","cn":"一个有魔力的小男孩辛辛的故事"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"（地方或物体）奇妙的，神奇的","en":"You can say that a place or object is magical when it has a special mysterious quality that makes it seem wonderful and exciting.","ex":{"en":"The beautiful island of Cyprus is a magical place to get married.","cn":"美丽的塞浦路斯岛是缔结良缘的美妙之地。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"very enjoyable, exciting, or romantic, in a strange or special way","cn":"奇异的﹐美妙的﹐迷人的"},{"en":"relating to magic or able to do magic","cn":"魔法的﹔能变魔术的"}]},"collocations":{"phrases":["VERBS be | find sth","ADV. truly, very a truly magical experience | quite, totally | almost Her beauty had an almost magical quality."]},"media":{"uk":"media/ldoce/hwd/bre/e/magical0205.mp3","us":"media/ldoce/hwd/ame/0/magical.mp3"},"examples":[{"en":"Her words had a magical effect on us.","cn":"她的话对我们有一种魔力般的作用。"},{"en":"We spent a magical week in Paris.","cn":"我们在巴黎度过了十分愉快的一周。"}],"oxford":{"phon":"ˈmædʒɪkl","pos":"adjective","senses":[{"en":"containing magic; used in magic","cn":"有魔力的；用于巫术的","ex":{"en":"magical powers","cn":"魔力"}},{"en":"wonderful; extremely pleasant","cn":"奇妙的；极其愉快的","lab":"informal","ex":{"en":"a truly magical feeling","cn":"真正奇妙的感觉"}}]}},"mascara":{"collins":{"senses":[{"pos":"N-MASS 物质名词","cn":"睫毛油;睫毛膏","en":"Mascara is a substance used as make-up to make eyelashes darker.","ex":{"en":"...water-resistant mascaras.","cn":"防水睫毛膏"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"coloured substances that are put on your face to improve or change your appearance","cn":""},{"en":"creams, powders etc that you use on your face and body in order to look more attractive","cn":""},{"en":"a substance you use for adding colour to your lips, in the shape of a small stick","cn":""}]},"collocations":{"phrases":["ADJ. thick | waterproof","VERB + MASCARA wear | apply, put on | remove | smudge Her tears had smudged her mascara.","MASCARA + VERB run, smudge","MASCARA + NOUN brush, wand"]},"media":{"uk":"media/ldoce/hwd/bre/9/mascara0205.mp3","us":"media/ldoce/hwd/ame/9/mascara.mp3","img":["media/thumb/mascara.jpg"]},"oxford":{"phon":"mæˈskɑːrə","pos":"noun","senses":[{"en":"a type of make-up that is put on eyelashes to make them look dark and thick","cn":"睫毛膏","ex":{"en":"waterproof mascara","cn":"防水睫毛膏"}}]}},"maxim":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"信条;格言;箴言","en":"A maxim is a rule for good or sensible behaviour, especially one in the form of a saying.","ex":{"en":"I believe in the maxim 'if it ain't broke, don't fix it'.","cn":"我相信这样一条箴言：“不破不修”。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a well-known phrase or saying, especially one that gives a rule for sensible behaviour","cn":"箴言﹐格言"}]},"vocab":{"pos":"n","senses":[{"en":"A maxim is a succinct formulation of a principle, rule, or basic truth about life. Usually clever, maxims are like great sayings everybody knows. Ben Franklin is the author of many, including \"Early to bed, early to rise, makes a man healthy, wealthy, and wise.\""}]},"collocations":{"phrases":["ADJ. general, simple","VERB + MAXIM apply, follow If you follow a few simple maxims, your business should be a success."]},"media":{"uk":"media/ldoce/hwd/bre/1/maxim0205.mp3","us":"media/ldoce/hwd/ame/d/maxim.mp3"},"oxford":{"phon":"ˈmæksɪm","pos":"noun","senses":[{"en":"a well-known phrase that expresses something that is usually true or that people think is a rule for sensible behaviour","cn":"格言；箴言；座右铭","ex":{"en":"There is some truth in the old maxim, ‘You get what you pay for.’","cn":"常言说得好：“一分钱一分货。”"}}]}},"madison":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"the capital city of the US state of Wisconsin","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/7/p028-000186505.mp3","us":"media/ldoce/hwd/ame/1/l2madison.mp3"},"oxford":{"phon":"ˈmædɪsn","pos":"noun","senses":[{"en":"a bicycle race for teams of two or more riders, in which the riders in each team take turns to ride","cn":"麦迪逊：两个或两个以上车手的自行车比赛，其中每个车队的车手轮流骑行"},{"en":"the capital of the US state of Wisconsin","cn":"麦迪逊（美国威斯康星州首府）","pos":""},{"en":"a first name for girls","cn":"麦迪逊（女子名）","lab":"especially North American English","pos":""}]}},"maid":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（家庭）女佣;（旅馆）侍女","en":"A maid is a woman who works as a servant in a hotel or private house.","ex":{"en":"A maid brought me breakfast at half past eight.","cn":"8点半女佣给我送来了早餐。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a female servant, especially in a large house or hotel 〔","cn":"尤指大宅或酒店的〕女仆"},{"en":"a woman or girl who is not married","cn":"未婚女子﹔姑娘﹐少女"}]},"collocations":{"phrases":["ADJ. dairy, kennel, kitchen, laundry, parlour, scullery | lady's, personal | daily They had a daily maid, but no live-in servants. • Note at"]},"media":{"uk":"media/ldoce/hwd/bre/0/brelasdemaid.mp3","us":"media/ldoce/hwd/ame/a/made1.mp3"},"examples":[{"en":"There is a maid to do the housework.","cn":"有个女仆做家务事。"},{"en":"a kitchen maid","cn":"厨房女佣人"}],"oxford":{"phon":"meɪd","pos":"noun","senses":[{"en":"a female servant in a house or hotel","cn":"女仆；侍女；（旅馆的）女服务员","ex":{"en":"There is a maid to do the housework.","cn":"有个女仆做家务事。"}},{"en":"a young woman who is not married","cn":"少女；年轻姑娘；未婚年轻女子","lab":"old use"}]}},"mainstream":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"（人、活动、思想等的）主流，主要倾向，主要趋势","en":"People, activities, or ideas that are part of the mainstream are regarded as the most typical, normal, and conventional because they belong to the same group or system as most others of their kind.","ex":{"en":"...people outside the economic mainstream","cn":"经济主流之外的人"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the most usual ideas or methods, or the people who have these ideas or methods 〔","cn":"思想或方法的〕主流；主流群体"},{"en":"ordinary things are not special or unusual","cn":""},{"en":"something that is normal is just as you would expect it to be, because it is not special or different","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Mainstream describes what's viewed by most people in a society as \"normal,\" like the mainstream view that everyone should get married, move to the suburbs, and have children as soon as they can."}]},"collocations":{"phrases":["ADJ. cultural, educational, political, etc.","VERB + MAINSTREAM enter, join | cut sb/sth off from, exclude sb/sth from These teachers have been cut off from the mainstream of educational","MAINSTREAM + NOUN society | education, schools | parties, politics | art, cinema | media","PREP. in/within the ~ He was in the mainstream of British contemporary music. | into the ~ This technology was designed for specialists but ","PHRASES part of the mainstream This style of drama is not part of the mainstream."]},"media":{"uk":"media/ldoce/hwd/bre/8/mainstream_v0205.mp3","us":"media/ldoce/hwd/ame/a/mainstream1.mp3"},"examples":[{"en":"His radical views place him outside the mainstream of American politics.","cn":"他的激进观点使他脱离了美国政治的主流。"},{"en":"Vegetarianism has been mainstreamed.","cn":"素食主义已为大多数人所接受。"}],"oxford":{"phon":"ˈmeɪnstriːm","pos":"noun","senses":[{"en":"the ideas and opinions that are thought to be normal because they are shared by most people; the people whose ideas and opinions are most accepted","cn":"主流思想；主流群体","ex":{"en":"His radical views place him outside the mainstream of American politics.","cn":"他的激进观点使他脱离了美国政治的主流。"}},{"en":"considered normal because it reflects what is done or accepted by most people","cn":"主流的","ex":{"en":"mainstream culture/politics","cn":"主流文化／政治"},"pos":"adjective"},{"en":"mainstream education is for children who do not have any special needs or difficulties","cn":"（教育）主流的（相对特殊教育而言）","pos":"adjective"},{"en":"to make a particular idea or opinion accepted by most people","cn":"使为大多数人所接受","ex":{"en":"Vegetarianism has been mainstreamed.","cn":"素食主义已为大多数人所接受。"},"pos":"verb"},{"en":"to include children with special needs in the same class or school as children who do not have special needs","cn":"让（身心有缺陷的儿童）融入主流教育","lab":"especially North American English","pos":"verb"}]}},"malaria":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"疟疾","en":"Malaria is a serious disease carried by mosquitoes which causes periods of fever."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a disease that is common in hot countries and that you get when a type of mosquito bites you","cn":"疟疾"}]},"vocab":{"pos":"n","senses":[{"en":"Malaria is an infectious disease that spreads through mosquitoes. If you're traveling in a warm-climate area in the tropics, you might be in danger of contracting malaria . Pack your Deep Woods OFF!."}]},"collocations":{"phrases":["ADJ. acute, severe","VERB + MALARIA have, suffer from | catch, contract | carry, transmit Malaria is transmitted by mosquitoes. | treat | eradicate","MALARIA + NOUN sufferer, victim | parasite | vaccine | control, eradication •"]},"media":{"uk":"media/ldoce/hwd/bre/0/malaria0205.mp3","us":"media/ldoce/hwd/ame/1/malaria.mp3"},"examples":[{"en":"malarial insects/patients/regions","cn":"传播疟疾的昆虫；疟疾病人/流行区域"}],"oxford":{"phon":"məˈleəriə","pos":"noun","senses":[{"en":"a serious disease that causes a high temperature and shivering (= shaking of the body) caused by the bite of some types of mosquito","cn":"疟疾","ex":{"en":"An increasing number of malaria cases are reported each year.","cn":"上报的疟疾病例数目逐年增多。"}}]}},"maze":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"迷宫","en":"A maze is a complex system of passages or paths between walls or hedges and is designed to confuse people who try to find their way through it, often as a form of amusement.","ex":{"en":"The palace has extensive gardens, a maze, and tennis courts.","cn":"这座宫殿有几座大花园、一处迷宫和几个网球场。"}},{"pos":"N-COUNT 可数名词","cn":"（街道、房间、地道）错综复杂;迷津","en":"A maze of streets, rooms, or tunnels is a large number of them that are connected in a complicated way, so that it is difficult to find your way through them.","ex":{"en":"The children lead me through the maze of alleys to the edge of the city.","cn":"孩子们领我穿过迷宫一般的街巷，来到城边。"}},{"pos":"N-COUNT 可数名词","cn":"错综复杂的想法;复杂难懂的话题;纷繁复杂的规则","en":"You can refer to a set of ideas, topics, or rules as a maze when a large number of them are related to each other in a complicated way that makes them difficult to understand.","ex":{"en":"The book tries to steer you through the maze of alternative therapies.","cn":"本书旨在就各种非传统疗法为您指点迷津。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a place where it is very easy to become lost, because it has a large number of paths, passages, or narrow streets that cross each other","cn":""},{"en":"a complicated and confusing arrangement of streets, roads etc","cn":"街道[道路]的纵横交错"},{"en":"a large number of rules, instructions etc which are complicated and difficult to understand","cn":"纷繁复杂的事物〔如规则﹑命令等〕"}]},"collocations":{"phrases":["ADJ. complex, intricate, tortuous","VERB + MAZE be/get lost in | find your way through He found his way through the complex maze of corridors.","PREP. in a/the ~, through a/the ~ I followed him through a maze of narrow alleys. | ~ of I was lost in a maze of passages."]},"media":{"img":["media/ldoce/img/ldoce_220.png"],"uk":"media/ldoce/hwd/bre/1/maize0205.mp3","us":"media/ldoce/hwd/ame/6/maize.mp3"},"examples":[{"en":"( figurative ) The building is a maze of corridors.","cn":"这座建筑长廊交错，简直就是一座迷宫。"},{"en":"We got lost in the maze.","cn":"我们在迷宫里迷失了方向。"}],"oxford":{"phon":"meɪz","pos":"noun","senses":[{"en":"a system of paths separated by walls or hedges built in a park or garden, that is designed so that it is difficult to find your way through","cn":"迷宫","ex":{"en":"We got lost in the maze.","cn":"我们在迷宫里迷失了方向。"}},{"en":"a complicated network of paths and passages","cn":"错综复杂的路径","ex":{"en":"The building is a maze of corridors.","cn":"这座建筑长廊交错，简直就是一座迷宫。"}},{"en":"a large number of complicated rules or details that are difficult to understand","cn":"纷繁复杂的规则；复杂难懂的细节","g":"[usually singular]","ex":{"en":"Many applicants for the grant are put off by the maze of regulations and conditions.","cn":"许多补助金申请人都因复杂的法规和条件而望而却步。"}},{"en":"a printed puzzle in which you have to draw a line that shows a way through a complicated pattern of lines","cn":"迷宫图","lab":"North American English"}]}},"marquess":{"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a marquis","cn":"侯爵"}]},"media":{"uk":"media/ldoce/hwd/bre/5/ld41marquess.mp3","us":"media/ldoce/hwd/ame/5/ld41marquess.mp3"},"examples":[{"en":"the Marquess of Bath","cn":"巴斯侯爵"}],"oxford":{"phon":"ˈmɑːkwɪs","pos":"noun","senses":[{"en":"(in the UK) a nobleman of high rank between an earl and a duke","cn":"（英国）侯爵","ex":{"en":"the Marquess of Bath","cn":"巴斯侯爵"}}]}},"malnutrition":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"营养不良；营养失调","en":"If someone is suffering from malnutrition, they are physically weak and extremely thin because they have not eaten enough food.","ex":{"en":"Infections are more likely in those suffering from malnutrition.","cn":"营养不良的人更有可能被传染。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"suffering or death caused by not having enough food to eat","cn":""},{"en":"bad health caused by not eating enough food or by not eating enough of the right kinds of food","cn":""},{"en":"a situation in which a large number of people in a country or area are very hungry and many die because the crops of rice, wheat etc have failed","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Malnutrition is a condition resulting from an unbalanced diet or insufficient food. If you live for an entire year on Twinkies and diet soda, you will undoubtedly suffer from malnutrition ."}]},"collocations":{"phrases":["ADJ. severe | chronic | child","VERB + MALNUTRITION suffer (from) | die from/of"]},"media":{"uk":"media/ldoce/hwd/bre/8/malnutrition0205.mp3","us":"media/ldoce/hwd/ame/d/malnutrition.mp3"},"examples":[{"en":"refugees suffering from malnutrition","cn":"营养不良的难民"}],"oxford":{"phon":"ˌmælnjuˈtrɪʃn","pos":"noun","senses":[{"en":"a poor condition of health caused by a lack of food or a lack of the right type of food","cn":"营养不良"}]}},"mary":{"ldoce":{"phon":"hwd","pos":"","senses":[{"en":"in the Christian religion, the mother of Jesus Christ, and the most important of all the saint s . She was the wife of Joseph, but Christians believe she was a virgin (= someone who has never had sex ) , because the father of Jesus is not a human being, but Go","cn":""},{"en":"in the New Testament of the Bible, a woman who lived with her sister, Martha. When Jesus visited them, Mary remained to listen to what he was saying while Martha went and prepared food for him and his disciple s . As a result Mary often represents the type of ","cn":""}]},"media":{"uk":"media/ldoce/hwd/bre/e/lpd_mary.mp3","us":"media/ldoce/hwd/ame/c/p028-000007987.mp3"},"oxford":{"phon":"ˈmeəri","pos":"","senses":[{"en":"a first name for girls","cn":"玛丽（女子名）"}]}},"magnitude":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"巨大;庞大;重要(性)","en":"If you talk about the magnitude of something, you are talking about its great size, scale, or importance.","ex":{"en":"An operation of this magnitude is going to be difficult","cn":"这么大的手术实施起来十分困难。"}},{"pos":"N-VAR 可变名词","cn":"星等(指星的亮度);震级;(爆炸的)强度","en":"Magnitude is used in stating the size or extent of something such as a star, earthquake, or explosion.","ex":{"en":"...the 1.2 magnitude star Fomalhaut","cn":"星等为1.2 的北落师门星"}},{"pos":"PHRASE 短语","cn":"程度;重要性","en":"You can use order of magnitude when you are giving an approximate idea of the amount or importance of something.","ex":{"en":"America and Russia do not face a problem of the same order of magnitude as Japan.","cn":"美俄两国所面临问题的重要性与日本的不可同日而语。"}},{"pos":"PHRASE 短语","cn":"数量级","en":"In mathematics, if one amount is an order of magnitude larger than another, it is ten times larger than the other. If it is two orders of magnitude larger, it is a hundred times larger.","ex":{"en":"The time delay would be smaller by eight orders of magnitude.","cn":"如果按8个数量级来看，延时量会显得小一些。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"use this to talk about or ask about the size of something","cn":""},{"en":"the size of something such as a problem or a change, not of an object, vehicle etc","cn":""},{"en":"how big and important or serious something is","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"Earthquakes have great magnitude in that they are powerful. Their power is rated by their level of magnitude , or how much energy they release relative to other earthquakes."}]},"collocations":{"phrases":["ADJ. considerable, great | sufficient a fall in costs of sufficient magnitude to enable us to reduce prices","PREP. in ~ The effects were substantial in magnitude.","PHRASES of the first magnitude Stars of the first magnitude are visible to the naked eye. a disaster of the first magnitude | (by) an order "]},"media":{"uk":"media/ldoce/hwd/bre/b/magnitude0205.mp3","us":"media/ldoce/hwd/ame/0/magnitude.mp3"},"examples":[{"en":"We did not realize the magnitude of the problem.","cn":"我们没有意识到这个问题的重要性。"},{"en":"The star varies in brightness by about three magnitudes.","cn":"星体的亮度大约分三个星等。"}],"oxford":{"phon":"ˈmæɡnɪtjuːd","pos":"noun","senses":[{"en":"the great size or importance of something; the degree to which something is large or important","cn":"巨大；重大；重要性","g":"[uncountable]","lab":"formal","ex":{"en":"We did not realize the magnitude of the problem.","cn":"我们没有意识到这个问题的重要性。"}},{"en":"the degree to which a star is bright","cn":"星等；星的亮度","g":"[countable, uncountable]","lab":"astronomy","ex":{"en":"The star varies in brightness by about three magnitudes.","cn":"这颗星的亮度大约在三个星等之间变化。"}},{"en":"the size of an earthquake","cn":"震级","g":"[countable, uncountable]","lab":"geology","ex":{"en":"The quake reached a magnitude of 7.1 on the Richter scale.","cn":"地震震级达到里氏7.1级。"}}]}},"marijuana":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"大麻(一种毒品)","en":"Marijuana is a drug which is made from the dried leaves and flowers of the hemp plant, and which can be smoked."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an illegal drug smoked like a cigarette, made from the dried leaves of the hemp plant","cn":"大麻﹐大麻毒品"}]},"vocab":{"pos":"n","senses":[{"en":"Marijuana is a commonly used illegal drug made from dried leaves of the hemp plant. Smoking marijuana creates a high."}]},"collocations":{"phrases":["QUANT. joint","VERB + MARIJUANA smoke","MARIJUANA + NOUN cigarette, joint | plant • Note at DRUG (for more verbs and nouns)"]},"media":{"uk":"media/ldoce/hwd/bre/e/marijuana_las3_br.mp3","us":"media/ldoce/hwd/ame/9/laadmarijuana.mp3"},"oxford":{"phon":"ˌmærəˈwɑːnə","pos":"noun","senses":[{"en":"a drug (illegal in many countries) made from the dried flowers of the cannabis plant, which gives the person smoking it a feeling of being relaxed","cn":"大麻"}]}}});
